/* ============================================================
   Mil Palavras — per-word content (pronunciation, example, note)
   Keyed by the exact Portuguese string. Merged into the cards at
   boot: a card gets .ipa/.ex/.exE/.note/.noteE when its `p` matches.
   European Portuguese throughout. Added in batches, most-common first.
   Pronunciation: English respelling. CAPITALS = the stressed syllable
   (single-syllable words stay lowercase). Nasal sounds are marked
   "(nasal)" — never a trailing g/ng. nh→ny, lh→ly, final -e→uh,
   s→sh before a consonant / at the end.
   ============================================================ */
window.MIL_CONTENT = {
  "a": {"ipa":"ah","ex":"A minha irmã vai a Lisboa amanhã.","exE":"My sister is going to Lisbon tomorrow.","note":"Cuidado: \"a\" é artigo feminino e também preposição de destino. Quando a preposição encontra o artigo feminino, contraem em \"à\" (vou à praia), com acento grave.","noteE":"Two different words spelled the same: the feminine article and the preposition 'to'. When they meet they contract into à with a grave accent (vou à praia = I'm going to the beach)."},
  "a administração": {"ipa":"ah ahd-mee-nish-trah-SOW (nasal)","ex":"Trabalha na administração pública.","exE":"She works in the civil service.","note":"\"Administração pública\" é o equivalente ao serviço público; \"conselho de administração\" é o órgão de direção de uma empresa.","noteE":"Administração pública is the civil service; conselho de administração is a company's board of directors."},
  "a alma": {"ipa":"ah AHL-mah","ex":"Ele canta com muita alma.","exE":"He sings with a lot of soul.","note":"Mantém o artigo \"a\" apesar de começar por a: diz-se \"a alma\". \"Não estava vivalma\" significa que não estava lá ninguém.","noteE":"It keeps the article a even though it starts with a: a alma. The fixed phrase não estava vivalma means there was not a soul there."},
  "a altura": {"ipa":"al-TOO-rah","ex":"Naquela altura eu ainda morava em Lisboa.","exE":"At that time I was still living in Lisbon.","note":"Muito importante em Portugal: \"naquela altura\" e \"nessa altura\" significam \"at that time\", um uso temporal que surpreende quem só conhece o sentido de height.","noteE":"Very important in Portugal: \"naquela altura\" and \"nessa altura\" mean \"at that time\", a use that surprises learners who only know the height meaning."},
  "a amizade": {"ipa":"ah-mee-ZAH-duh","ex":"A nossa amizade já dura vinte anos.","exE":"Our friendship has already lasted twenty years.","note":"A colocação normal é «fazer amizade com alguém», não «ter amizade». «Amigo» é a pessoa; «amizade» é a relação, e nunca se usa para tratar alguém.","noteE":"You \"fazer amizade com\" someone (strike up a friendship). \"Amizade\" is the relationship only — never a way to address a person."},
  "a análise": {"ipa":"ah ah-NAH-lee-zuh","ex":"Amanhã vou fazer análises ao sangue.","exE":"Tomorrow I'm having blood tests done.","note":"No plural, \"análises\" são quase sempre exames médicos ao sangue ou à urina. A sílaba tónica é a antepenúltima, por causa do acento.","noteE":"In the plural, análises almost always means medical blood or urine tests. The accent puts the stress on the third-to-last syllable."},
  "a arte": {"ipa":"AR-tuh","ex":"Ela estuda história da arte em Lisboa.","exE":"She studies art history in Lisbon.","note":"Feminina apesar do -e final. Repara na ordem invertida em relação ao inglês: \"história da arte\" (art history), \"obra de arte\" (work of art).","noteE":"Feminine despite the -e ending. Note the order flips versus English: \"história da arte\" (art history), \"obra de arte\" (work of art)."},
  "a assembleia": {"ipa":"ah ah-se (nasal)-BLAY-ah","ex":"A Assembleia da República aprovou a lei.","exE":"Parliament approved the law.","note":"A Assembleia da República é o parlamento português. Nos prédios, a \"assembleia de condóminos\" é a reunião dos moradores.","noteE":"A Assembleia da República is the Portuguese parliament. In apartment blocks, an assembleia de condóminos is the residents' meeting."},
  "a atenção": {"ipa":"ah-teh (nasal)-SOWN (nasal)","ex":"Presta atenção ao que estou a dizer.","exE":"Pay attention to what I'm saying.","note":"Diz-se «prestar atenção a», nunca «pagar atenção». Sozinho, «Atenção!» significa cuidado.","noteE":"The verb is 'prestar atenção a' — never 'pagar' (a direct calque of 'pay attention'). On its own, 'Atenção!' means 'Careful!'."},
  "a atividade": {"ipa":"ah-tee-vee-DAH-duh","ex":"As crianças fazem atividades ao ar livre.","exE":"The children do outdoor activities.","note":"Depois do Acordo Ortográfico escreve-se sem c: \"atividade\", não \"actividade\". Ainda vais encontrar a grafia antiga em livros mais velhos.","noteE":"Since the spelling reform it is written without the c: \"atividade\", not \"actividade\". You will still meet the old spelling in older books."},
  "a autoridade": {"ipa":"ow-too-ree-DAH-duh","ex":"Ele falou com autoridade sobre o tema.","exE":"He spoke with authority on the subject.","note":"No plural, «as autoridades» refere-se às entidades oficiais (polícia, câmara, etc.).","noteE":"In the plural, 'as autoridades' means the officials — police, council and so on."},
  "a avó": {"ipa":"ah ah-VAW","ex":"A minha avó faz um bolo delicioso.","exE":"My grandmother makes a delicious cake.","note":"O acento agudo abre a vogal, quase como \"aw\" em inglês. Confundir avó com avô é o erro mais comum dos estrangeiros — a diferença é só o acento.","noteE":"The acute accent opens the vowel to an 'aw' sound. Mixing up avó and avô is the classic learner error, and the accent is the only clue."},
  "a ação": {"ipa":"ah-SOW (nasal)","ex":"É preciso passar das palavras à ação.","exE":"We need to go from words to action.","note":"Depois do Acordo Ortográfico escreve-se \"ação\", sem o c mudo de \"acção\". Todas as palavras em -ção são femininas.","noteE":"Since the spelling reform it is \"ação\", without the old silent c of \"acção\". Every -ção noun is feminine."},
  "a barriga": {"ipa":"ah bah-RREE-gah","ex":"Dói-me a barriga desde o almoço.","exE":"My stomach has hurt since lunch.","note":"\"Barriga\" é a palavra do dia a dia; \"o estômago\" é o órgão e \"o abdómen\" é técnico (repare no acento europeu, não \"abdômen\").","noteE":"The everyday word for your belly; o estômago is the actual organ. Note the European spelling abdómen with an acute, not the Brazilian abdômen."},
  "a base": {"ipa":"BAH-zuh","ex":"Com base nisso, decidimos mudar de casa.","exE":"On that basis, we decided to move house.","note":"Guarda duas expressões fixas: \"com base em\" (based on) e \"à base de\" (made with, as in \"um molho à base de natas\").","noteE":"Keep two set phrases: \"com base em\" (based on) and \"à base de\" (made with, as in \"um molho à base de natas\")."},
  "a boca": {"ipa":"ah BOH-kah","ex":"Abre a boca, disse o médico.","exE":"Open your mouth, said the doctor.","note":"\"Boca\" entra em muitas expressões: \"boca do estômago\", \"andar de boca em boca\". Como parte do corpo, leva artigo e não possessivo.","noteE":"Appears in many idioms, e.g. andar de boca em boca ('to be the talk of the town'). Like other body parts it takes the article, not a possessive."},
  "a cabeça": {"ipa":"ah kah-BAY-sah","ex":"Dói-me a cabeça desde manhã.","exE":"I've had a headache since this morning.","note":"\"Ter dor de cabeça\" e \"doer a cabeça\" são ambas corretas. Note-se que é feminina apesar de designar frequentemente um chefe (\"o cabeça de lista\" é masculino).","noteE":"Both ter dor de cabeça and dói-me a cabeça work for 'headache'. The word is feminine, but the figurative o cabeça de lista ('top candidate') is masculine."},
  "a cadeira": {"ipa":"kah-DAY-rah","ex":"Faltam duas cadeiras para todos se sentarem.","exE":"We're two chairs short for everyone to sit down.","note":"Na universidade portuguesa, «uma cadeira» é também uma disciplina do curso — «chumbei a uma cadeira» significa reprovar. «Cadeira de rodas» é a cadeira de rodas.","noteE":"At Portuguese universities a \"cadeira\" is also a course module — \"chumbar a uma cadeira\" is to fail it. \"Cadeira de rodas\" is a wheelchair."},
  "a cama": {"ipa":"KAH-mah","ex":"Faz a cama antes de sair, por favor.","exE":"Make the bed before you leave, please.","note":"Diz-se «fazer a cama» e «ir para a cama» (deitar-se). «Cama de casal» é a cama de duas pessoas e «cama de solteiro» a de uma.","noteE":"You \"fazer a cama\" and \"ir para a cama\" (go to bed). \"Cama de casal\" is a double, \"cama de solteiro\" a single."},
  "a camisa": {"ipa":"kah-MEE-zah","ex":"Ele veste sempre camisa para o trabalho.","exE":"He always wears a shirt to work.","note":"É a camisa com botões e colarinho — a de malha é «camisola» e a de manga curta em algodão é «t-shirt». «Camisa de noite» é a camisa de dormir.","noteE":"This is a button-up shirt with a collar — knitwear is \"camisola\" and a cotton tee is \"t-shirt\". \"Camisa de noite\" is a nightgown."},
  "a camisola": {"ipa":"kah-mee-ZAW-lah","ex":"Leva uma camisola, que está frio.","exE":"Take a jumper, it's cold.","note":"Em Portugal é a peça de malha (jumper/sweatshirt) e também a camisola de uma equipa de futebol. Não é a «camisole» inglesa.","noteE":"In Portugal it is a knitted top (jumper or sweatshirt) and also a football team's jersey. It is not an English \"camisole\"."},
  "a campanha": {"ipa":"kah (nasal)-PAH-nyah","ex":"A campanha eleitoral começa amanhã.","exE":"The election campaign starts tomorrow.","note":"Nada tem a ver com «campo» ou com acampar. Colocações: campanha eleitoral, campanha publicitária.","noteE":"Nothing to do with camping or 'campo' (field). Usual pairings: campanha eleitoral, campanha publicitária."},
  "a capacidade": {"ipa":"kah-pah-see-DAH-duh","ex":"Ele tem capacidade para liderar a equipa.","exE":"He has the ability to lead the team.","note":"Usa-se «capacidade de» ou «capacidade para» + infinitivo; nunca «capacidade a».","noteE":"Take 'de' or 'para' plus an infinitive after it — never 'a'. It covers both human ability and physical capacity."},
  "a cara": {"ipa":"ah KAH-rah","ex":"Tens boa cara hoje!","exE":"You're looking well today!","note":"\"Cara\" é o termo corrente; \"o rosto\" é mais literário e \"a face\" é anatómico. \"Ter cara de\" significa parecer, e \"cara\" é também o feminino de \"caro\" (expensive).","noteE":"The everyday word — rosto is literary and face anatomical. Ter cara de means 'to look like'. Beware: cara is also feminine of caro, 'expensive'."},
  "a característica": {"ipa":"ah kah-rahk-tuh-RISH-tee-kah","ex":"A principal característica dele é a calma.","exE":"His main characteristic is calmness.","note":"O acento cai em -rís-, longe do fim da palavra, e é aí que os estrangeiros costumam errar. O adjetivo é \"característico\".","noteE":"The stress falls on -rís-, far from the end, which is where learners usually go wrong. The adjective is característico."},
  "a carreira": {"ipa":"kah-RRAY-rah","ex":"Ela fez carreira na banca.","exE":"She built a career in banking.","note":"«Fazer carreira» é a colocação habitual. Em transportes, «carreira» é também a linha de autocarro.","noteE":"'Fazer carreira' is the usual collocation. In transport, 'carreira' also means a bus route or service."},
  "a carta": {"ipa":"ah KAR-tah","ex":"Escrevi uma carta à minha avó.","exE":"I wrote a letter to my grandmother.","note":"Carta é a que se envia pelo correio; a letra do alfabeto é \"letra\". Em Portugal, \"a carta\" sozinha costuma referir-se à carta de condução.","noteE":"Carta is the letter you post; a letter of the alphabet is letra. In Portugal carta on its own usually means driving licence."},
  "a casa": {"ipa":"ah KAH-zah","ex":"Vou para casa.","exE":"I'm going home.","note":"'Em casa' = at home, 'para casa' = homewards — sem artigo nestas expressões.","noteE":"'Em casa' = at home, 'para casa' = homewards — no article in these set phrases."},
  "a casa de banho": {"ipa":"KAH-zah duh BAH (nasal)-nyoo","ex":"Desculpe, onde fica a casa de banho?","exE":"Excuse me, where is the bathroom?","note":"É o termo de Portugal; os brasileiros dizem «banheiro», que aqui significa nadador-salvador. Em locais públicos vê-se também «WC» e «lavabos».","noteE":"This is the Portugal term; Brazilians say \"banheiro\", which here means a lifeguard. Public signs also use \"WC\" and \"lavabos\"."},
  "a causa": {"ipa":"KOW-zah","ex":"Chegámos tarde por causa do trânsito.","exE":"We arrived late because of the traffic.","note":"Distingue bem: \"por causa de\" leva substantivo (por causa da chuva) e \"porque\" leva uma frase (porque choveu). Trocá-los é um erro muito comum.","noteE":"Keep them apart: \"por causa de\" takes a noun (por causa da chuva) and \"porque\" takes a clause (porque choveu). Swapping them is a very common mistake."},
  "a cidade": {"ipa":"ah see-DAH-duh","ex":"Lisboa é uma cidade linda.","exE":"Lisbon is a beautiful city.","note":"Feminina; palavras em -dade são sempre femininas (a verdade, a idade).","noteE":"Feminine; nouns ending in -dade are always feminine (a verdade, a idade)."},
  "a ciência": {"ipa":"ah see-E (nasal)-see-ah","ex":"A ciência ainda não tem resposta.","exE":"Science does not have an answer yet.","note":"Leva artigo, ao contrário do inglês. Não confundir com \"consciência\", que significa consciência moral ou o estar consciente.","noteE":"It takes the article, unlike English science. Do not confuse it with consciência, which means conscience or consciousness."},
  "a classe": {"ipa":"ah KLAH-suh","ex":"Viajámos em classe económica.","exE":"We travelled in economy class.","note":"Classe é classe social ou classe de viagem. O grupo de alunos é \"a turma\" e a aula que se assiste é \"a aula\": nunca classe.","noteE":"Classe means social class or travel class. A group of pupils is a turma and a lesson is uma aula, never classe."},
  "a coisa": {"ipa":"ah KOY-zah","ex":"Que coisa estranha!","exE":"What a strange thing!","note":"Palavra-curinga para qualquer objeto ou assunto.","noteE":"A catch-all word for any object or matter."},
  "a comida": {"ipa":"koo-MEE-dah","ex":"A comida portuguesa é deliciosa.","exE":"Portuguese food is delicious.","note":"Do verbo 'comer'; 'comida' = food/meal.","noteE":"From the verb 'comer' (to eat); means food/meal."},
  "a comissão": {"ipa":"koo-mee-SOWN (nasal)","ex":"A comissão reúne-se na próxima terça-feira.","exE":"The commission meets next Tuesday.","note":"É o grupo de pessoas nomeado para um fim e também a percentagem cobrada por um intermediário: «trabalhar à comissão».","noteE":"It is both an appointed panel of people and a middleman's cut — \"trabalhar à comissão\" is to work on commission."},
  "a companhia": {"ipa":"ah ko (nasal)-pah-NYEE-ah","ex":"Fazes-me companhia até ao comboio?","exE":"Will you keep me company as far as the train?","note":"\"Fazer companhia a alguém\" é a colocação fixa. Para empresa, os portugueses dizem quase sempre \"empresa\"; companhia fica para aviação e seguros.","noteE":"Fazer companhia a alguém is the set phrase. For a business, Portuguese almost always says empresa; companhia is kept for airlines and insurers."},
  "a comunicação": {"ipa":"koo-moo-nee-kah-SOWN (nasal)","ex":"A comunicação entre os dois serviços falhou.","exE":"Communication between the two departments broke down.","note":"«Os meios de comunicação social» (ou «a comunicação social») é como se diz «the media» em Portugal.","noteE":"'A comunicação social' is the standard Portuguese term for 'the media'."},
  "a comunidade": {"ipa":"koo-moo-nee-DAH-duh","ex":"A comunidade portuguesa em França é grande.","exE":"The Portuguese community in France is large.","note":"Ligada ao verbo «comungar» e a «comum»; note o «u» pronunciado em «-mun-», ao contrário do inglês.","noteE":"Related to 'comum'. Note the middle syllables are fully pronounced (koo-moo-nee-), unlike the reduced English word."},
  "a condição": {"ipa":"koh (nasal)-dee-SOW (nasal)","ex":"Empresto-te o carro, com uma condição.","exE":"I'll lend you the car, on one condition.","note":"\"Com a condição de que\" pede conjuntivo: \"com a condição de que venhas cedo\". No plural, \"as condições\" são os termos de um contrato ou o estado de algo.","noteE":"\"Com a condição de que\" takes the subjunctive: \"com a condição de que venhas cedo\". In the plural, \"as condições\" are contract terms or the state of something."},
  "a confiança": {"ipa":"koh (nasal)-fee-AH (nasal)-sah","ex":"Tenho toda a confiança na minha equipa.","exE":"I have complete trust in my team.","note":"É sempre «confiança em», tal como o verbo «confiar em». «Uma pessoa de confiança» é alguém fiável; «ter confiança» pode ser confiar noutros ou em si mesmo.","noteE":"It takes \"em\", like the verb \"confiar em\". \"De confiança\" describes someone reliable; the noun covers both trust in others and self-confidence."},
  "a construção": {"ipa":"koh (nasal)sh-troo-SOWN (nasal)","ex":"A construção da ponte demorou três anos.","exE":"Building the bridge took three years.","note":"Refere o processo de construir e não o edifício acabado — para isso diz-se «o edifício» ou «a obra». «Em construção» é a placa nas obras.","noteE":"It names the process, not the finished building — for that say \"o edifício\" or \"a obra\". \"Em construção\" is the under-construction sign."},
  "a conta": {"ipa":"KOH (nasal)-tah","ex":"A conta, por favor. Podemos pagar separado?","exE":"The bill, please. Can we pay separately?","note":"Uma só palavra para a conta do restaurante, a conta bancária e as contas de matemática (\"fazer contas\"). Aprende também \"dar-se conta de\" (to realise).","noteE":"One word covers the restaurant bill, a bank account and doing sums (\"fazer contas\"). Also learn \"dar-se conta de\" (to realise)."},
  "a conversa": {"ipa":"ko (nasal)-VEHR-sah","ex":"Tivemos uma conversa longa ao telefone.","exE":"We had a long conversation on the phone.","note":"«Conversa» é a palavra do dia a dia; «conversação» é formal ou técnica. «Conversa fiada» significa treta.","noteE":"'Conversa' is the everyday word; 'conversação' is formal or technical. 'Conversa fiada' means empty talk."},
  "a cor": {"ipa":"kohr","ex":"De que cor é o teu casaco novo?","exE":"What colour is your new coat?","note":"Atenção à expressão «saber de cor», que significa saber de memória e não tem nada a ver com cores. Pergunta-se «de que cor é?», com a preposição.","noteE":"Watch out for \"saber de cor\" — it means to know by heart and has nothing to do with colour. The question is \"de que cor é?\", with the preposition."},
  "a costa": {"ipa":"KAWSH-tah","ex":"A costa alentejana é linda e pouco construída.","exE":"The Alentejo coast is beautiful and barely built up.","note":"Cuidado com o plural: \"as costas\" quer dizer as costas do corpo (\"dói-me as costas\"), não várias costas marítimas. O o é aberto nas duas.","noteE":"Watch the plural: \"as costas\" means your back (\"dói-me as costas\"), not several coastlines. The o is open in both."},
  "a cozinha": {"ipa":"koo-ZEE-nyah","ex":"A minha mãe está na cozinha a fazer o jantar.","exE":"My mother is in the kitchen making dinner.","note":"Designa a divisão e também a gastronomia de um país: «a cozinha portuguesa». O verbo é «cozinhar» e o «nh» soa como o «ni» de «onion».","noteE":"It names both the room and a country's cuisine: \"a cozinha portuguesa\". The verb is \"cozinhar\"; \"nh\" sounds like the \"ni\" in \"onion\"."},
  "a criança": {"ipa":"kree-AH (nasal)-sah","ex":"A criança está a dormir no quarto.","exE":"The child is sleeping in the bedroom.","note":"É sempre feminina, mesmo quando se fala de um rapaz: \"a criança está cansada\". Em conversa, os portugueses dizem muito \"miúdo/miúda\" para kid.","noteE":"It is always feminine, even for a boy: \"a criança está cansada\". In conversation Portuguese people often say \"miúdo/miúda\" for kid."},
  "a criação": {"ipa":"ah kree-ah-SOW (nasal)","ex":"A criação desta empresa demorou anos.","exE":"Setting up this company took years.","note":"Vem de criar e serve também para a educação dos filhos e para a criação de animais, sentidos que o inglês \"creation\" não tem.","noteE":"It comes from criar and also covers raising children and breeding livestock, senses the English creation does not have."},
  "a cultura": {"ipa":"kool-TOO-rah","ex":"A cultura portuguesa dá muito valor à família.","exE":"Portuguese culture places great value on family.","note":"Além do sentido social, significa cultivo agrícola: «a cultura do milho». «Ter cultura geral» é ser bem informado, não ser educado.","noteE":"Besides the social sense it means a crop or cultivation: \"a cultura do milho\". \"Ter cultura geral\" is to be well-read, not well-mannered."},
  "a câmara": {"ipa":"KUH-mah-rah","ex":"Fui à câmara municipal tratar dos papéis.","exE":"I went to the town hall to sort out the paperwork.","note":"Em Portugal \"a câmara\" sozinha quer quase sempre dizer câmara municipal (a autarquia). Para fotografar, dizemos antes \"máquina fotográfica\" ou a câmara do telemóvel.","noteE":"In Portugal \"a câmara\" on its own almost always means the town council. For photography people say \"máquina fotográfica\" or the phone's camera."},
  "a decisão": {"ipa":"duh-see-ZOWN (nasal)","ex":"Ainda não tomei uma decisão sobre a casa.","exE":"I still haven't made a decision about the house.","note":"Diz-se «tomar uma decisão», nunca «fazer uma decisão» — erro típico de quem traduz do inglês. «Decidir-se por» é escolher entre opções.","noteE":"You \"tomar\" a decision, never \"fazer\" one — a classic English-speaker slip. \"Decidir-se por\" is to settle on one option."},
  "a defesa": {"ipa":"ah duh-FAY-zah","ex":"A defesa da equipa esteve muito bem.","exE":"The team's defence played very well.","note":"Escreve-se com s (não com c, como o inglês \"defence\") e lê-se z. \"A defesa da tese\" é a prova oral final de um doutoramento.","noteE":"It is spelled with an s, unlike English defence, and sounds like z. A defesa da tese is the oral defence of a doctorate."},
  "a diferença": {"ipa":"dee-fuh-REN (nasal)-sah","ex":"Não vejo diferença entre os dois.","exE":"I don't see any difference between the two.","note":"«Diferença entre A e B»; e o adjetivo pede «diferente de», nunca «diferente que».","noteE":"Use 'diferença entre A e B'; and the adjective takes 'diferente de', never 'diferente que'."},
  "a dificuldade": {"ipa":"ah dee-fee-kool-DAH-duh","ex":"Tenho dificuldade em perceber o sotaque.","exE":"I find the accent hard to understand.","note":"\"Ter dificuldade em\" + infinitivo é a construção fixa; muitos estrangeiros usam erradamente \"a\" ou \"de\".","noteE":"Ter dificuldade em plus an infinitive is the set construction; learners often wrongly use a or de instead."},
  "a direção": {"ipa":"dee-reh-SOWN (nasal)","ex":"Vamos na direção errada.","exE":"We're going in the wrong direction.","note":"Depois do Acordo Ortográfico escreve-se sem o «c» (antes «direcção»), mas o «e» mantém-se aberto. Também significa a administração de uma empresa ou escola.","noteE":"Since the spelling reform it drops the old \"c\" (\"direcção\"), though the open \"e\" survives. It also means the management board of a company or school."},
  "a doença": {"ipa":"ah doo-E (nasal)-sah","ex":"A doença dele já está controlada.","exE":"His illness is under control now.","note":"Não se diz \"ter uma doença\" no dia a dia: diz-se \"estar doente\". Doença é a condição, doente é a pessoa ou o adjetivo.","noteE":"In everyday speech you say estar doente rather than ter uma doença. Doença is the condition; doente is the sick person or the adjective."},
  "a dor": {"ipa":"dor","ex":"Tenho dores de cabeça desde ontem.","exE":"I've had a headache since yesterday.","note":"É feminina, ao contrário da maioria das palavras em -or: a dor, a cor, a flor. Diz-se «ter dores de».","noteE":"Feminine, unlike most -or nouns (compare a cor, a flor). The usual phrase is 'ter dores de'."},
  "a década": {"ipa":"DEH-kah-dah","ex":"Vivi em Lisboa durante uma década.","exE":"I lived in Lisbon for a decade.","note":"Para falar dos anos 80 diz-se «na década de 80» ou «nos anos 80».","noteE":"To say 'in the eighties', Portuguese uses 'na década de 80' or 'nos anos 80'."},
  "a dúvida": {"ipa":"ah DOO-vee-dah","ex":"Sem dúvida que te ajudo.","exE":"Of course I'll help you.","note":"\"Sem dúvida\" equivale a claro que sim, e \"tirar uma dúvida\" é esclarecer uma questão. O acento distingue o nome do verbo \"duvida\".","noteE":"Sem dúvida means of course, and tirar uma dúvida is to clear something up. The accent distinguishes the noun from the verb duvida."},
  "a economia": {"ipa":"ah ee-koo-noo-MEE-ah","ex":"A economia portuguesa cresceu este ano.","exE":"The Portuguese economy grew this year.","note":"Vale para a economia de um país e para a disciplina. Para poupar dinheiro no dia a dia diz-se \"poupar\" ou \"fazer poupanças\", não \"fazer economia\".","noteE":"It covers a country's economy and the academic subject. For saving money day to day, say poupar or fazer poupanças, not fazer economia."},
  "a educação": {"ipa":"ah ee-doo-kah-SOW (nasal)","ex":"Aquele rapaz não tem educação nenhuma.","exE":"That boy has no manners at all.","note":"Além de ensino, educação significa boas maneiras: \"ter educação\" é ser bem-educado e \"sem educação\" é malcriado.","noteE":"Besides schooling, educação means good manners: ter educação is to be polite and sem educação means rude."},
  "a eleição": {"ipa":"ee-lay-SOWN (nasal)","ex":"As eleições autárquicas são no outono.","exE":"The local elections are in the autumn.","note":"Usa-se quase sempre no plural, «as eleições». Em Portugal distinguem-se as «legislativas», as «presidenciais» e as «autárquicas» (locais).","noteE":"Almost always plural, \"as eleições\". Portugal distinguishes \"legislativas\", \"presidenciais\" and \"autárquicas\" (local) elections."},
  "a empresa": {"ipa":"eh (nasal)-PRAY-zah","ex":"Ele trabalha numa empresa de informática.","exE":"He works at an IT company.","note":"É a palavra normal para company/firm; \"companhia\" usa-se sobretudo em nomes próprios e no sentido de companhia humana. Falso amigo de \"enterprise\" no sentido de iniciativa.","noteE":"This is the normal word for company or firm; \"companhia\" appears mainly in proper names and in the sense of someone's company. It is a false friend of \"enterprise\" meaning boldness."},
  "a energia": {"ipa":"ah ee-nuhr-ZHEE-ah","ex":"Hoje não tenho energia nenhuma.","exE":"I have no energy at all today.","note":"O g antes de e lê-se como o j português. A conta da luz é \"a fatura da eletricidade\", não da energia.","noteE":"The g before e sounds like the Portuguese j. Your electricity bill is a fatura da eletricidade, not da energia."},
  "a entrada": {"ipa":"ah e (nasal)-TRAH-dah","ex":"Como entrada, pedimos queijo da serra.","exE":"For a starter, we ordered mountain cheese.","note":"Significa entrada de um edifício, bilhete de acesso e ainda o prato que se come antes do principal, num restaurante.","noteE":"It means the entrance to a building, an admission ticket, and also the starter course you eat before the main dish."},
  "a equipa": {"ipa":"ee-KEE-pah","ex":"A nossa equipa ganhou por dois a zero.","exE":"Our team won two nil.","note":"Em Portugal diz-se \"equipa\"; a forma \"equipe\" é brasileira e soa estranha aqui. O verbo fica no singular: \"a equipa joga\", não \"jogam\".","noteE":"In Portugal it is \"equipa\"; the form \"equipe\" is Brazilian and sounds odd here. The verb stays singular: \"a equipa joga\", not \"jogam\"."},
  "a escola": {"ipa":"sh-KAW-lah","ex":"Os miúdos saem da escola às três e meia.","exE":"The kids get out of school at half past three.","note":"\"Escola\" é o ensino até ao secundário; a universidade é \"a faculdade\" ou \"a universidade\", nunca \"escola\". Um \"colégio\" é normalmente um colégio privado.","noteE":"\"Escola\" covers schooling up to secondary; university is \"a faculdade\" or \"a universidade\", never \"escola\". A \"colégio\" is usually a private school."},
  "a espécie": {"ipa":"sh-PEH-see-uh","ex":"É uma espécie de sopa com peixe.","exE":"It's a sort of soup with fish.","note":"\"Uma espécie de\" é a forma corrente de dizer \"a kind of\". Não confundas com \"especiarias\" (spices), que é falso amigo de \"species\".","noteE":"\"Uma espécie de\" is the everyday way to say \"a kind of\". Don't confuse it with \"especiarias\" (spices), a classic false-friend trap."},
  "a estante": {"ipa":"sh-TAHN (nasal)-tuh","ex":"Comprámos uma estante nova para os livros.","exE":"We bought a new bookcase for the books.","note":"É o móvel completo, não uma prateleira só. Também designa a estante de partituras dos músicos.","noteE":"It is the whole unit, not one shelf. It also means a music stand for sheet music."},
  "a estrada": {"ipa":"ah ish-TRAH-dah","ex":"A estrada para o Norte estava cortada.","exE":"The road north was closed.","note":"Estrada é a via entre localidades; dentro da cidade diz-se \"rua\". A autoestrada é a via rápida com portagens.","noteE":"Estrada is the road between towns; within a city you say rua. An autoestrada is the motorway, with tolls."},
  "a estrela": {"ipa":"sh-TRAY-lah","ex":"Consegues ver aquela estrela ali?","exE":"Can you see that star over there?","note":"Vale para o astro e para uma figura famosa, como em inglês. A Serra da Estrela é a montanha mais alta de Portugal continental.","noteE":"It covers both the astronomical body and a famous person, just like English. The Serra da Estrela is mainland Portugal's highest range."},
  "a estrutura": {"ipa":"sh-troo-TOO-rah","ex":"A estrutura do edifício está em bom estado.","exE":"The building's structure is in good condition.","note":"O «es-» inicial pronuncia-se «sh», sem vogal audível. Usa-se tanto para construções físicas como para a organização de um texto ou de uma empresa.","noteE":"The initial \"es-\" is just a \"sh\" sound. It works for physical buildings and equally for the structure of a text or a company."},
  "a existência": {"ipa":"ee-zeesh-TEN (nasal)-see-ah","ex":"Desconhecia a existência deste sítio.","exE":"I didn't know this place existed.","note":"O «x» lê-se como «z». Em português é frequente usar o substantivo onde o inglês usa o verbo «to exist».","noteE":"The x sounds like z. Portuguese often uses this noun where English would use the verb 'to exist'."},
  "a experiência": {"ipa":"ah aysh-puh-ree-E (nasal)-see-ah","ex":"Não tenho experiência nesta área.","exE":"I have no experience in this field.","note":"A mesma palavra serve para experiência de vida e para experiência científica, que o inglês separa em experience e experiment.","noteE":"The one word covers both life experience and a scientific experiment, which English splits into two."},
  "a expressão": {"ipa":"esh-pruh-SOWN (nasal)","ex":"Não conhecia essa expressão portuguesa.","exE":"I didn't know that Portuguese expression.","note":"Significa tanto a frase feita («expressão idiomática») como a expressão do rosto.","noteE":"Means both a set phrase ('expressão idiomática') and a facial expression."},
  "a face": {"ipa":"FAH-suh","ex":"A face norte do edifício está sempre à sombra.","exE":"The north face of the building is always in shade.","note":"No dia a dia diz-se «cara» ou «rosto»; «face» é formal, anatómica ou geométrica. «Face a» significa perante/em comparação com.","noteE":"For a person's face, everyday European Portuguese uses 'cara' or 'rosto'; 'face' is formal or technical. 'Face a' means in the face of / compared with."},
  "a faculdade": {"ipa":"fah-kool-DAH-duh","ex":"Ando na faculdade desde setembro.","exE":"I've been at university since September.","note":"Falso amigo: não é o corpo docente (isso é «o corpo docente»), mas a escola dentro da universidade — e, na fala, a própria universidade.","noteE":"False friend: it is not the teaching staff (that's \"o corpo docente\") but a school within a university — and colloquially, university itself."},
  "a falta": {"ipa":"FAHL-tah","ex":"Tens-me feito muita falta este mês.","exE":"I've missed you a lot this month.","note":"«Fazer falta» significa ser necessário ou fazer sentir a ausência — a pessoa que falta é o sujeito, ao contrário do inglês «I miss you». No futebol, «falta» é a falta cometida.","noteE":"\"Fazer falta\" flips the English structure: the missed person is the subject, so \"fazes-me falta\" = \"I miss you\". In football it means a foul."},
  "a família": {"ipa":"fah-MEE-lee-ah","ex":"A minha família é grande.","exE":"My family is big.","note":"Acento no 'í': fa-MÍ-lia.","noteE":"Stress on the 'í': fah-MEE-lee-ah."},
  "a fase": {"ipa":"ah FAH-zuh","ex":"Estamos a passar por uma fase difícil.","exE":"We're going through a difficult phase.","note":"O s entre vogais lê-se como z. É feminina apesar de terminar em -e, ao contrário de muitos nomes nessa terminação.","noteE":"The s between vowels sounds like z. It is feminine despite the -e ending, unlike many nouns ending that way."},
  "a ferramenta": {"ipa":"fuh-rrah-MEN (nasal)-tah","ex":"Preciso de uma ferramenta mais pequena.","exE":"I need a smaller tool.","note":"Serve para ferramentas físicas e informáticas. Note «mais pequeno», a forma normal em Portugal, e não «menor».","noteE":"Used for both physical and software tools. Note that European Portuguese normally says 'mais pequeno', not 'menor'."},
  "a festa": {"ipa":"FESH-tah","ex":"A festa de anos dela acaba tarde.","exE":"Her birthday party finishes late.","note":"«Dar uma festa» = organizar. No Natal e Ano Novo deseja-se «Boas Festas».","noteE":"'Dar uma festa' means to throw a party. At Christmas and New Year people say 'Boas Festas'."},
  "a figura": {"ipa":"fee-GOO-rah","ex":"Ele fez boa figura na entrevista.","exE":"He made a good impression in the interview.","note":"«Fazer boa/má figura» significa causar boa ou má impressão, e «fazer figura triste» é passar vergonha. Também é a figura de um livro ou de um gráfico.","noteE":"\"Fazer boa/má figura\" is to come across well or badly; \"fazer figura triste\" is to embarrass yourself. It also means a figure in a book or chart."},
  "a filha": {"ipa":"ah FEE-lyah","ex":"A filha deles estuda medicina.","exE":"Their daughter studies medicine.","note":"'lh' soa como o 'lli' de 'million'.","noteE":"'lh' sounds like the 'lli' in 'million'."},
  "a fonte": {"ipa":"ah FO (nasal)-tuh","ex":"Bebemos água na fonte da aldeia.","exE":"We drank water at the village fountain.","note":"Cobre a fonte de água, a nascente e a fonte de informação. Já o tipo de letra do computador diz-se \"tipo de letra\", não fonte, em Portugal.","noteE":"It covers a fountain, a spring and a source of information. A computer font, though, is tipo de letra in Portugal, not fonte."},
  "a forma": {"ipa":"ah FAWR-mah","ex":"Não gosto da forma como ele fala.","exE":"I don't like the way he speaks.","note":"Traduz muitas vezes \"way\" e não \"form\": \"desta forma\" = deste modo. Distingue-se de \"o forma\" — não existe — mas cuidado com \"o formato\", que é o tamanho ou disposição.","noteE":"Usually translates 'way' rather than 'form': desta forma means 'in this way'. Don't reach for it when you mean size or layout — that's o formato."},
  "a força": {"ipa":"ah FOHR-sah","ex":"Não tenho força para levantar isto.","exE":"I don't have the strength to lift this.","note":"\"Força!\" sozinho é uma exclamação de encorajamento, como \"come on!\". \"À força\" significa contra a vontade de alguém.","noteE":"Shouted on its own, Força! means 'come on, you can do it'. À força means 'by force, against someone's will'."},
  "a frase": {"ipa":"ah FRAH-zuh","ex":"Repete a frase mais devagar, por favor.","exE":"Repeat the sentence more slowly, please.","note":"Falso amigo: \"frase\" traduz normalmente \"sentence\", não \"phrase\". Para o inglês \"phrase\" diz-se antes \"expressão\" ou \"locução\".","noteE":"A false friend: frase means a full sentence, not an English 'phrase'. For that, say expressão or locução instead."},
  "a frente": {"ipa":"FREH (nasal)-tuh","ex":"Segue sempre em frente até ao semáforo.","exE":"Keep going straight ahead until the traffic lights.","note":"É feminina apesar de acabar em -e. \"Em frente\" quer dizer em linha reta ou em frente de algo; \"à frente\" quer dizer adiante ou à dianteira.","noteE":"Feminine despite the -e ending. \"Em frente\" means straight ahead or opposite something; \"à frente\" means further ahead or in the lead."},
  "a função": {"ipa":"foo (nasal)-SOW (nasal)","ex":"Qual é a função deste botão?","exE":"What's the function of this button?","note":"\"Em função de\" significa consoante ou dependendo de, muito usado em registo formal. \"Estar em funções\" quer dizer estar no exercício de um cargo.","noteE":"\"Em função de\" means depending on, common in formal register. \"Estar em funções\" means to be currently holding a post."},
  "a gente": {"ipa":"ah ZHEH (nasal)-tuh","ex":"Havia muita gente na praia.","exE":"There were a lot of people at the beach.","note":"É singular gramaticalmente: \"a gente é simpática\", nunca \"são\". Em Portugal significa sobretudo \"as pessoas\"; o uso como \"nós\" é comum no Brasil e informal cá.","noteE":"Grammatically singular — muita gente é simpática, never são. In Portugal it mostly means 'people'; using it for 'we' is Brazilian and sounds very casual here."},
  "a guarda": {"ipa":"GWAR-dah","ex":"A guarda das crianças ficou com a mãe.","exE":"Custody of the children went to the mother.","note":"Cuidado com o género: «a guarda» é o ato de guardar ou a corporação (a GNR), enquanto «o guarda» é o homem que vigia. «Estar de guarda» é estar de serviço.","noteE":"Watch the gender: \"a guarda\" is the act of guarding or the force (the GNR), while \"o guarda\" is the man on duty. \"Estar de guarda\" means to be on watch."},
  "a guerra": {"ipa":"GEH-rrah","ex":"A guerra acabou.","exE":"The war is over.","note":"'gu' antes de 'e' soa como o 'g' de 'get'.","noteE":"'gu' before 'e' sounds like the hard g in 'get'."},
  "a história": {"ipa":"ish-TAW-ree-ah","ex":"Conta-me uma história.","exE":"Tell me a story.","note":"Significa 'history' e 'story'; a grafia 'estória' não se usa em Portugal.","noteE":"Means both 'history' and 'story'; the spelling 'estória' isn't used in Portugal."},
  "a hora": {"ipa":"ah AW-rah","ex":"Que horas são? São três horas.","exE":"What time is it? It's three o'clock.","note":"O \"h\" é sempre mudo. Para perguntar as horas usa-se o plural: \"Que horas são?\". \"Está na hora\" significa que chegou o momento de fazer algo.","noteE":"The h is silent. Asking the time uses the plural — Que horas são? — and está na hora means 'it's time' in the sense of 'time to go'."},
  "a idade": {"ipa":"ah ee-DAH-duh","ex":"Que idade tem a tua irmã?","exE":"How old is your sister?","note":"A idade exprime-se com \"ter\", não com \"ser\": \"tenho trinta anos\". \"Que idade tens?\" e \"Quantos anos tens?\" são igualmente naturais.","noteE":"Age uses ter, never ser: tenho trinta anos. Both Que idade tens? and Quantos anos tens? sound equally natural."},
  "a ideia": {"ipa":"ah ee-DAY-ah","ex":"Tive uma ideia melhor.","exE":"I had a better idea.","note":"Em Portugal escreve-se sem acento e pronuncia-se com ditongo, \"ee-DAY-ah\". \"Não faço ideia\" é a expressão fixa, com o verbo fazer e não ter.","noteE":"The everyday phrase for 'I've no idea' is Não faço ideia — note faço, not tenho, which is the mistake English speakers make."},
  "a igreja": {"ipa":"ee-GRAY-zhah","ex":"A igreja da aldeia é do século XVI.","exE":"The village church is from the 16th century.","note":"Com minúscula é o edifício; com maiúscula, «a Igreja», é a instituição. Diz-se «ir à igreja», com a contração de a + a.","noteE":"Lower case is the building; capitalised \"a Igreja\" is the institution. The phrase is \"ir à igreja\", with a + a contracted."},
  "a ilha": {"ipa":"EE-lyah","ex":"A ilha da Madeira é verde todo o ano.","exE":"The island of Madeira is green all year round.","note":"O lh soa como o ly de \"million\", nunca como um l simples. Diz-se \"na ilha\" para estar nela e \"à ilha\" para ir até lá.","noteE":"The lh sounds like the ly in \"million\", never a plain l. Use \"na ilha\" for being on it and \"à ilha\" for going there."},
  "a imagem": {"ipa":"ee-MAH-zheh (nasal)","ex":"A imagem da televisão está desfocada.","exE":"The picture on the television is blurry.","note":"Feminina apesar do -em final, tal como \"a ordem\" e \"a viagem\"; plural \"imagens\". Para uma fotografia diz-se antes \"foto\" ou \"fotografia\".","noteE":"Feminine despite the -em ending, like \"a ordem\" and \"a viagem\"; plural \"imagens\". For a photograph say \"foto\" or \"fotografia\" instead."},
  "a importância": {"ipa":"ah ee (nasal)-poor-TA (nasal)-see-ah","ex":"Não dês importância ao que ele disse.","exE":"Don't pay attention to what he said.","note":"\"Dar importância a\" significa valorizar ou ligar a algo. Em linguagem bancária, importância também significa quantia em dinheiro.","noteE":"Dar importância a means to attach weight to something. In banking language importância also means a sum of money."},
  "a influência": {"ipa":"ah ee (nasal)-floo-E (nasal)-see-ah","ex":"Ele teve muita influência na minha decisão.","exE":"He had a lot of influence on my decision.","note":"Usa-se com as preposições em ou sobre: \"ter influência em\", \"exercer influência sobre\". O verbo influenciar não leva preposição.","noteE":"It goes with em or sobre: ter influência em, exercer influência sobre. The verb influenciar takes no preposition."},
  "a informação": {"ipa":"ee (nasal)-foor-mah-SOW (nasal)","ex":"Preciso de mais informações sobre o horário.","exE":"I need more information about the timetable.","note":"Ao contrário do inglês, usa-se muito no plural: \"informações\" são dados vários e também o balcão de atendimento numa estação.","noteE":"Unlike English, it is freely pluralised: \"informações\" means bits of information and also the enquiries desk at a station."},
  "a instituição": {"ipa":"eensh-tee-too-ee-SOWN (nasal)","ex":"Esta instituição ajuda pessoas idosas.","exE":"This institution helps elderly people.","note":"Todas as palavras terminadas em -ção são femininas e fazem o plural em -ções: instituições.","noteE":"Every noun ending in -ção is feminine and pluralises in -ções: instituições."},
  "a irmã": {"ipa":"ah eer-MA (nasal)","ex":"Tenho uma irmã.","exE":"I have a sister.","note":"Feminino de 'irmão'; plural 'as irmãs'.","noteE":"Feminine of 'irmão'; plural 'as irmãs'."},
  "a janela": {"ipa":"zhah-NEH-lah","ex":"Ela está à janela a ver a chuva.","exE":"She's at the window watching the rain.","note":"\"Estar à janela\" (com a contração à) significa estar debruçado a olhar para a rua, um hábito muito português. \"Na janela\" seria estar em cima dela.","noteE":"\"Estar à janela\" means leaning out watching the street, a very Portuguese habit. \"Na janela\" would mean on top of it."},
  "a justiça": {"ipa":"ah zhoosh-TEE-sah","ex":"Ele só quer justiça para a família.","exE":"He only wants justice for his family.","note":"\"Fazer justiça a alguém\" é reconhecer-lhe o mérito. \"A Justiça\", com maiúscula, refere-se ao sistema judicial.","noteE":"Fazer justiça a alguém means to give someone due credit. Capitalised, a Justiça refers to the judicial system."},
  "a lei": {"ipa":"lay","ex":"A nova lei entra em vigor em janeiro.","exE":"The new law comes into force in January.","note":"É feminina apesar de não acabar em -a: \"uma lei injusta\", plural \"as leis\". Para a disciplina académica usa-se \"Direito\", não \"lei\".","noteE":"It is feminine despite not ending in -a: \"uma lei injusta\", plural \"as leis\". The academic subject is \"Direito\", not \"lei\"."},
  "a liberdade": {"ipa":"lee-buhr-DAH-duh","ex":"O 25 de Abril trouxe a liberdade a Portugal.","exE":"The 25th of April brought freedom to Portugal.","note":"«Ter a liberdade de» + infinitivo. Não confundir com «à vontade», que é sentir-se confortável.","noteE":"Use 'ter a liberdade de' + infinitive. Don't confuse it with 'à vontade', which means feeling at ease."},
  "a linha": {"ipa":"LEE-nyah","ex":"Esta linha de comboio vai até Cascais.","exE":"This train line goes as far as Cascais.","note":"Cobre a linha desenhada, a linha de costura, a linha de comboio e a linha telefónica. Em Lisboa, \"a Linha\" é a zona de Cascais e Estoril.","noteE":"It covers a drawn line, sewing thread, a train line and a phone line. In Lisbon, \"a Linha\" means the Cascais and Estoril corridor."},
  "a literatura": {"ipa":"lee-tuh-rah-TOO-rah","ex":"Ela estuda literatura portuguesa em Coimbra.","exE":"She studies Portuguese literature in Coimbra.","note":"Não se usa, como em inglês, para folhetos informativos; nesse caso diz-se «documentação» ou «folhetos».","noteE":"Unlike English, it never means informational leaflets — for that say 'documentação' or 'folhetos'."},
  "a lua": {"ipa":"LOO-ah","ex":"Esta noite a lua está cheia.","exE":"The moon is full tonight.","note":"«Estar na lua» significa estar distraído, e a «lua de mel» é a viagem depois do casamento. O astro leva maiúscula só em contexto científico.","noteE":"\"Estar na lua\" is to be daydreaming, and \"lua de mel\" is the honeymoon. It is only capitalised in astronomical writing."},
  "a luta": {"ipa":"LOO-tah","ex":"A luta contra os incêndios continua.","exE":"The fight against the fires goes on.","note":"«Luta contra» (algo mau) e «luta por» (algo desejado). Também designa o desporto de luta.","noteE":"Use 'luta contra' for something bad and 'luta por' for something you want. It also means wrestling as a sport."},
  "a luz": {"ipa":"loosh","ex":"Apaga a luz da cozinha antes de sair.","exE":"Turn off the kitchen light before you leave.","note":"\"A luz\" também é a eletricidade — \"a conta da luz\" é a electricity bill. Guarda a expressão \"dar à luz\", que significa dar à luz um bebé.","noteE":"\"A luz\" also means electricity — \"a conta da luz\" is the electricity bill. Keep the phrase \"dar à luz\", which means to give birth."},
  "a língua": {"ipa":"LEEN (nasal)-gwah","ex":"A língua portuguesa tem muitos falantes.","exE":"The Portuguese language has many speakers.","note":"Serve para o idioma e para o órgão na boca. «Idioma» é mais formal e «ter na ponta da língua» significa estar quase a lembrar-se de uma palavra.","noteE":"It covers both the language and the tongue in your mouth. \"Idioma\" is more formal, and \"ter na ponta da língua\" means a word is on the tip of your tongue."},
  "a madeira": {"ipa":"mah-DAY-rah","ex":"A mesa é de madeira maciça.","exE":"The table is made of solid wood.","note":"«Madeira» é o material; a lenha para a lareira é «lenha» e o bosque é «a floresta» ou «o bosque».","noteE":"'Madeira' is wood as a material; firewood is 'lenha' and woods/forest is 'floresta' or 'bosque'."},
  "a maioria": {"ipa":"my-oo-REE-ah","ex":"A maioria das pessoas prefere ir de autocarro.","exE":"Most people prefer to go by bus.","note":"«A maioria de» costuma levar o verbo no singular, embora o plural também se ouça. Não confundir com «maior», o comparativo de grande.","noteE":"\"A maioria de\" normally takes a singular verb, though the plural is heard too. Don't confuse it with \"maior\" (bigger)."},
  "a maneira": {"ipa":"mah-NAY-rah","ex":"Não gosto da maneira como ele fala.","exE":"I don't like the way he speaks.","note":"Usa-se «de qualquer maneira» para «de qualquer modo» e «desta maneira» para «assim». É quase sinónimo de «forma», mas «maneira» é mais coloquial.","noteE":"\"De qualquer maneira\" means \"anyway\" and \"desta maneira\" means \"this way\". It overlaps with \"forma\", but \"maneira\" is the chattier of the two."},
  "a manhã": {"ipa":"mah-NYA (nasal)","ex":"De manhã tomo sempre o pequeno-almoço em casa.","exE":"In the morning I always have breakfast at home.","note":"Não confundas \"manhã\" com \"amanhã\" (o dia seguinte). Diz-se \"de manhã\", sem artigo, para falar da parte do dia.","noteE":"Don't mix up \"manhã\" with \"amanhã\" (tomorrow). Use \"de manhã\" with no article for the time of day."},
  "a massa": {"ipa":"MAH-sah","ex":"A massa já está a cozer.","exE":"The pasta is already cooking.","note":"Serve para massa alimentícia, massa de pão e massa física; «em massa» significa em grande número.","noteE":"Covers pasta, dough and physical mass; 'em massa' means en masse, in large numbers."},
  "a medida": {"ipa":"muh-DEE-dah","ex":"O governo tomou medidas contra a poluição.","exE":"The government took measures against pollution.","note":"Diz-se \"tomar medidas\", não \"fazer\". Aprende também \"à medida que\" (as, while) e \"feito à medida\" (made to measure).","noteE":"You \"tomar medidas\", not \"fazer\". Also learn \"à medida que\" (as, while) and \"feito à medida\" (made to measure)."},
  "a mentira": {"ipa":"meh (nasal)-TEE-rah","ex":"Isso é mentira, eu estava em casa.","exE":"That's a lie, I was at home.","note":"Diz-se \"contar\" ou \"dizer uma mentira\", nunca \"fazer\". Note-se que \"isso é mentira\" dispensa o artigo, ao contrário do inglês \"that's a lie\".","noteE":"You \"contar\" or \"dizer uma mentira\" — never \"fazer\". Note \"isso é mentira\" drops the article, unlike English \"that's a lie\"."},
  "a mesa": {"ipa":"MAY-zah","ex":"Podes pôr a mesa para o jantar?","exE":"Can you set the table for dinner?","note":"«Pôr a mesa» é preparar os talheres e «levantar a mesa» é tirá-los. O «s» entre vogais lê-se como «z», nunca como «ss».","noteE":"\"Pôr a mesa\" is to lay the table and \"levantar a mesa\" to clear it. The \"s\" between vowels is a \"z\" sound, never \"ss\"."},
  "a morte": {"ipa":"ah MOR-tuh","ex":"Foi uma questão de vida ou de morte.","exE":"It was a matter of life or death.","note":"Feminina, apesar de terminar em -e; o -e final soa 'uh'.","noteE":"Feminine, despite ending in -e; the final -e sounds like 'uh'."},
  "a mudança": {"ipa":"ah moo-DA (nasal)-sah","ex":"A mudança de casa foi cansativa.","exE":"Moving house was exhausting.","note":"Serve para mudança em geral e para mudança de casa. No carro, \"as mudanças\" são as velocidades; e mudar de casa diz-se \"mudar-se\".","noteE":"It covers change in general and moving house. In a car as mudanças are the gears, and to move house is mudar-se."},
  "a mulher": {"ipa":"ah moo-LYER","ex":"A mulher dele é médica.","exE":"His wife is a doctor.","note":"Significa 'mulher' e 'esposa'; 'lh' soa como o 'lli' de 'million'.","noteE":"Means both 'woman' and 'wife'; 'lh' sounds like the 'lli' in 'million'."},
  "a máquina": {"ipa":"MAH-kee-nah","ex":"A máquina de lavar avariou-se ontem.","exE":"The washing machine broke down yesterday.","note":"Palavra esdrúxula: a força está na primeira sílaba. Colocações: máquina de lavar roupa/loiça, máquina fotográfica.","noteE":"Stress falls on the first syllable. Useful pairings: 'máquina de lavar roupa/loiça', 'máquina fotográfica'."},
  "a mãe": {"ipa":"ah my (nasal)","ex":"A minha mãe é professora.","exE":"My mother is a teacher.","note":"Vogal nasal; plural 'as mães'.","noteE":"Nasal vowel; plural 'as mães'."},
  "a mão": {"ipa":"ah MOW (nasal)","ex":"Dá-me a mão para atravessar.","exE":"Give me your hand to cross the road.","note":"É feminina apesar de terminar em -ão, e o plural é irregular: \"as mãos\". \"Em segunda mão\" quer dizer usado; \"à mão\" quer dizer feito manualmente.","noteE":"Feminine despite the -ão ending, with the irregular plural mãos. Em segunda mão means second-hand and à mão means by hand."},
  "a média": {"ipa":"ah MEH-dee-ah","ex":"A média das notas foi de catorze valores.","exE":"The average of the grades was fourteen.","note":"\"Em média\" é a locução fixa. Não confundir com \"os media\" (imprensa), que em Portugal se diz muitas vezes \"a comunicação social\".","noteE":"Em média is the fixed phrase for on average. Do not confuse it with os media, which in Portugal is often called a comunicação social."},
  "a música": {"ipa":"MOO-zee-kah","ex":"Põe uma música mais calma, se faz favor.","exE":"Put on a calmer song, please.","note":"\"A música\" é a arte em geral, mas \"uma música\" é uma canção concreta — em português usa-se muito onde o inglês diria \"a song\". \"Canção\" é mais formal ou poético.","noteE":"\"A música\" is music in general, but \"uma música\" is a specific song — Portuguese uses it where English says \"a song\". \"Canção\" is more formal or poetic."},
  "a natureza": {"ipa":"ah nah-too-RAY-zah","ex":"Gosto de passear na natureza.","exE":"I like walking in nature.","note":"Ao contrário do inglês, leva sempre artigo: \"a natureza\". \"Por natureza\" significa por índole, de forma inata.","noteE":"Unlike English, it always takes the article: a natureza. Por natureza means by nature, innately."},
  "a necessidade": {"ipa":"nuh-suh-see-DAH-duh","ex":"Não há necessidade de te preocupares.","exE":"There's no need for you to worry.","note":"«Não há necessidade de» é o equivalente de «there's no need to». O verbo relacionado é «precisar de», mais usado na fala do que «ter necessidade de».","noteE":"\"Não há necessidade de\" is how you say \"there's no need to\". In speech, \"precisar de\" is far commoner than \"ter necessidade de\"."},
  "a noite": {"ipa":"ah NOY-tuh","ex":"À noite fico em casa.","exE":"At night I stay home.","note":"'À noite' = at night; 'esta noite' = tonight.","noteE":"'À noite' = at night; 'esta noite' = tonight."},
  "a operação": {"ipa":"ah oo-puh-rah-SOW (nasal)","ex":"A operação ao joelho correu bem.","exE":"The knee operation went well.","note":"Na medicina diz-se \"fazer uma operação\" ou, na perspetiva do doente, \"ser operado a\" alguma coisa.","noteE":"In medicine you say fazer uma operação or, from the patient's side, ser operado a something."},
  "a opinião": {"ipa":"oo-pee-nee-OWN (nasal)","ex":"Na minha opinião, o filme é fraco.","exE":"In my opinion, the film is weak.","note":"Diz-se sempre «na minha opinião», com artigo. O plural é «opiniões».","noteE":"Portuguese needs the article: 'na minha opinião', never 'em minha opinião'. Plural is 'opiniões'."},
  "a ordem": {"ipa":"AWR-deh (nasal)","ex":"Põe os livros por ordem alfabética.","exE":"Put the books in alphabetical order.","note":"Feminina apesar de acabar em -em; o plural é \"as ordens\". Serve para sequência e para uma ordem dada por alguém: \"cumprir ordens\".","noteE":"Feminine despite the -em ending; the plural is \"as ordens\". It covers both sequence and a command given: \"cumprir ordens\"."},
  "a orelha": {"ipa":"ah oo-RAY-lyah","ex":"O bebé tem as orelhas pequeninas.","exE":"The baby has tiny ears.","note":"\"Orelha\" é a parte visível; \"o ouvido\" é o interior e o sentido da audição. Diz-se \"dói-me o ouvido\", não \"dói-me a orelha\".","noteE":"Orelha is the outer ear you can see; o ouvido is the inner ear and the sense of hearing. An earache is dói-me o ouvido."},
  "a organização": {"ipa":"ah or-gah-nee-zah-SOW (nasal)","ex":"A organização do evento correu muito bem.","exE":"The organisation of the event went very well.","note":"Todos os nomes terminados em -ção são femininos e fazem o plural em -ções: organizações. Serve tanto para a entidade como para o ato de organizar.","noteE":"All -ção nouns are feminine and pluralise as -ções: organizações. It covers both the body itself and the act of organising."},
  "a palavra": {"ipa":"pah-LAH-vrah","ex":"Não percebi a última palavra.","exE":"I didn't catch the last word.","note":"É o nome da aplicação: Mil Palavras.","noteE":"It's the app's name: Mil Palavras (a thousand words)."},
  "a parede": {"ipa":"pah-RAY-duh","ex":"Vamos pintar a parede da sala de branco.","exE":"We're going to paint the living-room wall white.","note":"«Parede» é a parede interior de um edifício; a parede exterior de um terreno é «o muro». «Falar para as paredes» é falar sem ser ouvido.","noteE":"\"Parede\" is a wall of a building; a free-standing outdoor wall is \"o muro\". \"Falar para as paredes\" is to talk and be ignored."},
  "a parte": {"ipa":"ah PAR-tuh","ex":"Esta é a melhor parte do filme.","exE":"This is the best part of the film.","note":"Feminino, ao contrário do que sugere a terminação em -e. Atenção à expressão \"à parte\" (separadamente) e ao falso amigo \"partir\", que significa sair ou quebrar.","noteE":"Feminine despite the -e ending. Watch the fixed phrase à parte ('separately, aside') and don't link it to partir, which means to leave or to break."},
  "a paz": {"ipa":"pash","ex":"Queremos paz.","exE":"We want peace.","note":"Final '-z' soa 'sh'; rima com 'faz'.","noteE":"Final '-z' sounds 'sh'; it rhymes with 'faz'."},
  "a pedra": {"ipa":"ah PEH-drah","ex":"Tropecei numa pedra no caminho.","exE":"I tripped on a stone on the path.","note":"Serve para pedra e rocha em geral; \"rocha\" é sobretudo termo geológico. \"Pedras nos rins\" são cálculos renais.","noteE":"It covers stone and rock generally; rocha is mainly a geological term. Pedras nos rins are kidney stones."},
  "a pena": {"ipa":"ah PAY-nah","ex":"Que pena não teres vindo!","exE":"What a shame you didn't come!","note":"Além de pena de ave e pena judicial, é a base de duas expressões muito usadas: \"que pena!\" e \"vale a pena\" (compensa).","noteE":"Besides a bird's feather and a legal sentence, it drives two very common phrases: que pena! (what a pity) and vale a pena (it's worth it)."},
  "a pergunta": {"ipa":"per-GOON (nasal)-tah","ex":"Posso fazer-te uma pergunta rápida?","exE":"Can I ask you a quick question?","note":"Diz-se \"fazer uma pergunta\", nunca \"perguntar uma pergunta\". \"Pergunta\" é o que se pergunta; \"questão\" é um assunto ou problema.","noteE":"You \"fazer uma pergunta\" — never \"perguntar uma pergunta\". \"Pergunta\" is what you ask; \"questão\" is a matter or issue."},
  "a perna": {"ipa":"ah PEHR-nah","ex":"Magoei a perna a correr.","exE":"I hurt my leg while running.","note":"O \"e\" é aberto na sílaba tónica. \"Passar a perna a alguém\" significa enganar essa pessoa, e não tem nada a ver com pernas.","noteE":"The stressed e is open. The idiom passar a perna a alguém means to cheat or trick someone, nothing to do with legs."},
  "a pesquisa": {"ipa":"ah push-KEE-zah","ex":"Fiz uma pesquisa rápida na internet.","exE":"I did a quick search on the internet.","note":"Em Portugal, pesquisa é sobretudo uma busca ou consulta; para trabalho académico ou científico diz-se \"investigação\".","noteE":"In Portugal pesquisa is mostly a search or lookup; academic and scientific research is called investigação."},
  "a pessoa": {"ipa":"ah puh-SOH-ah","ex":"É uma boa pessoa.","exE":"He's a good person.","note":"Sempre feminina, mesmo para um homem: 'ele é uma pessoa simpática'.","noteE":"Always feminine, even for a man: 'ele é uma pessoa simpática'."},
  "a peça": {"ipa":"ah PEH-sah","ex":"Falta uma peça para acabar o móvel.","exE":"One part is missing to finish the cabinet.","note":"Significa peça de teatro, peça musical e também componente ou sobresselente de uma máquina. \"Pregar uma peça a alguém\" é fazer-lhe uma partida.","noteE":"It covers a theatre play, a musical piece and a machine part or spare. Pregar uma peça a alguém means to play a trick on someone."},
  "a planta": {"ipa":"PLAH (nasal)-tah","ex":"Podes regar as plantas enquanto estou fora?","exE":"Can you water the plants while I'm away?","note":"Falso amigo: uma fábrica industrial nunca é \"planta\" em português — diz-se \"a fábrica\" ou \"a unidade\". \"Planta\" é a planta viva ou a planta de um edifício.","noteE":"False friend: an industrial plant is never \"planta\" in Portuguese — say \"a fábrica\" or \"a unidade\". \"Planta\" is a living plant or a building's floor plan."},
  "a política": {"ipa":"poo-LEE-tee-kah","ex":"Não gosto de falar de política ao jantar.","exE":"I don't like talking politics over dinner.","note":"\"A política\" cobre politics e policy; \"o político / a política\" é a pessoa, o que gera ambiguidade resolvida pelo contexto. \"Político\" também é adjetivo.","noteE":"\"A política\" covers both politics and policy; \"o político / a política\" is the politician, an ambiguity context resolves. \"Político\" is also an adjective."},
  "a população": {"ipa":"poo-poo-lah-SOW (nasal)","ex":"A população da aldeia é cada vez menor.","exE":"The village population keeps getting smaller.","note":"Leva verbo no singular, mesmo referindo-se a muita gente: \"a população está preocupada\". Feminina, como todos os nomes em -ção.","noteE":"It takes a singular verb even though it refers to many people: \"a população está preocupada\". Feminine, like all -ção nouns."},
  "a porta": {"ipa":"PAWR-tah","ex":"Fecha a porta, por favor, está frio.","exE":"Close the door please, it's cold.","note":"Não confundas com \"o porto\" (o cais, e a cidade do Porto). Um portão é grande e exterior; uma porta é normalmente de casa ou de divisão.","noteE":"Don't confuse it with \"o porto\" (harbour, and the city Porto). A \"portão\" is a large outdoor gate; a \"porta\" is normally a house or room door."},
  "a posição": {"ipa":"poo-zee-SOWN (nasal)","ex":"O partido ainda não tomou posição sobre o assunto.","exE":"The party hasn't taken a position on the matter yet.","note":"«Tomar posição» é assumir publicamente uma opinião. Para o cargo de alguém usa-se antes «o cargo» ou «o lugar», não «posição».","noteE":"\"Tomar posição\" is to publicly take a stance. For someone's job role, say \"o cargo\" or \"o lugar\" rather than \"posição\"."},
  "a possibilidade": {"ipa":"ah poo-suh-bee-lee-DAH-duh","ex":"Existe a possibilidade de chover amanhã.","exE":"There's a possibility of rain tomorrow.","note":"Pede a preposição de: \"a possibilidade de fazer algo\". Quando se usa \"é possível que\", o verbo seguinte vai para o conjuntivo.","noteE":"It takes de: a possibilidade de fazer algo. Note that é possível que requires the subjunctive in the following verb."},
  "a praia": {"ipa":"PRY-ah","ex":"Vamos à praia no sábado de manhã.","exE":"We're going to the beach on Saturday morning.","note":"«Ir à praia» (com crase de a + a) mas «estar na praia». O acento grave marca a contração.","noteE":"It's 'ir à praia' (a + a contracted, hence the grave accent) but 'estar na praia'."},
  "a prateleira": {"ipa":"prah-tuh-LAY-rah","ex":"Os copos estão na prateleira de cima.","exE":"The glasses are on the top shelf.","note":"É uma tábua isolada, dentro de um armário ou na parede; o móvel inteiro com várias prateleiras é «a estante».","noteE":"It is one single board, inside a cupboard or on the wall; the whole piece of furniture holding several is \"a estante\"."},
  "a presença": {"ipa":"ah pruh-ZE (nasal)-sah","ex":"A tua presença na festa foi importante.","exE":"Your presence at the party mattered.","note":"\"Marcar presença\" é a expressão fixa para comparecer a um evento. O s entre vogais lê-se z.","noteE":"Marcar presença is the set phrase for turning up at an event. The s between vowels is pronounced as z."},
  "a produção": {"ipa":"proo-doo-SOW (nasal)","ex":"A produção de vinho aumentou este ano.","exE":"Wine production went up this year.","note":"Feminina, com plural \"produções\". Repara que se diz \"produção de vinho\" com \"de\", onde o inglês junta as palavras sem preposição.","noteE":"Feminine, plural \"produções\". Note it takes \"de\" — \"produção de vinho\" — where English just stacks the nouns together."},
  "a proposta": {"ipa":"proo-PAWSH-tah","ex":"Fizeram-me uma proposta de trabalho.","exE":"They made me a job offer.","note":"Diz-se «fazer uma proposta», nunca «dar». Serve para propostas de negócio, de emprego e de lei — para pedidos de casamento diz-se antes «pedido».","noteE":"You \"fazer\" a proposal, never \"dar\" one. It covers business, job and legislative proposals; a marriage proposal is a \"pedido\"."},
  "a prova": {"ipa":"ah PRAW-vah","ex":"Tenho uma prova de matemática amanhã.","exE":"I have a maths test tomorrow.","note":"É prova escolar, prova judicial e prova de degustação, tudo na mesma palavra. \"À prova de água\" significa impermeável.","noteE":"It means a school test, legal proof and a tasting, all in one word. À prova de água means waterproof."},
  "a prática": {"ipa":"PRAH-tee-kah","ex":"Na prática, é bem mais difícil.","exE":"In practice, it is much harder.","note":"Não confundir com o adjetivo «prático» (útil, jeitoso). Colocação comum: «pôr em prática».","noteE":"Don't mix up the noun 'a prática' with the adjective 'prático' (handy, practical). Common collocation: 'pôr em prática'."},
  "a qualidade": {"ipa":"kwah-lee-DAH-duh","ex":"Este vinho tem muita qualidade.","exE":"This wine is of very high quality.","note":"«De qualidade» funciona como adjetivo: «um produto de qualidade». «Na qualidade de» significa «enquanto», na função de: «falou na qualidade de diretor».","noteE":"\"De qualidade\" works like an adjective: \"um produto de qualidade\". \"Na qualidade de\" means \"in the capacity of\"."},
  "a quantidade": {"ipa":"kwahn (nasal)-tee-DAH-duh","ex":"Precisamos de uma boa quantidade de farinha.","exE":"We need a good amount of flour.","note":"Na fala, «uma quantidade de» pode significar simplesmente «muitos»: «havia uma quantidade de gente». O «qua-» lê-se «kwa», com o «u» audível.","noteE":"Colloquially \"uma quantidade de\" just means \"loads of\": \"havia uma quantidade de gente\". The \"qua-\" is pronounced \"kwa\", with an audible \"u\"."},
  "a questão": {"ipa":"kush-TOW (nasal)","ex":"Não é questão de dinheiro, é de tempo.","exE":"It's not a matter of money, it's of time.","note":"Raramente significa uma pergunta concreta — para isso usa-se \"pergunta\". Guarda as expressões \"em questão\" (in question) e \"pôr em questão\" (to call into doubt).","noteE":"It rarely means a question you actually ask — that is \"pergunta\". Keep the phrases \"em questão\" (in question) and \"pôr em questão\" (to call into doubt)."},
  "a rainha": {"ipa":"rrah-EE-nyah","ex":"A rainha visitou a cidade em maio.","exE":"The queen visited the city in May.","note":"São três sílabas — ra-i-nha — porque o «i» forma sílaba própria. Serve também para a peça do xadrez e para a abelha-rainha.","noteE":"Three syllables — ra-i-nha — since the \"i\" stands alone. It also names the chess queen and the queen bee."},
  "a rapariga / a menina": {"ipa":"ah rrah-pah-REE-gah / ah muh-NEE-nah","ex":"A rapariga do café é muito simpática.","exE":"The girl at the café is very nice.","note":"Em Portugal rapariga é totalmente neutro, mas no Brasil é ofensivo, por isso convém saber com quem se fala. \"Menina\" serve também como tratamento cortês.","noteE":"In Portugal rapariga is completely neutral, but in Brazil it is offensive, so know your audience. Menina also works as a polite form of address."},
  "a razão": {"ipa":"rrah-ZOW (nasal)","ex":"Tens razão, foi culpa minha.","exE":"You're right, it was my fault.","note":"\"Ter razão\" é a maneira portuguesa de dizer \"to be right\" — nunca se usa \"estar certo\" para uma pessoa. \"Por razões de\" introduz uma justificação formal.","noteE":"\"Ter razão\" is how Portuguese says \"to be right\" — you never use \"estar certo\" for a person. \"Por razões de\" introduces a formal justification."},
  "a realidade": {"ipa":"ah rree-ah-lee-DAH-duh","ex":"Na realidade, nunca lá estive.","exE":"Actually, I've never been there.","note":"\"Na realidade\" traduz o inglês \"actually\". Cuidado com o falso amigo \"atualmente\", que significa neste momento, não \"na verdade\".","noteE":"Na realidade is how you say actually. Beware the false friend atualmente, which means currently, not in fact."},
  "a rede": {"ipa":"RRAY-duh","ex":"Aqui não tenho rede no telemóvel.","exE":"I don't have any signal on my mobile here.","note":"Além de «rede social» e «rede de computadores», «não ter rede» significa não ter cobertura de telemóvel. Também é a rede de pesca e a rede de dormir.","noteE":"Besides social and computer networks, \"não ter rede\" means having no phone signal. It is also a fishing net and a hammock."},
  "a reforma": {"ipa":"rruh-FOHR-mah","ex":"O meu pai está na reforma desde o ano passado.","exE":"My father has been retired since last year.","note":"Em Portugal significa sobretudo a aposentação: «estar na reforma», «estar reformado». O sentido político de mudança («a reforma da lei») também existe.","noteE":"In Portugal it mainly means retirement: \"estar na reforma\", \"estar reformado\". The political sense (legal reform) exists too."},
  "a região": {"ipa":"ah rruh-ZHOW (nasal)","ex":"Esta região é conhecida pelo vinho.","exE":"This region is known for its wine.","note":"É feminino, apesar da terminação em -ão; o plural é \"as regiões\". Em Portugal fala-se muito de \"região demarcada\" a propósito de vinhos.","noteE":"Feminine despite the -ão ending, plural regiões. In Portugal you'll meet it constantly in wine labelling: região demarcada, a protected wine region."},
  "a regra": {"ipa":"ah RREH-grah","ex":"Esta regra aplica-se a todos.","exE":"This rule applies to everyone.","note":"\"Por regra\" ou \"em regra\" significam normalmente. Note-se que a régua de medir é outra palavra, com acento: \"a régua\".","noteE":"Por regra and em regra both mean as a rule. Note that a measuring ruler is a different word with an accent: a régua."},
  "a relação": {"ipa":"ah rruh-lah-SOW (nasal)","ex":"Tenho uma boa relação com os vizinhos.","exE":"I have a good relationship with the neighbours.","note":"Feminino, plural \"relações\". A locução \"em relação a\" significa \"quanto a\" e é muito frequente na escrita.","noteE":"Feminine, plural relações. The set phrase em relação a means 'regarding / compared with' and is everywhere in written Portuguese."},
  "a república": {"ipa":"rruh-POO-blee-kah","ex":"O Presidente da República discursou ontem.","exE":"The President of the Republic spoke yesterday.","note":"O chefe de Estado português chama-se «Presidente da República». Em Coimbra, uma «república» é também uma casa partilhada por estudantes.","noteE":"Portugal's head of state is the \"Presidente da República\". In Coimbra, a \"república\" is also a shared student house."},
  "a resposta": {"ipa":"ah rrush-PAWSH-tah","ex":"Ainda não tive resposta ao meu e-mail.","exE":"I still haven't had a reply to my email.","note":"O verbo pede preposição: \"responder a uma pergunta\", nunca responder algo. \"Dar uma resposta\" é a colocação habitual.","noteE":"The verb needs a preposition: responder a uma pergunta, never responder something. Dar uma resposta is the usual collocation."},
  "a reunião": {"ipa":"ah rreh-oo-nee-OW (nasal)","ex":"A reunião foi adiada para sexta-feira.","exE":"The meeting was postponed to Friday.","note":"É a palavra normal para reuniões de trabalho: \"ter uma reunião\", \"estar em reunião\". O plural é reuniões.","noteE":"This is the standard word for a work meeting: ter uma reunião, estar em reunião. The plural is reuniões, like all -ão/-ões nouns."},
  "a roupa": {"ipa":"RROH-pah","ex":"Vou estender a roupa lá fora.","exE":"I'm going to hang the washing outside.","note":"Usa-se no singular como coletivo — «tenho pouca roupa» — e o plural «as roupas» soa estranho em Portugal. «Roupa suja» é a roupa por lavar.","noteE":"It stays singular as a mass noun — \"tenho pouca roupa\" — and the plural \"as roupas\" sounds odd in Portugal. \"Roupa suja\" is laundry to be washed."},
  "a roupa interior": {"ipa":"RROH-pah een (nasal)-tuh-ree-OHR","ex":"Pus a roupa interior a lavar.","exE":"I put the underwear in the wash.","note":"É o termo de Portugal; no Brasil diz-se «roupa íntima». Como «roupa», fica no singular mesmo quando se fala de várias peças.","noteE":"This is the Portugal term; Brazil says \"roupa íntima\". Like \"roupa\", it stays singular even for several items."},
  "a rua": {"ipa":"ah RROO-ah","ex":"Moro na rua ao lado do mercado.","exE":"I live on the street next to the market.","note":"O \"r\" inicial é gutural, na garganta. Diz-se \"na rua\" para o inglês \"on the street\", e \"ir para a rua\" significa simplesmente sair de casa.","noteE":"The initial r is guttural, made in the throat. Use na rua for 'on the street', and note ir para a rua just means to go outside."},
  "a sala": {"ipa":"SAH-lah","ex":"Estamos na sala a ver televisão.","exE":"We're in the living room watching television.","note":"Sozinha significa quase sempre a sala de estar; com complemento passa a qualquer divisão: «sala de aula», «sala de espera», «sala de jantar».","noteE":"On its own it usually means the living room; with a complement it becomes any room: \"sala de aula\", \"sala de espera\", \"sala de jantar\"."},
  "a saúde": {"ipa":"sah-OO-duh","ex":"A minha avó tem muito boa saúde.","exE":"My grandmother is in very good health.","note":"O acento no «ú» separa as vogais, por isso são três sílabas: sa-ú-de. Sozinho, «Saúde!» é o brinde e também o que se diz a quem espirra.","noteE":"The accent on \"ú\" splits the vowels into three syllables. On its own, \"Saúde!\" is both a toast and what you say after a sneeze."},
  "a secretária": {"ipa":"suh-kruh-TAH-ree-ah","ex":"Deixei as chaves em cima da secretária.","exE":"I left the keys on the desk.","note":"Armadilha clássica: «a secretária» é a mesa de trabalho e também a profissional; o masculino «o secretário» só é pessoa.","noteE":"Classic trap: 'a secretária' means both a desk and a female secretary; the masculine 'o secretário' only means the person."},
  "a segurança": {"ipa":"ah suh-goo-RA (nasal)-sah","ex":"A segurança do edifício foi reforçada.","exE":"The building's security was tightened.","note":"Cuidado com o género: \"a segurança\" é o conceito, mas também designa a pessoa, dizendo-se \"o segurança\" para um homem que faz vigilância.","noteE":"Watch the gender: a segurança is the concept, but the same word names a security guard, and a male guard is o segurança."},
  "a semana": {"ipa":"ah suh-MAH-nah","ex":"Até para a semana!","exE":"See you next week!","note":"'Para a semana' = next week; 'fim de semana' = weekend.","noteE":"'Para a semana' = next week; 'fim de semana' = weekend."},
  "a senhora": {"ipa":"ah suh-NYAW-rah","ex":"A senhora quer pagar com cartão?","exE":"Would you like to pay by card, madam?","note":"Tratamento formal feminino, com verbo na terceira pessoa. \"Dona\" usa-se antes do primeiro nome (Dona Maria) e \"minha senhora\" é uma fórmula educada no comércio.","noteE":"The formal feminine address, with third-person verbs. Dona goes before a first name (Dona Maria), and minha senhora is the polite shop-counter formula."},
  "a situação": {"ipa":"see-twah-SOW (nasal)","ex":"A situação em casa está mais calma agora.","exE":"The situation at home is calmer now.","note":"Feminina, como todas as palavras em -ção. Coloquialmente, \"estar numa situação\" pode significar estar em apuros.","noteE":"Feminine, like every -ção noun. Colloquially \"estar numa situação\" can mean to be in a jam."},
  "a sociedade": {"ipa":"soo-see-uh-DAH-duh","ex":"A sociedade portuguesa mudou muito desde 1974.","exE":"Portuguese society has changed a lot since 1974.","note":"Além do sentido social, é o termo jurídico para company: \"sociedade anónima\" é o equivalente a uma PLC. Feminina apesar do -e.","noteE":"Besides the social sense, it is the legal word for a company: \"sociedade anónima\" is the equivalent of a PLC. Feminine despite the -e."},
  "a solução": {"ipa":"soo-loo-SOWN (nasal)","ex":"Encontrámos uma solução simples.","exE":"We found a simple solution.","note":"Diz-se «a solução para o problema» (ou «do problema»), nunca «a solução a».","noteE":"It takes 'para' or 'de': 'a solução para o problema'. Never 'solução a'."},
  "a superfície": {"ipa":"soo-puhr-FEE-see-uh","ex":"Limpa bem a superfície da mesa.","exE":"Clean the surface of the table well.","note":"«Grande superfície» é o termo usado em Portugal para hipermercado; não significa apenas uma superfície grande.","noteE":"'Grande superfície' is the Portuguese term for a hypermarket, not simply a large surface."},
  "a série": {"ipa":"ah SEH-ree-uh","ex":"Estamos a ver uma série portuguesa.","exE":"We're watching a Portuguese series.","note":"\"Uma série de\" também significa um grande número de coisas. Não confundir com \"a sério\", que quer dizer seriamente.","noteE":"Uma série de also means a whole load of something. Do not confuse it with a sério, which means seriously."},
  "a t-shirt": {"ipa":"TEE-shurt","ex":"Comprei uma t-shirt branca na feira.","exE":"I bought a white t-shirt at the market.","note":"É um empréstimo do inglês, feminino e muito corrente em Portugal. A alternativa portuguesa «camiseta» quase não se usa aqui.","noteE":"An English loanword, feminine and very common in Portugal. The native option \"camiseta\" is barely used here."},
  "a tarde": {"ipa":"TAR-duh","ex":"À tarde vou apanhar o comboio para Sintra.","exE":"In the afternoon I'm getting the train to Sintra.","note":"\"Boa tarde\" usa-se desde o meio-dia até anoitecer, muito depois do inglês \"good afternoon\". Cuidado: \"tarde\" também é advérbio, \"chegar tarde\".","noteE":"\"Boa tarde\" runs from noon until dusk, far later than English \"good afternoon\". Note \"tarde\" is also an adverb: \"chegar tarde\" (to arrive late)."},
  "a taxa": {"ipa":"ah TAH-shah","ex":"A taxa de juro subiu outra vez.","exE":"The interest rate has gone up again.","note":"Falso amigo perigoso: taxa é uma percentagem ou uma taxa administrativa, mas o imposto que se paga ao Estado é \"o imposto\". O x lê-se sh.","noteE":"A dangerous false friend: taxa is a rate or an administrative fee, while a government tax is o imposto. The x sounds like sh."},
  "a televisão": {"ipa":"tuh-luh-vee-ZOWN (nasal)","ex":"À noite gostamos de ver televisão juntos.","exE":"In the evening we like to watch television together.","note":"Em Portugal diz-se «ver televisão»; «assistir televisão» é forma brasileira (aqui seria «assistir a»). Na fala corrente abrevia-se para «a tele».","noteE":"In Portugal you \"ver televisão\"; \"assistir televisão\" is the Brazilian form (here it would need \"a\"). Casually it's shortened to \"a tele\"."},
  "a teoria": {"ipa":"tee-oo-REE-ah","ex":"Em teoria, isso funciona muito bem.","exE":"In theory, that works very well.","note":"O par fixo é «em teoria... na prática...». Note a diferença de preposição entre as duas.","noteE":"The set pairing is 'em teoria... na prática...' — note that the prepositions differ ('em' vs 'na')."},
  "a terra": {"ipa":"ah TEH-rrah","ex":"Esta terra é boa para plantar.","exE":"This soil is good for planting.","note":"Com maiúscula, \"a Terra\" é o planeta; com minúscula é solo ou a localidade de origem — \"a minha terra\" significa a minha terra natal.","noteE":"Capitalised, a Terra is the planet; lower case it's soil, and a minha terra means 'my home town', a very common way to say where you're from."},
  "a tia": {"ipa":"ah TEE-ah","ex":"A tia Ana vem jantar hoje.","exE":"Aunt Ana is coming for dinner today.","note":"Usa-se com artigo antes do nome: \"a tia Ana\". Em Portugal, as crianças tratam por \"tia\" as educadoras do infantário, mesmo sem parentesco.","noteE":"Takes an article before the name: a tia Ana. In Portugal small children call their nursery teachers tia even though there's no family tie."},
  "a técnica": {"ipa":"TEHK-nee-kah","ex":"Ele aprendeu a técnica com o avô.","exE":"He learned the technique from his grandfather.","note":"«A técnica» é o método; «o técnico» ou «a técnica» como pessoa é o especialista, e no desporto é o treinador. O «é» aberto exige o acento.","noteE":"\"A técnica\" is the method, but as a person a \"técnico/técnica\" is a specialist — and in sport, the coach. The accent marks the open \"e\"."},
  "a unidade": {"ipa":"ah oo-nee-DAH-duh","ex":"Esta unidade custa dois euros.","exE":"This unit costs two euros.","note":"Nas universidades portuguesas, uma cadeira chama-se oficialmente \"unidade curricular\". Também significa unidade no sentido de união entre pessoas.","noteE":"At Portuguese universities a module is officially called a unidade curricular. It also means unity in the sense of people being united."},
  "a universidade": {"ipa":"oo-nee-vehr-see-DAH-duh","ex":"A minha irmã estuda na universidade de Coimbra.","exE":"My sister studies at the University of Coimbra.","note":"Diz-se «andar na universidade» ou «estudar na universidade», com «na». Na conversa do dia a dia os portugueses dizem antes «a faculdade».","noteE":"You \"andar na universidade\" or \"estudar na universidade\", with \"na\". In everyday chat, Portuguese speakers say \"a faculdade\" instead."},
  "a venda": {"ipa":"ah VE (nasal)-dah","ex":"A casa está à venda desde março.","exE":"The house has been for sale since March.","note":"\"À venda\" é a expressão fixa para \"for sale\". A mesma palavra significa também a faixa que tapa os olhos.","noteE":"À venda is the set phrase for for sale. The same word also means a blindfold."},
  "a verdade": {"ipa":"ver-DAH-duh","ex":"Diz-me a verdade, não estou zangado.","exE":"Tell me the truth, I'm not angry.","note":"\"É verdade\" é a forma normal de dizer \"that's true\", e \"não é verdade?\" funciona como question tag no fim da frase. \"Na verdade\" significa \"actually\".","noteE":"\"É verdade\" is the normal way to say \"that's true\", and \"não é verdade?\" works as a question tag. \"Na verdade\" means \"actually\"."},
  "a vez": {"ipa":"ah vehsh","ex":"É a minha vez.","exE":"It's my turn.","note":"'Vez' = turn/occasion; 'uma vez' = once, 'às vezes' = sometimes.","noteE":"'Vez' = turn/occasion; 'uma vez' = once, 'às vezes' = sometimes."},
  "a viagem": {"ipa":"ah vee-AH-zhay (nasal)","ex":"Boa viagem! Manda mensagem quando chegares.","exE":"Have a good trip! Text me when you arrive.","note":"É feminina apesar de terminar em -em, e o plural é viagens. Diz-se \"fazer uma viagem\"; o verbo correspondente é viajar.","noteE":"It is feminine despite the -em ending, and the plural is viagens. You say fazer uma viagem; the verb is viajar."},
  "a vida": {"ipa":"ah VEE-dah","ex":"Assim é a vida.","exE":"That's life.","note":"'Ganhar a vida' = to earn a living.","noteE":"'Ganhar a vida' = to earn a living."},
  "a vila": {"ipa":"VEE-lah","ex":"A minha vila tem cerca de dois mil habitantes.","exE":"My town has about two thousand inhabitants.","note":"Em Portugal «vila» é uma categoria administrativa entre aldeia e cidade, não um sinónimo solto de «village».","noteE":"In Portugal 'vila' is an official rank between 'aldeia' (village) and 'cidade' (city) — not a loose word for village."},
  "a vitória": {"ipa":"ah vee-TAW-ree-ah","ex":"A vitória foi merecida.","exE":"The victory was deserved.","note":"O acento agudo abre o o. Diz-se \"conseguir uma vitória\" ou simplesmente \"ganhar\"; \"vencer\" é um pouco mais formal.","noteE":"The acute accent opens the o. You say conseguir uma vitória or just ganhar; vencer sounds slightly more formal."},
  "a volta": {"ipa":"VAWL-tah","ex":"Vamos dar uma volta depois do jantar?","exE":"Shall we go for a stroll after dinner?","note":"\"Dar uma volta\" é passear sem destino; \"à volta de\" significa à roda de ou aproximadamente; \"estar de volta\" é ter regressado.","noteE":"\"Dar uma volta\" is to go for a wander; \"à volta de\" means around or roughly; \"estar de volta\" means to be back."},
  "a vontade": {"ipa":"ah vo (nasal)-TAH-duh","ex":"Não tenho vontade de sair hoje.","exE":"I don't feel like going out today.","note":"\"Ter vontade de\" + infinitivo é a forma corrente de dizer \"apetecer\"; \"estar à vontade\" significa sentir-se descontraído.","noteE":"Ter vontade de plus an infinitive is how you say to feel like doing something; estar à vontade means to be at ease."},
  "a voz": {"ipa":"vawsh","ex":"Lê o texto em voz alta, se faz favor.","exE":"Read the text out loud, please.","note":"\"Em voz alta\" é ler ou falar alto; \"em voz baixa\" é sussurrar. No plural o o abre: \"vozes\" diz-se com o aberto.","noteE":"\"Em voz alta\" is aloud; \"em voz baixa\" is in a whisper. In the plural the o opens up: \"vozes\" has an open o."},
  "a zona": {"ipa":"ZOH-nah","ex":"Moro numa zona muito sossegada da cidade.","exE":"I live in a very quiet part of the city.","note":"Muito usada para «área» ou «bairro» na conversa do dia a dia: «a zona histórica», «zona pedonal». Também designa uma parte do corpo.","noteE":"Widely used for \"area\" or \"neighbourhood\" in everyday talk: \"a zona histórica\", \"zona pedonal\". It also refers to a part of the body."},
  "a água": {"ipa":"AH-gwah","ex":"Um copo de água, por favor.","exE":"A glass of water, please.","note":"Acento no primeiro 'á'; feminina.","noteE":"Stress on the first 'á'; feminine."},
  "a área": {"ipa":"ah AH-ree-ah","ex":"Trabalho na área da saúde.","exE":"I work in the health sector.","note":"Além de superfície, significa domínio profissional: \"a minha área é o direito\". Em futebol, \"a grande área\" é a zona de penálti.","noteE":"Beyond surface area it means a professional field: a minha área é o direito. In football a grande área is the penalty box."},
  "a árvore": {"ipa":"ah AR-voo-ruh","ex":"Sentámo-nos à sombra da árvore.","exE":"We sat in the shade of the tree.","note":"O acento marca a tónica na primeira sílaba, o que surpreende muitos aprendentes. \"Árvore genealógica\" é a árvore de família.","noteE":"The accent puts the stress on the first syllable, which surprises many learners. Árvore genealógica is a family tree."},
  "a época": {"ipa":"EH-poo-kah","ex":"Na época alta, os hotéis ficam caríssimos.","exE":"In high season, hotels get extremely expensive.","note":"É a época turística ou desportiva; as estações do ano são \"as estações\" (primavera, verão...). \"Na época\" também significa \"naquele tempo\".","noteE":"It means a tourist or sporting season; the seasons of the year are \"as estações\" (primavera, verão...). \"Na época\" can also mean \"back then\"."},
  "abaixo": {"ipa":"ah-BYE-shoo","ex":"As notas estão abaixo da média.","exE":"The marks are below average.","note":"Usa-se com \"de\" e tem sentido abstrato ou de escala (abaixo de zero). \"Mais abaixo\" remete para um ponto mais adiante num texto.","noteE":"It takes de and carries an abstract or scale meaning, as in abaixo de zero. Mais abaixo points further down a text."},
  "abandonar": {"ipa":"ah-bah (nasal)-doo-NAR","ex":"Ele abandonou o curso a meio.","exE":"He dropped out of the course halfway through.","note":"Regular. É mais forte do que «deixar» e implica largar algo ou alguém definitivamente.","noteE":"Regular. It is stronger than deixar and implies giving something or someone up for good."},
  "aberto": {"ipa":"uh-BEHR-too","ex":"O museu está aberto até às seis.","exE":"The museum is open until six.","note":"É particípio irregular de \"abrir\" e usa-se sobretudo com \"estar\" para o estado. Concorda: aberta, abertos, abertas.","noteE":"It is the irregular participle of \"abrir\" and is used mainly with \"estar\" for the state. It agrees: aberta, abertos, abertas."},
  "aborrecido": {"ipa":"uh-boo-rruh-SEE-doo","ex":"O filme foi um bocado aborrecido.","exE":"The film was a bit boring.","note":"Com \"ser\" a coisa é maçadora; com \"estar\" a pessoa está chateada ou zangada. Concorda: aborrecida, aborrecidos, aborrecidas.","noteE":"With \"ser\" the thing is dull; with \"estar\" the person is annoyed or upset. It agrees: aborrecida, aborrecidos, aborrecidas."},
  "abrir": {"ipa":"ah-BREER","ex":"As lojas abrem às dez horas.","exE":"The shops open at ten.","note":"Regular na conjugação, mas com particípio passado irregular: aberto, não abrido. O mesmo acontece com cobrir e coberto.","noteE":"Regular in conjugation, but with an irregular past participle: aberto, not abrido. The same happens with cobrir and coberto."},
  "acabar": {"ipa":"ah-kah-BAR","ex":"Acabei de chegar a casa.","exE":"I've just got home.","note":"Acabar de mais infinitivo é a forma portuguesa de dizer ter feito algo agora mesmo. Acabar por significa acabar por acontecer, contra o previsto.","noteE":"Acabar de plus an infinitive is the Portuguese way of saying you have just done something. Acabar por means to end up doing something, against expectation."},
  "aceitar": {"ipa":"ah-say-TAR","ex":"Este café não aceita cartão.","exE":"This café doesn't take card.","note":"Tem dois particípios: «aceitado» com ter e «aceite» com ser ou estar. Em Portugal usa-se «aceite» e não «aceito».","noteE":"It has two participles: aceitado with ter, aceite with ser/estar. Portugal uses aceite, not the Brazilian aceito."},
  "achar": {"ipa":"ah-SHAR","ex":"Acho que sim.","exE":"I think so.","note":"'Achar que' = to think that (opinião); 'acho que sim/não'.","noteE":"'Achar que' = to think that (opinion); 'acho que sim' = I think so."},
  "acima": {"ipa":"ah-SEE-mah","ex":"A temperatura está acima dos trinta graus.","exE":"The temperature is above thirty degrees.","note":"Usa-se com \"de\" e tem valor mais abstrato ou de medida do que \"em cima de\". \"Acima de tudo\" significa sobretudo.","noteE":"It takes de and is more abstract or measurement-based than em cima de. Acima de tudo means above all."},
  "acompanhar": {"ipa":"ah-ko (nasal)-pah-NYAR","ex":"Queres que te acompanhe até à paragem?","exE":"Do you want me to walk you to the bus stop?","note":"Não leva preposição antes do complemento: acompanho-te. Também significa seguir algo, como acompanhar um jogo ou as notícias.","noteE":"No preposition before the object: acompanho-te. It also means to follow something, like a match or the news."},
  "acontecer": {"ipa":"ah-koh (nasal)-tuh-SEHR","ex":"O que aconteceu à tua bicicleta?","exE":"What happened to your bike?","note":"Usa-se quase só na terceira pessoa e pede a para indicar a quem: aconteceu-me uma coisa estranha. Na fala corrente diz-se muito passar-se.","noteE":"It is used almost only in the third person and takes a for the person affected: aconteceu-me uma coisa estranha. In everyday speech passar-se is very common instead."},
  "acreditar": {"ipa":"ah-kruh-dee-TAR","ex":"Não acredito em fantasmas.","exE":"I don't believe in ghosts.","note":"Pede «em» antes de nome (acreditar em alguém) e «que» antes de frase. Não confundir com «achar», que exprime opinião.","noteE":"Takes em before a noun (acreditar em alguém) and que before a clause. Don't confuse it with achar, which expresses an opinion."},
  "acrescentar": {"ipa":"ah-kresh-seh (nasal)-TAR","ex":"Acrescenta um pouco de sal à sopa.","exE":"Add a bit of salt to the soup.","note":"Acrescentar algo a algo — juntar a um conjunto que já existe, sobretudo ingredientes e palavras. Para somar números usa-se somar.","noteE":"Acrescentar algo a algo — adding to something that already exists, typically ingredients or remarks. For adding numbers use somar."},
  "acusar": {"ipa":"ah-koo-ZAR","ex":"Acusaram-no de mentir.","exE":"They accused him of lying.","note":"Acusar alguém de algo ou de + infinitivo. Depois de forma verbal terminada em -m, o pronome o passa a no: acusaram-no.","noteE":"Acusar someone de something or de + infinitive. After a verb form ending in -m, the pronoun o becomes no: acusaram-no."},
  "adeus": {"ipa":"ah-DEH-oosh","ex":"Adeus, foi um prazer.","exE":"Goodbye, it was a pleasure.","note":"Mais definitivo do que 'até já' ou 'até logo'.","noteE":"More final than 'até já' or 'até logo' (see you soon / later)."},
  "admitir": {"ipa":"ahd-mee-TEER","ex":"Admito que me enganei.","exE":"I admit I got it wrong.","note":"Admitir que + indicativo quando se confessa um facto, mas + conjuntivo quando se aceita uma hipótese. Também significa contratar (a empresa admitiu dez pessoas).","noteE":"Admitir que + indicative when confessing a fact, but + subjunctive when entertaining a possibility. It also means to hire (a empresa admitiu dez pessoas)."},
  "adquirir": {"ipa":"ahd-kee-REER","ex":"A empresa adquiriu novos equipamentos.","exE":"The company acquired new equipment.","note":"Registo formal ou comercial; no dia a dia diz-se comprar ou arranjar. Conjuga-se regularmente: eu adquiro, ele adquire, eles adquirem.","noteE":"Formal or commercial register; day to day you say comprar or arranjar. It conjugates regularly: eu adquiro, ele adquire, eles adquirem."},
  "afastar": {"ipa":"ah-fash-TAR","ex":"Afasta-te da beira, por favor.","exE":"Move away from the edge, please.","note":"Afastar algo ou alguém de; o uso mais frequente é o reflexo afastar-se de. No imperativo o pronome vem depois, com hífen: afasta-te.","noteE":"Afastar something or someone de; the commonest use is reflexive afastar-se de. In the imperative the pronoun follows with a hyphen: afasta-te."},
  "afirmar": {"ipa":"ah-feer-MAR","ex":"O ministro afirmou que tudo estava bem.","exE":"The minister stated that everything was fine.","note":"Pertence ao registo formal e jornalístico; na conversa diz-se dizer. Afirmar que leva indicativo, porque exprime certeza.","noteE":"It belongs to formal and journalistic register; in conversation you say dizer. Afirmar que takes the indicative, since it expresses certainty."},
  "agora": {"ipa":"ah-GAW-rah","ex":"Agora não posso falar contigo.","exE":"I can't talk to you now.","note":"\"Agora mesmo\" reforça a ideia de imediato e \"por agora\" significa por enquanto. Pode abrir a frase ou vir depois do verbo.","noteE":"Agora mesmo intensifies it to right now and por agora means for the time being. It can open the sentence or follow the verb."},
  "ajudar": {"ipa":"ah-zhoo-DAR","ex":"Ajudas-me a levar as compras?","exE":"Will you help me carry the shopping?","note":"Antes de outro verbo leva «a»: ajudar alguém a fazer algo. O nome correspondente é «a ajuda».","noteE":"Before another verb it takes a: ajudar alguém a fazer algo. The related noun is a ajuda."},
  "alcançar": {"ipa":"ahl-kah (nasal)-SAR","ex":"Não alcanço a prateleira de cima.","exE":"I can't reach the top shelf.","note":"Alterna ç e c consoante a vogal seguinte: eu alcanço, tu alcanças, que ele alcance. Leva objeto direto, tanto no sentido físico como no de atingir um objetivo.","noteE":"Alternates ç and c depending on the following vowel: eu alcanço, tu alcanças, que ele alcance. Takes a direct object, both physically and for reaching a goal."},
  "alegre": {"ipa":"uh-LEH-gruh","ex":"É uma pessoa muito alegre.","exE":"She is a very cheerful person.","note":"Forma única para os dois géneros, plural \"alegres\". Costuma vir depois do nome e refere-se mais ao feitio do que ao estado passageiro.","noteE":"One form for both genders, plural \"alegres\". It usually follows the noun and describes character rather than a passing mood."},
  "algo": {"ipa":"AL-goo","ex":"Há algo estranho nesta sopa.","exE":"There is something strange in this soup.","note":"É mais formal ou escrito do que alguma coisa, que domina na conversa. Como advérbio significa um pouco: algo cansado.","noteE":"More formal or written than alguma coisa, which dominates in conversation. As an adverb it means somewhat: algo cansado, somewhat tired."},
  "algum / alguma": {"ipa":"al-GOO (nasal) / al-GOO-mah","ex":"Tens algum trocado para o autocarro?","exE":"Do you have any change for the bus?","note":"Antes do substantivo tem sentido positivo, mas depois do substantivo torna-se enfático e negativo: não há dúvida alguma quer dizer nenhuma dúvida.","noteE":"Before the noun it is positive, but after the noun it becomes emphatic and negative: não há dúvida alguma means no doubt at all."},
  "alguém": {"ipa":"al-GEH (nasal)","ex":"Está alguém à porta.","exE":"There is someone at the door.","note":"Invariável e sem plural; leva sempre verbo no singular. Refere-se apenas a pessoas, ao contrário de algo.","noteE":"Invariable and with no plural; it always takes a singular verb. It refers only to people, unlike algo."},
  "ali / lá": {"ipa":"ah-LEE / lah","ex":"O teu telemóvel está ali, em cima da mesa.","exE":"Your mobile is there, on the table.","note":"\"Ali\" indica um sítio visível que se aponta; \"lá\" é mais distante ou vago e usa-se com movimento (vou lá). \"Aí\" refere o sítio onde está a pessoa com quem falas.","noteE":"Ali points to a visible spot, while lá is vaguer or farther and pairs with movement. Aí refers to where the person you are speaking to is."},
  "alimentar": {"ipa":"ah-lee-meh (nasal)-TAR","ex":"Alimenta o gato antes de saíres.","exE":"Feed the cat before you go out.","note":"Alimentar alguém ou algo; alimentar-se de é comer habitualmente. Também é figurado: alimentar esperanças, alimentar um conflito.","noteE":"Alimentar someone or something; alimentar-se de means to feed on something habitually. Also figurative: alimentar esperanças, to nurse hopes."},
  "alto": {"ipa":"AHL-too","ex":"A minha irmã é mais alta do que eu.","exE":"My sister is taller than me.","note":"Serve para altura de pessoas e de coisas e concorda: alta, altos, altas. Também funciona como advérbio invariável de volume: fala mais alto.","noteE":"It covers the height of people and things and agrees: alta, altos, altas. It also works as an invariable adverb of volume: fala mais alto."},
  "amanhã": {"ipa":"ah-mah-NYA (nasal)","ex":"Amanhã tenho de acordar cedo.","exE":"Tomorrow I have to get up early.","note":"Não confundir com \"de manhã\" (in the morning): amanhã de manhã junta os dois. \"Depois de amanhã\" é dentro de dois dias.","noteE":"Keep it apart from de manhã (in the morning); amanhã de manhã combines both. Depois de amanhã is the day after tomorrow."},
  "amar": {"ipa":"ah-MAR","ex":"Amo-te mais do que tudo.","exE":"I love you more than anything.","note":"Em Portugal é forte e reservado a relações profundas; para o dia a dia diz-se gostar muito de ou adorar. Pronome enclítico: amo-te.","noteE":"In Portugal it is strong and reserved for deep relationships; day to day people say gostar muito de or adorar. Enclitic pronoun: amo-te."},
  "amarelo": {"ipa":"uh-muh-REH-loo","ex":"Aquela casa amarela é a minha.","exE":"That yellow house is mine.","note":"Concorda normalmente: amarela, amarelos, amarelas. Em compostos fica invariável: paredes amarelo-claro.","noteE":"It agrees normally: amarela, amarelos, amarelas. In compounds it stays invariable: paredes amarelo-claro."},
  "analisar": {"ipa":"ah-nah-lee-ZAR","ex":"Vamos analisar os resultados amanhã.","exE":"We'll analyse the results tomorrow.","note":"Escreve-se com s e não com z, tal como análise e analista. Regular em -ar, transitivo direto.","noteE":"Spelt with s, not z, like análise and analista. A regular -ar verb taking a direct object."},
  "andar": {"ipa":"ah (nasal)-DAR","ex":"Ando a estudar português há um ano.","exE":"I've been studying Portuguese for a year.","note":"Com a mais infinitivo exprime uma atividade que dura há algum tempo, construção muito portuguesa. Com de indica meio de transporte: andar de comboio.","noteE":"With a plus an infinitive it expresses an activity going on over a stretch of time, a very Portuguese construction. With de it gives the means of transport: andar de comboio."},
  "antes": {"ipa":"AN (nasal)-tush","ex":"Antes, vivia numa aldeia pequena.","exE":"Before, I lived in a small village.","note":"Sozinho é advérbio; com complemento usa-se \"antes de\" + nome ou infinitivo. A conjunção \"antes que\" pede sempre o conjuntivo (antes que seja tarde).","noteE":"Alone it is an adverb; with a complement use antes de plus noun or infinitive. The conjunction antes que always takes the subjunctive."},
  "anunciar": {"ipa":"ah-noo (nasal)-see-AR","ex":"Anunciaram os resultados esta manhã.","exE":"They announced the results this morning.","note":"Regular. Serve para dar uma notícia e para pôr anúncios: anunciar um carro para venda.","noteE":"Regular. It covers announcing news and placing adverts: anunciar um carro para venda."},
  "apanhar": {"ipa":"ah-pah-NYAR","ex":"Apanhei o comboio das oito.","exE":"I caught the eight o'clock train.","note":"É o verbo europeu para apanhar transportes, sol, chuva ou uma constipação. Os brasileiros dizem «pegar» nestes casos.","noteE":"This is the European verb for catching transport, sun, rain or a cold. Brazilians use pegar in these cases."},
  "aparecer": {"ipa":"ah-pah-ruh-SEHR","ex":"Ele apareceu sem avisar.","exE":"He showed up without warning.","note":"Primeira pessoa com ç: eu apareço. Não confundir com parecer, que é dar a impressão de algo.","noteE":"The first person takes ç: eu apareço. Don't confuse it with parecer, which is to seem."},
  "aperceber-se": {"ipa":"ah-puhr-suh-BEHR-suh","ex":"Não me apercebi de que estavas ali.","exE":"I didn't realise you were there.","note":"Usa-se sempre reflexo e pede «de»: apercebi-me do erro. Difere de «perceber», que é compreender.","noteE":"Always reflexive and takes de: apercebi-me do erro. It differs from perceber, which means to understand."},
  "apesar de": {"ipa":"ah-puh-ZAR duh","ex":"Apesar de estar cansado, saiu com os amigos.","exE":"Despite being tired, he went out with his friends.","note":"Usa-se com nome ou infinitivo; se o sujeito for diferente, usa-se o infinitivo pessoal (apesar de tu estares cansado). A variante \"apesar de que\" pede conjuntivo e é rara.","noteE":"It takes a noun or an infinitive, switching to the personal infinitive when the subject differs. The rarer apesar de que takes the subjunctive."},
  "aplicar": {"ipa":"ah-plee-KAR","ex":"Vou aplicar o creme nas mãos.","exE":"I'm going to apply the cream to my hands.","note":"Aplicar rege a ou em: aplicar uma regra a um caso, aplicar dinheiro em ações. O reflexo aplicar-se a quer dizer «dizer respeito a».","noteE":"Aplicar takes a or em: aplicar uma regra a um caso, aplicar dinheiro em ações. The reflexive aplicar-se a means 'to concern / to be relevant to'."},
  "apoiar": {"ipa":"ah-poo-YAR","ex":"Apoio-te nessa decisão.","exE":"I'm behind you on that decision.","note":"Apoiar alguém leva objeto direto e pronome enclítico (apoio-te, apoiámo-lo). Apoiar-se em significa encostar-se ou basear-se.","noteE":"Apoiar alguém takes a direct object with the pronoun attached (apoio-te). Apoiar-se em means to lean on, or to be based on."},
  "apontar": {"ipa":"ah-po (nasal)-TAR","ex":"Ele apontou para o outro lado da rua.","exE":"He pointed to the other side of the street.","note":"Pede «para» quando se indica uma direção. Também significa tomar nota: apontei o número dele.","noteE":"It takes para when indicating a direction. It also means to jot down: apontei o número dele."},
  "aprender": {"ipa":"ah-preh (nasal)-DEHR","ex":"Estou a aprender a nadar.","exE":"I'm learning to swim.","note":"Aprender a + infinitivo quando se trata de uma competência; sem preposição para matérias (aprender português). Não confundir com apreender, que é captar ou confiscar.","noteE":"Aprender a + infinitive for a skill; no preposition for subjects (aprender português). Don't confuse it with apreender, to grasp or to seize."},
  "apresentar": {"ipa":"ah-pruh-zeh (nasal)-TAR","ex":"Deixa-me apresentar-te a minha irmã.","exE":"Let me introduce you to my sister.","note":"Apresenta-se alguém a alguém. A forma reflexiva serve para nos darmos a conhecer: apresento-me, chamo-me Rui.","noteE":"You apresentar someone a someone else. The reflexive is how you introduce yourself: apresento-me, chamo-me Rui."},
  "aproveitar": {"ipa":"ah-proo-vay-TAR","ex":"Aproveita o sol enquanto dura.","exE":"Make the most of the sun while it lasts.","note":"Aproveitar algo (objeto direto) ou aproveitar para + infinitivo. Aproveitar-se de tem sentido negativo: tirar partido de alguém.","noteE":"Aproveitar something (direct object), or aproveitar para + infinitive. Aproveitar-se de is negative: to take advantage of someone."},
  "aproximar": {"ipa":"ah-proo-see-MAR","ex":"O comboio aproxima-se da estação.","exE":"The train is approaching the station.","note":"Quase sempre reflexo e com de: aproximar-se de alguém ou de algo. Na forma não reflexa aproxima-se uma coisa de outra (aproximou a cadeira da mesa).","noteE":"Nearly always reflexive and with de: aproximar-se de someone or something. Non-reflexively you bring one thing closer to another (aproximou a cadeira da mesa)."},
  "aquele / aquela": {"ipa":"ah-KAY-luh / ah-KEH-lah","ex":"Aquele prédio ali é a escola.","exE":"That building over there is the school.","note":"Indica o que está longe de ambos os falantes. Contrai-se com a, de e em, com acento grave na primeira: àquele, daquela, naquele.","noteE":"Points to what is far from both speakers. It contracts with a, de and em, taking a grave accent in the first: àquele, daquela, naquele."},
  "aqueles / aquelas": {"ipa":"ah-KAY-lush / ah-KEH-lush","ex":"Aquelas senhoras estão à espera.","exE":"Those ladies over there are waiting.","note":"Plural de aquele e aquela, com as mesmas contrações: àqueles, daquelas, naqueles. Também serve para falar de tempos distantes: naqueles anos.","noteE":"The plural of aquele and aquela, with the same contractions: àqueles, daquelas, naqueles. It also works for distant times: naqueles anos, in those years."},
  "aqui / cá": {"ipa":"ah-KEE / kah","ex":"Anda cá, o jantar já está aqui na mesa.","exE":"Come here, dinner is already here on the table.","note":"\"Aqui\" aponta um ponto preciso; \"cá\" é mais vago e aparece com verbos de movimento (vem cá, chega cá). Com preposição contrai-se: daqui, por aqui.","noteE":"Aqui pins down a precise spot, while cá is vaguer and pairs with verbs of motion. With prepositions it contracts, giving daqui and por aqui."},
  "aquilo": {"ipa":"ah-KEE-loo","ex":"Aquilo ali é um moinho.","exE":"That thing over there is a windmill.","note":"Neutro e invariável, para algo distante e não nomeado; contrai-se em àquilo, daquilo e naquilo. Aplicado a pessoas soa depreciativo.","noteE":"Neuter and invariable, for something distant and unnamed; it contracts to àquilo, daquilo and naquilo. Applied to people it sounds dismissive."},
  "as": {"ipa":"ash","ex":"As chaves estão em cima da mesa.","exE":"The keys are on top of the table.","note":"Com preposições, contrai: a + as = às, de + as = das, em + as = nas, por + as = pelas. Essas contrações são obrigatórias.","noteE":"Contractions with prepositions are compulsory, never optional: às, das, nas, pelas. Saying 'de as' instead of 'das' marks you instantly as a learner."},
  "as calças": {"ipa":"KAHL-sash","ex":"Estas calças ficam-me um pouco largas.","exE":"These trousers are a bit loose on me.","note":"Só existe no plural, como em inglês: para uma peça diz-se «um par de calças» ou simplesmente «umas calças».","noteE":"Plural only, like English: for a single item say \"um par de calças\" or just \"umas calças\"."},
  "as costas": {"ipa":"ash KAWSH-tash","ex":"Tenho as costas doridas de estar sentado.","exE":"My back is sore from sitting.","note":"Usa-se sempre no plural em português: \"as costas\", nunca \"a costa\" para o corpo. \"A costa\" no singular significa o litoral.","noteE":"Always plural for the body part. The singular a costa means a coastline, so watch the number carefully."},
  "as meias": {"ipa":"MAY-ash","ex":"Tenho os pés frios, vou pôr meias.","exE":"My feet are cold, I'm going to put socks on.","note":"«Meia» também significa metade («meia hora»), mas atenção: usar «meia» para o número seis ao telefone é hábito brasileiro — em Portugal diz-se «seis».","noteE":"\"Meia\" also means half (\"meia hora\"), but using it for the digit six on the phone is a Brazilian habit — in Portugal say \"seis\"."},
  "assim": {"ipa":"ah-SEE (nasal)","ex":"Faz assim, é mais fácil.","exE":"Do it like this, it's easier.","note":"\"Assim que\" significa logo que e pede o futuro do conjuntivo. \"Mesmo assim\" quer dizer apesar disso e \"assim-assim\" é mais ou menos.","noteE":"The connective assim que means as soon as and takes the future subjunctive. Mesmo assim means even so, and assim-assim means so-so."},
  "assim que": {"ipa":"ah-SEE (nasal) kuh","ex":"Assim que chegar a casa, telefono-te.","exE":"As soon as I get home, I'll call you.","note":"Para o futuro pede o futuro do conjuntivo (assim que puderes); para o passado leva indicativo (assim que chegou). Sinónimos: \"logo que\" e \"mal\".","noteE":"For the future it takes the future subjunctive, but for past events the indicative. Logo que and mal are close synonyms."},
  "assistir": {"ipa":"ah-seesh-TEER","ex":"Assisti ao jogo na televisão.","exE":"I watched the match on TV.","note":"Assistir A algo quando se vê ou se está presente (assistir ao filme, à aula) — a preposição é obrigatória em Portugal. Sem preposição significa prestar assistência.","noteE":"Assistir A something when watching or attending (assistir ao filme, à aula) — the preposition is obligatory in Portugal. Without it the verb means to assist."},
  "assustador": {"ipa":"uh-soosh-tuh-DOR","ex":"Foi um filme assustador.","exE":"It was a scary film.","note":"Faz o feminino em \"assustadora\" e o plural em \"assustadores, assustadoras\". Descreve o que provoca medo; a pessoa com medo está \"assustada\".","noteE":"The feminine is \"assustadora\" and the plurals are \"assustadores, assustadoras\". It describes what causes fear; the frightened person is \"assustada\"."},
  "atingir": {"ipa":"ah-tee (nasal)-ZHEER","ex":"A temperatura atingiu os quarenta graus.","exE":"The temperature reached forty degrees.","note":"O «g» passa a «j» antes de «a» e «o»: atinjo, atinja. Usa-se sobretudo para valores, objetivos e limites.","noteE":"The g becomes j before a and o: atinjo, atinja. It is used mostly for figures, goals and limits."},
  "atirar": {"ipa":"ah-tee-RAR","ex":"Atirou a bola por cima do muro.","exE":"He threw the ball over the wall.","note":"Atirar algo a ou para alguém; atirar-se a é lançar-se sobre alguém ou algo. Para deitar no lixo os portugueses dizem antes deitar fora.","noteE":"Atirar something a or para someone; atirar-se a means to hurl oneself at something. For throwing things out, Portuguese prefers deitar fora."},
  "atrasado": {"ipa":"uh-truh-ZAH-doo","ex":"O comboio está atrasado vinte minutos.","exE":"The train is twenty minutes late.","note":"Usa-se com \"estar\" ou \"chegar\": cheguei atrasada. Concorda com quem se atrasa: atrasada, atrasados, atrasadas.","noteE":"Use it with \"estar\" or \"chegar\": cheguei atrasada. It agrees with whoever is late: atrasada, atrasados, atrasadas."},
  "atravessar": {"ipa":"ah-trah-vuh-SAR","ex":"Atravessa a rua na passadeira.","exE":"Cross the road at the crossing.","note":"Leva objeto direto — atravessar a rua, nunca «atravessar pela rua». Também é figurado: atravessar uma fase difícil.","noteE":"Takes a direct object — atravessar a rua, never 'atravessar pela rua'. Also figurative: atravessar uma fase difícil, to go through a rough patch."},
  "atribuir": {"ipa":"ah-tree-BWEER","ex":"Atribuíram-lhe o primeiro prémio.","exE":"They gave him first prize.","note":"Verbo em -uir: eu atribuo, ele atribui, eles atribuem; leva acento quando o i é tónico (atribuí, atribuíram). Atribuir algo a alguém.","noteE":"An -uir verb: eu atribuo, ele atribui, eles atribuem; the i takes an accent when stressed (atribuí, atribuíram). Atribuir something a someone."},
  "atrás": {"ipa":"ah-TRAHSH","ex":"Senta-te atrás, há mais espaço.","exE":"Sit at the back, there's more room.","note":"Pede \"de\": atrás da porta. Evita-se \"há dois anos atrás\", que é redundante; diz-se apenas \"há dois anos\".","noteE":"It takes de, as in atrás da porta. Avoid há dois anos atrás as redundant; just say há dois anos."},
  "até": {"ipa":"ah-TEH","ex":"Trabalho até às seis da tarde.","exE":"I work until six in the afternoon.","note":"Além de \"until\", significa também \"even\" (até eu percebi isso). Nas despedidas usa-se em fórmulas fixas: até já, até logo, até amanhã.","noteE":"Besides 'until', it also means 'even': até eu percebi isso ('even I understood that'). It powers the standard goodbyes: até já, até logo, até amanhã."},
  "até à próxima": {"ipa":"ah-TEH ah PRAW-see-mah","ex":"Obrigado por tudo, até à próxima!","exE":"Thanks for everything, until next time!","note":"Literalmente 'até à próxima (vez)'.","noteE":"Literally 'until the next (time)'."},
  "aumentar": {"ipa":"ow-meh (nasal)-TAR","ex":"Os preços aumentaram muito este ano.","exE":"Prices went up a lot this year.","note":"Serve como transitivo e intransitivo: aumentar o volume ou o preço aumentou. O contrário é «diminuir».","noteE":"Works both transitively and intransitively: aumentar o volume or o preço aumentou. The opposite is diminuir."},
  "avançar": {"ipa":"ah-vah (nasal)-SAR","ex":"A esta hora o trânsito não avança.","exE":"At this time of day the traffic doesn't move.","note":"Cedilha antes de a/o: eu avanço, tu avanças, que ele avance. Avançar com um projeto é pô-lo em marcha; avançar para é dirigir-se a.","noteE":"Cedilla before a/o: eu avanço, tu avanças, que ele avance. Avançar com a project means to push ahead with it; avançar para means to move towards."},
  "azul": {"ipa":"uh-ZOOL","ex":"Ela tem os olhos azuis.","exE":"She has blue eyes.","note":"Não muda no feminino, mas o plural é irregular: azuis. Depois do nome, como todas as cores.","noteE":"It does not change in the feminine, but the plural is irregular: azuis. It goes after the noun, like all colours."},
  "baixar": {"ipa":"buy-SHAR","ex":"Baixa o volume da televisão.","exE":"Turn the television down.","note":"Transitivo (baixar o volume) ou intransitivo (os preços baixaram). Para ficheiros, em Portugal diz-se transferir ou descarregar, nunca «baixar».","noteE":"Transitive (baixar o volume) or intransitive (os preços baixaram). For files, Portugal says transferir or descarregar, never 'baixar'."},
  "baixo": {"ipa":"BYE-shoo","ex":"Ele é baixo, mas joga muito bem.","exE":"He is short, but he plays very well.","note":"É o contrário de \"alto\" e concorda: baixa, baixos, baixas. Como advérbio fica invariável: fala mais baixo, por favor.","noteE":"It is the opposite of \"alto\" and agrees: baixa, baixos, baixas. As an adverb it stays invariable: fala mais baixo, por favor."},
  "barato": {"ipa":"buh-RAH-too","ex":"Este restaurante é bom e barato.","exE":"This restaurant is good and cheap.","note":"Concorda: barata, baratos, baratas, mas atenção, \"barata\" também é o inseto. Como advérbio fica invariável: comprei barato.","noteE":"It agrees: barata, baratos, baratas, but beware, \"barata\" is also the insect. As an adverb it stays invariable: comprei barato."},
  "bastante": {"ipa":"bash-TAN (nasal)-tuh","ex":"Ela fala bastante bem português.","exE":"She speaks Portuguese quite well.","note":"Invariável antes de adjetivos e advérbios; como determinante faz plural \"bastantes\" (bastantes pessoas). Significa \"bastante mesmo\", mais do que o \"enough\" inglês.","noteE":"It is invariable before adjectives and adverbs but pluralises to bastantes as a determiner. It means quite a lot, stronger than English enough."},
  "bastar": {"ipa":"bash-TAR","ex":"Basta! Já chega de barulho.","exE":"Enough! No more noise.","note":"Impessoal, na 3.ª pessoa: basta + infinitivo (basta pedir). Com pronome indireto significa ser suficiente para alguém: basta-me isto.","noteE":"Impersonal, third person only: basta + infinitive (basta pedir, you only have to ask). With an indirect pronoun it means enough for someone: basta-me isto."},
  "bater": {"ipa":"bah-TEHR","ex":"Alguém está a bater à porta.","exE":"Someone is knocking at the door.","note":"Bater «à» porta é bater com a mão; bater «em» alguém é agredir. Também se bate um recorde e se batem os ovos.","noteE":"Bater à porta is to knock; bater em alguém is to hit a person. You also bater um recorde (break a record) and beat eggs."},
  "beber": {"ipa":"buh-BEHR","ex":"Bebes um café comigo?","exE":"Will you have a coffee with me?","note":"Regular em -er. Para convites usa-se o presente do indicativo, onde o inglês usa «will you». Ao balcão, tomar um café é ainda mais comum do que beber.","noteE":"A regular -er verb. Invitations use the simple present where English uses 'will you'. At the counter, tomar um café is even commoner than beber."},
  "bem": {"ipa":"beh (nasal)","ex":"Ela fala muito bem inglês.","exE":"She speaks English very well.","note":"\"Bem\" é advérbio e modifica o verbo; \"bom\" é adjetivo e concorda com o nome. O comparativo é \"melhor\".","noteE":"Bem is the adverb modifying a verb, while bom is the adjective agreeing with a noun. Its comparative form is melhor."},
  "bem como": {"ipa":"beh (nasal) KOH-moo","ex":"Convidámos os pais, bem como os avós.","exE":"We invited the parents, as well as the grandparents.","note":"Conector aditivo de registo cuidado, que liga sobretudo grupos nominais e vem depois de vírgula. O verbo concorda normalmente com o primeiro elemento.","noteE":"It is a careful-register additive connector, mostly joining noun phrases after a comma. The verb usually agrees with the first element only."},
  "boa noite": {"ipa":"BOH-ah NOY-tuh","ex":"Boa noite, até amanhã.","exE":"Good night, see you tomorrow.","note":"Serve para cumprimentar à noite e para despedir-se ao deitar.","noteE":"Used both to greet in the evening and to say goodnight."},
  "boa sorte!": {"ipa":"BOH-ah SOR-tuh","ex":"Boa sorte no exame!","exE":"Good luck on the exam!","note":"'Sorte' é luck; 'ter sorte' = to be lucky.","noteE":"'Sorte' means luck; 'ter sorte' = to be lucky."},
  "boa tarde": {"ipa":"BOH-ah TAR-duh","ex":"Boa tarde, posso entrar?","exE":"Good afternoon, may I come in?","note":"Do meio-dia até ao pôr do sol.","noteE":"From noon until sunset."},
  "bom": {"ipa":"bo (nasal)","ex":"Está um bom dia.","exE":"It's a nice day.","note":"Masculino; feminino 'boa'. Vogal nasal.","noteE":"Masculine; feminine 'boa'. Nasal vowel."},
  "bom dia": {"ipa":"bo (nasal) DEE-ah","ex":"Bom dia! Um café, por favor.","exE":"Good morning! A coffee, please.","note":"Usa-se até ao meio-dia; depois passa a 'boa tarde'.","noteE":"Used until noon; after that it becomes 'boa tarde'."},
  "bonito": {"ipa":"boo-NEE-too","ex":"Que vista bonita!","exE":"What a lovely view!","note":"Feminino 'bonita'; sinónimo de 'lindo'.","noteE":"Feminine 'bonita'; a synonym of 'lindo'."},
  "branco": {"ipa":"BRA (nasal)-koo","ex":"Ela vestiu uma camisa branca.","exE":"She put on a white shirt.","note":"Como todas as cores, vem depois do nome e concorda: branca, brancos, brancas. Note-se a expressão \"deu-me um branco\", esqueci-me.","noteE":"Like all colours it follows the noun and agrees: branca, brancos, brancas. Note the idiom \"deu-me um branco\", I drew a blank."},
  "burro": {"ipa":"BOO-rroo","ex":"Não sejas burro, pensa bem.","exE":"Don't be dumb, think it through.","note":"É coloquial e ofensivo se dirigido a alguém; entre amigos passa por brincadeira. Concorda: burra, burros, burras.","noteE":"It is colloquial and insulting when aimed at someone; among friends it passes as teasing. It agrees: burra, burros, burras."},
  "buscar": {"ipa":"boosh-KAR","ex":"Vou buscar as crianças à escola.","exE":"I'm going to fetch the children from school.","note":"Em Portugal aparece quase sempre em ir buscar = apanhar e trazer, com a preposição a do sítio (à escola, ao aeroporto). Sozinho, no sentido de procurar, é literário.","noteE":"In Portugal it almost always appears as ir buscar = go and get, with a for the place (à escola, ao aeroporto). On its own, meaning 'to seek', it is literary."},
  "caber": {"ipa":"kah-BEHR","ex":"Não cabe mais nada na mala.","exE":"Nothing else will fit in the suitcase.","note":"Irregular: eu caibo, ele cabe, pretérito coube, conjuntivo caiba. Caber a alguém é ser da responsabilidade dessa pessoa: cabe-te a ti decidir.","noteE":"Irregular: eu caibo, ele cabe, past coube, subjunctive caiba. Caber a alguém means it is that person's responsibility: cabe-te a ti decidir."},
  "cada": {"ipa":"KAH-dah","ex":"Cada aluno tem um livro.","exE":"Each pupil has a book.","note":"Invariável e sempre seguido de substantivo no singular; nunca leva artigo. Sozinho, exige um ou uma: cada um recebeu o seu.","noteE":"Invariable and always followed by a singular noun; it never takes an article. On its own it needs um or uma: cada um recebeu o seu."},
  "cair": {"ipa":"kah-EER","ex":"O telemóvel caiu ao chão.","exE":"The phone fell on the floor.","note":"O a e o i são sílabas separadas: ca-ir, ca-í. Cair bem significa assentar bem, seja de roupa, seja de comida.","noteE":"The a and i are separate syllables: ca-ir, ca-í. Cair bem means to suit you, said both of clothes and of food that agrees with you."},
  "calmamente": {"ipa":"kahl-mah-MEH (nasal)-tuh","ex":"Ele explicou tudo calmamente.","exE":"He explained everything calmly.","note":"Vem do adjetivo \"calma\" e descreve o modo da ação, ficando depois do verbo. Na conversa diz-se mais \"com calma\".","noteE":"It derives from the adjective calma and describes manner, sitting after the verb. In conversation com calma is heard more often."},
  "calmo": {"ipa":"KAHL-moo","ex":"O mar estava calmo esta manhã.","exE":"The sea was calm this morning.","note":"Com \"ser\" descreve o feitio, com \"estar\" o momento: ela é calma, mas hoje não está. Concorda: calma, calmos, calmas.","noteE":"With \"ser\" it describes character, with \"estar\" the moment: ela é calma, mas hoje não está. It agrees: calma, calmos, calmas."},
  "cansado": {"ipa":"ka (nasal)-SAH-doo","ex":"Estou cansado, vou deitar-me cedo.","exE":"I am tired, I am going to bed early.","note":"Vai sempre com \"estar\" ou \"ficar\", nunca com \"ser\". Com \"de\" significa estar farto: estou cansada de esperar.","noteE":"It always goes with \"estar\" or \"ficar\", never \"ser\". With \"de\" it means fed up: estou cansada de esperar."},
  "cantar": {"ipa":"kah (nasal)-TAR","ex":"Ela está a cantar no duche.","exE":"She's singing in the shower.","note":"Verbo regular em -ar e o modelo da primeira conjugação. Note estar a cantar, a forma portuguesa do progressivo.","noteE":"A regular -ar verb and the model for the first conjugation. Note estar a cantar, the European Portuguese progressive."},
  "caracterizar": {"ipa":"kah-rahk-tuh-ree-ZAR","ex":"O que caracteriza esta região é o vinho.","exE":"What defines this region is its wine.","note":"Caracterizar-se por é ter algo como traço distintivo. Em Portugal o c antes de t pronuncia-se (carac-terizar), ao contrário de outras variantes.","noteE":"Caracterizar-se por means to be marked by a distinguishing feature. In Portugal the c before t is pronounced (carac-terizar), unlike in other varieties."},
  "caro": {"ipa":"KAH-roo","ex":"Os bilhetes estão muito caros este ano.","exE":"The tickets are very expensive this year.","note":"Depois do nome significa \"dispendioso\"; antes do nome, numa carta, significa \"querido\": Caro Senhor. Concorda: cara, caros, caras.","noteE":"After the noun it means \"costly\"; before the noun, in a letter, it means \"dear\": Caro Senhor. It agrees: cara, caros, caras."},
  "casar": {"ipa":"kah-ZAR","ex":"Ela casou com um português.","exE":"She married a Portuguese man.","note":"Pede «com», nunca complemento direto: casar com alguém. A forma «casar-se» também existe e é um pouco mais formal.","noteE":"It takes com, never a direct object: casar com alguém. The form casar-se also exists and is slightly more formal."},
  "castanho": {"ipa":"kush-TA (nasal)-nyoo","ex":"Ela tem o cabelo castanho e curto.","exE":"She has short brown hair.","note":"Em Portugal usa-se \"castanho\" e não \"marrom\", que é brasileiro. Concorda: castanha, castanhos, castanhas.","noteE":"In Portugal you use \"castanho\" and not \"marrom\", which is Brazilian. It agrees: castanha, castanhos, castanhas."},
  "causar": {"ipa":"kow-ZAR","ex":"A chuva causou muitos atrasos.","exE":"The rain caused a lot of delays.","note":"Regular. Usa-se sobretudo com consequências negativas: causar problemas, danos, dores ou má impressão.","noteE":"Regular. It is used mostly with negative consequences: causar problemas, danos, dores."},
  "cedo": {"ipa":"SAY-doo","ex":"Acordo sempre muito cedo.","exE":"I always wake up very early.","note":"É só advérbio, nunca adjetivo. Usa-se muito em \"mais cedo ou mais tarde\" e no diminutivo afetuoso \"cedinho\".","noteE":"It works only as an adverb, never as an adjective describing a noun. Note the set phrase mais cedo ou mais tarde and the affectionate diminutive cedinho."},
  "certamente / decerto": {"ipa":"sehr-tah-MEH (nasal)-tuh / duh-SEHR-too","ex":"Ele certamente já chegou a casa.","exE":"He has certainly already arrived home.","note":"\"Decerto\" é muito português e escreve-se numa palavra. Ambos podem vir antes ou depois do verbo; na fala usa-se sobretudo \"com certeza\".","noteE":"Decerto is distinctly European Portuguese and is written as one word. Both can precede or follow the verb, though spoken Portuguese prefers com certeza."},
  "certo": {"ipa":"SEHR-too","ex":"Acho que esta é a resposta certa.","exE":"I think this is the right answer.","note":"Depois do nome significa \"correto\" (a hora certa); antes do nome significa \"um certo\", indefinido (um certo senhor). Com pessoas usa-se \"ter razão\", não \"estar certo\".","noteE":"After the noun it means \"correct\" (a hora certa); before the noun it means \"a certain\", unspecified (um certo senhor). For people you say \"ter razão\", not \"estar certo\"."},
  "chamar": {"ipa":"shah-MAR","ex":"Ela chama-se Beatriz.","exE":"Her name is Beatriz.","note":"Na forma reflexiva dá o nome de alguém, e em Portugal o pronome vai depois do verbo na afirmativa: chamo-me, chama-se. Na negativa passa para a frente: não me chamo.","noteE":"The reflexive gives someone's name, and in Portugal the pronoun follows the verb in statements: chamo-me, chama-se. In the negative it moves in front: não me chamo."},
  "chato": {"ipa":"SHAH-too","ex":"Que chato, perdi as chaves outra vez.","exE":"How annoying, I lost my keys again.","note":"Em Portugal cobre \"aborrecido\" e \"irritante\", conforme o contexto. É muito coloquial e concorda: chata, chatos, chatas.","noteE":"In Portugal it covers both \"boring\" and \"annoying\", depending on context. It is very colloquial and agrees: chata, chatos, chatas."},
  "chegar": {"ipa":"shuh-GAR","ex":"O comboio chega às nove.","exE":"The train arrives at nine.","note":"Em Portugal chega-se a um sítio, nunca em. Usado sozinho significa bastar: chega!, já chega de conversa.","noteE":"In Portugal you chegar a a place, never em. Used alone it means to be enough: chega!, that's enough."},
  "chorar": {"ipa":"shoo-RAR","ex":"O bebé chorou a noite toda.","exE":"The baby cried all night.","note":"É intransitivo; para dizer por quem ou porquê usa-se por (chorar por alguém). Expressão corrente: rir até chorar.","noteE":"It is intransitive; to say who or what you are crying over, use por (chorar por alguém). A common phrase: rir até chorar, to laugh till you cry."},
  "cinzento": {"ipa":"see (nasal)-ZEH (nasal)-too","ex":"O céu está cinzento e vai chover.","exE":"The sky is grey and it is going to rain.","note":"Esta é a forma europeia; no Brasil diz-se \"cinza\". Vem depois do nome e concorda: cinzenta, cinzentos, cinzentas.","noteE":"This is the European form; in Brazil they say \"cinza\". It follows the noun and agrees: cinzenta, cinzentos, cinzentas."},
  "citar": {"ipa":"see-TAR","ex":"Citou o poeta de cor.","exE":"He quoted the poet from memory.","note":"Transitivo direto: citar alguém, citar um exemplo. Em linguagem jurídica significa convocar alguém para tribunal.","noteE":"Takes a direct object: citar alguém, citar um exemplo. In legal language it means to summon someone to court."},
  "claro": {"ipa":"KLAH-roo","ex":"O quarto é claro e tem uma janela grande.","exE":"The room is bright and has a big window.","note":"Nas cores fica depois e é invariável em género quando composto: olhos azuis-claros. Sozinho, \"claro!\" significa \"of course\".","noteE":"With colours it comes after and joins as a compound: olhos azuis-claros. On its own, \"claro!\" means \"of course\"."},
  "cobrir": {"ipa":"koo-BREER","ex":"Cobre a panela com a tampa.","exE":"Cover the pan with the lid.","note":"Particípio irregular: coberto, nunca «cobrido». O radical alterna no presente: eu cubro, tu cobres, eles cobrem.","noteE":"Irregular participle: coberto, never 'cobrido'. The stem alternates in the present: eu cubro, tu cobres, eles cobrem."},
  "colocar": {"ipa":"koo-loo-KAR","ex":"Coloca os livros na estante.","exE":"Put the books on the shelf.","note":"É mais cuidado do que pôr, que domina na conversa: põe aí. O c passa a qu antes de e: coloquei.","noteE":"It is more careful than pôr, which dominates in conversation: põe aí. The c becomes qu before e: coloquei."},
  "com": {"ipa":"koh (nasal)","ex":"Vou ao cinema com os meus amigos.","exE":"I'm going to the cinema with my friends.","note":"Com os pronomes forma palavras especiais: comigo, contigo, connosco (em Portugal, não \"conosco\"), convosco.","noteE":"With pronouns it fuses irregularly: comigo, contigo, connosco. Note the European spelling connosco with double n — conosco is Brazilian."},
  "com licença": {"ipa":"co (nasal) lee-SEN-sah","ex":"Com licença, deixa-me passar.","exE":"Excuse me, let me get by.","note":"Para pedir passagem ou interromper; 'desculpe' é para pedir desculpa.","noteE":"To get past someone or interrupt; use 'desculpe' to apologise."},
  "comer": {"ipa":"koo-MEHR","ex":"Comemos peixe grelhado ao almoço.","exE":"We had grilled fish for lunch.","note":"Para a refeição da manhã diz-se «tomar o pequeno-almoço», não «comer». «Comer fora» é ir ao restaurante.","noteE":"For the morning meal you say tomar o pequeno-almoço, not comer. Comer fora means to eat out."},
  "começar": {"ipa":"koo-muh-SAR","ex":"O filme começa daqui a pouco.","exE":"The film starts shortly.","note":"Pede a antes de infinitivo (começou a chover) e por para indicar a primeira etapa (comecei por ler). O ç passa a c antes de e: comecei.","noteE":"It takes a before an infinitive (começou a chover) and por for the first step in a sequence (comecei por ler). The ç becomes c before e: comecei."},
  "como?": {"ipa":"KOH-moo","ex":"Como é que vais para o trabalho?","exE":"How do you get to work?","note":"Em Portugal acrescenta-se quase sempre \"é que\" nas perguntas diretas. Sozinho, \"Como?\" significa \"Desculpe, pode repetir?\".","noteE":"Everyday European Portuguese nearly always adds \"é que\" in direct questions. On its own, \"Como?\" means \"Sorry, could you repeat that?\"."},
  "completar": {"ipa":"koh (nasal)-pluh-TAR","ex":"Ela completou o curso no ano passado.","exE":"She finished the course last year.","note":"Completar anos é fazer anos (completou trinta anos). O particípio completado usa-se com ter; completo é adjetivo e concorda (obra completa).","noteE":"Completar anos means to turn an age (completou trinta anos). The participle completado goes with ter; completo is an adjective and agrees (obra completa)."},
  "compor": {"ipa":"koh (nasal)-POHR","ex":"Ele compôs a música do filme.","exE":"He composed the film's music.","note":"Composto de pôr: eu componho, ele compõe, pretérito compus/compôs. Compor-se de significa ser formado por.","noteE":"A compound of pôr: eu componho, ele compõe, past compus/compôs. Compor-se de means to be made up of."},
  "comprar": {"ipa":"ko (nasal)-PRAR","ex":"Comprei pão fresco na padaria.","exE":"I bought fresh bread at the bakery.","note":"A pessoa a quem se compra leva «a»: comprei o carro a um amigo. O contrário é «vender».","noteE":"The person you buy from takes a: comprei o carro a um amigo. The opposite is vender."},
  "comprido": {"ipa":"koh (nasal)-PREE-doo","ex":"Ela tem o cabelo muito comprido.","exE":"She has very long hair.","note":"Usa-se para comprimento físico; para duração diz-se \"longo\" (um filme longo). Vem depois do nome e concorda: comprida, compridos, compridas.","noteE":"Use it for physical length; for duration say \"longo\" (um filme longo). It follows the noun and agrees: comprida, compridos, compridas."},
  "concluir": {"ipa":"ko (nasal)-kloo-EER","ex":"Concluí o curso no ano passado.","exE":"I finished the course last year.","note":"Conjuga-se como «construir»: concluo, concluis, conclui. Serve para terminar algo e para tirar uma conclusão.","noteE":"It follows construir: concluo, concluis, conclui. It covers both finishing something and drawing a conclusion."},
  "conduzir": {"ipa":"koh (nasal)-doo-ZEER","ex":"Ainda não sei conduzir.","exE":"I still can't drive.","note":"Em Portugal conduz-se um carro — dirigir tem outro sentido (chefiar). Verbo em -uzir: ele conduz, sem vogal final; conduzir a também é levar a um resultado.","noteE":"In Portugal you conduzir a car — dirigir here means to run or manage something. An -uzir verb: ele conduz, with no final vowel; conduzir a also means to lead to a result."},
  "confirmar": {"ipa":"koh (nasal)-feer-MAR","ex":"Podes confirmar a reserva por email?","exE":"Can you confirm the booking by email?","note":"Transitivo direto; confirmar-se significa revelar-se verdadeiro (a notícia confirmou-se). Repare no tu podes, forma informal corrente em Portugal.","noteE":"Takes a direct object; confirmar-se means to prove true (a notícia confirmou-se). Note tu podes, the everyday informal form in Portugal."},
  "conhecer": {"ipa":"koo-nyuh-SER","ex":"Conheces Lisboa?","exE":"Do you know Lisbon?","note":"Conhecer = conhecer pessoas/lugares; 'saber' = saber factos.","noteE":"Conhecer = to know people/places; 'saber' = to know facts."},
  "conhecido": {"ipa":"koo-nyuh-SEE-doo","ex":"É um restaurante muito conhecido aqui.","exE":"It is a very well known restaurant here.","note":"Menos forte do que \"famoso\" e usa-se também como nome: um conhecido meu. Concorda: conhecida, conhecidos, conhecidas.","noteE":"Weaker than \"famoso\" and also used as a noun: um conhecido meu. It agrees: conhecida, conhecidos, conhecidas."},
  "conquistar": {"ipa":"koh (nasal)-keesh-TAR","ex":"Conquistou o público com a voz.","exE":"She won the audience over with her voice.","note":"Transitivo direto, sem preposição; serve tanto para territórios como para simpatias e prémios. O nome correspondente é a conquista.","noteE":"Takes a direct object with no preposition; it works for territory, for affections and for prizes alike. The related noun is a conquista."},
  "conseguir": {"ipa":"ko (nasal)-suh-GEER","ex":"Não consigo abrir a porta.","exE":"I can't open the door.","note":"= to manage / be able to; irregular: 'consigo, consegues'.","noteE":"= to manage / be able to; irregular: 'consigo, consegues'."},
  "considerar": {"ipa":"koh (nasal)-see-duh-RAR","ex":"Considero isso uma boa ideia.","exE":"I consider that a good idea.","note":"Liga-se diretamente ao complemento, sem como: considero-o competente. Considerar que introduz uma opinião.","noteE":"It links straight to its complement, with no como: considero-o competente. Considerar que introduces an opinion."},
  "consistir": {"ipa":"koh (nasal)-seesh-TEER","ex":"O trabalho consiste em atender clientes.","exE":"The job consists of dealing with customers.","note":"Consistir EM, nunca «de» (consiste em três partes, consiste em ouvir). Usa-se praticamente só na 3.ª pessoa.","noteE":"Consistir EM, never 'de' (consiste em três partes, consiste em ouvir). Used almost exclusively in the third person."},
  "constituir": {"ipa":"koh (nasal)-shtee-too-EER","ex":"Isto constitui um grave problema.","exE":"This constitutes a serious problem.","note":"Verbo formal, típico de textos jurídicos e institucionais; na fala usa-se ser ou formar. Segue o padrão dos verbos em -uir: constituo, constitui.","noteE":"A formal verb, typical of legal and institutional texts; in speech ser or formar is used. It follows the -uir pattern: constituo, constitui."},
  "construir": {"ipa":"ko (nasal)-shtroo-EER","ex":"Estão a construir um hotel na praia.","exE":"They're building a hotel on the beach.","note":"Irregular no presente: construo, constróis, constrói, construímos, constroem. Note o acento aberto no «ó».","noteE":"Irregular present: construo, constróis, constrói, construímos, constroem. Note the open ó."},
  "contar": {"ipa":"koh (nasal)-TAR","ex":"Conta-me o que aconteceu ontem.","exE":"Tell me what happened yesterday.","note":"Serve para números e para histórias. Com com significa confiar em alguém: conta comigo.","noteE":"It covers both counting numbers and telling stories. With com it means to rely on someone: conta comigo, count on me."},
  "conter": {"ipa":"ko (nasal)-TEHR","ex":"Esta bebida não contém açúcar.","exE":"This drink contains no sugar.","note":"Conjuga-se como «ter»: contenho, contém, contêm, contive. «Conter-se» é controlar as emoções.","noteE":"It conjugates like ter: contenho, contém, contêm, contive. Conter-se means to hold yourself back."},
  "continuar": {"ipa":"ko (nasal)-tee-noo-AR","ex":"Continua em frente.","exE":"Carry straight on.","note":"'Continuar a + infinitivo' = to keep doing something.","noteE":"'Continuar a + infinitive' = to keep doing something."},
  "contra": {"ipa":"KOH (nasal)-trah","ex":"Somos todos contra essa decisão.","exE":"We are all against that decision.","note":"É invariável, nunca leva \"s\" no plural. Usa-se em desporto (Portugal contra Espanha) e em remédios (xarope contra a tosse).","noteE":"Invariable — it never agrees or takes a plural. Used for fixtures (Portugal contra Espanha) and for remedies: xarope contra a tosse, 'cough syrup'."},
  "contribuir": {"ipa":"koh (nasal)-tree-BWEER","ex":"Cada um contribuiu com dez euros.","exE":"Each of us chipped in ten euros.","note":"Contribuir COM a quantia e PARA o objetivo (contribuiu com dinheiro para a obra). Verbo em -uir: eu contribuo, ele contribui, eu contribuí.","noteE":"Contribuir COM the amount and PARA the purpose (contribuiu com dinheiro para a obra). An -uir verb: eu contribuo, ele contribui, eu contribuí."},
  "conversar": {"ipa":"koh (nasal)-vuhr-SAR","ex":"Conversámos até tarde no café.","exE":"We chatted until late at the café.","note":"Conversar com alguém sobre algo; falar é mais neutro, conversar implica troca demorada. O acento em conversámos distingue o pretérito do presente conversamos.","noteE":"Conversar com someone sobre something; falar is more neutral, conversar implies a proper exchange. The accent in conversámos marks the past against present conversamos."},
  "cor-de-laranja": {"ipa":"kawr-duh-luh-RA (nasal)-zhuh","ex":"Ele trouxe uma mochila cor-de-laranja.","exE":"He brought an orange backpack.","note":"É invariável, tal como \"cor-de-rosa\": sapatos cor-de-laranja, nunca \"cor-de-laranjas\". Vem sempre depois do nome.","noteE":"It is invariable, just like \"cor-de-rosa\": sapatos cor-de-laranja, never \"cor-de-laranjas\". It always follows the noun."},
  "cor-de-rosa": {"ipa":"kor-duh-RRAW-zah","ex":"Ela comprou uma mochila cor-de-rosa.","exE":"She bought a pink backpack.","note":"É invariável: não muda no feminino nem no plural (um casaco cor-de-rosa, umas sapatilhas cor-de-rosa). Em Portugal escreve-se com hífenes.","noteE":"It never changes form, staying the same in the feminine and the plural. In Portugal it keeps its hyphens; colour names built from a noun like this stay invariable."},
  "correr": {"ipa":"koo-RREHR","ex":"Corro no parque todas as manhãs.","exE":"I run in the park every morning.","note":"Também se usa para o decorrer das coisas: como correu o exame? O duplo rr lê-se com o som gutural da garganta.","noteE":"It is also used for how things go: como correu o exame? The double rr is the guttural throat sound."},
  "corresponder": {"ipa":"koo-rrush-poh (nasal)-DEHR","ex":"O preço não corresponde à qualidade.","exE":"The price doesn't match the quality.","note":"Corresponder A algo, com contração (ao, à). Corresponder-se com alguém é trocar cartas ou mensagens regularmente.","noteE":"Corresponder A something, contracted (ao, à). Corresponder-se com alguém means to exchange letters or messages regularly."},
  "cortar": {"ipa":"koor-TAR","ex":"Cortei o dedo a cortar pão.","exE":"I cut my finger cutting bread.","note":"Transitivo direto; a + infinitivo exprime a ação simultânea (a cortar pão). Cortar com alguém significa acabar a relação.","noteE":"Takes a direct object; a + infinitive expresses the simultaneous action (a cortar pão). Cortar com alguém means to break off a relationship."},
  "crescer": {"ipa":"krush-SEHR","ex":"As crianças crescem muito depressa.","exE":"Children grow up so fast.","note":"O «c» passa a «ç» antes de «a» e «o»: cresço, cresça. É intransitivo, por isso não leva complemento direto.","noteE":"The c becomes ç before a and o: cresço, cresça. It is intransitive, so it takes no direct object."},
  "criar": {"ipa":"kree-AR","ex":"Os meus avós criaram cinco filhos.","exE":"My grandparents raised five children.","note":"Significa tanto inventar como educar filhos ou criar animais. O i é tónico e forma sílaba própria: cri-ar, cri-o.","noteE":"It covers both inventing and bringing up children or rearing animals. The i is stressed and forms its own syllable: cri-ar, cri-o."},
  "cumprir": {"ipa":"koo (nasal)-PREER","ex":"Ele cumpriu a promessa que fez.","exE":"He kept the promise he made.","note":"Transitivo direto: cumprir a lei, um horário, uma pena. Cumprir-se significa realizar-se; cumprimentar (saudar) é da mesma família mas não é sinónimo.","noteE":"Takes a direct object: cumprir a lei, um horário, uma pena. Cumprir-se means to come true; cumprimentar (to greet) is related but not a synonym."},
  "curto": {"ipa":"KOOR-too","ex":"O vestido é demasiado curto para mim.","exE":"The dress is too short for me.","note":"É o contrário de \"comprido\" e serve para objetos e para tempo: uma pausa curta. Concorda: curta, curtos, curtas.","noteE":"It is the opposite of \"comprido\" and works for objects and for time: uma pausa curta. It agrees: curta, curtos, curtas."},
  "custar": {"ipa":"koosh-TAR","ex":"Quanto custa o bilhete de autocarro?","exE":"How much does the bus ticket cost?","note":"Usa-se sobretudo na 3.ª pessoa. Custa-me + infinitivo significa «é-me difícil»: custa-me acordar cedo.","noteE":"Used mostly in the third person. Custa-me + infinitive means 'I find it hard to': custa-me acordar cedo, I struggle to wake up early."},
  "dado que": {"ipa":"DAH-doo kuh","ex":"Dado que está a chover, ficamos em casa.","exE":"Given that it's raining, we'll stay at home.","note":"Conector causal de registo formal, com indicativo, normalmente a abrir a frase. Sem \"que\", \"dado\" concorda com o nome: dada a situação, dados os factos.","noteE":"It is a formal causal connector taking the indicative, usually opening the sentence. Without que, dado agrees with its noun, as in dada a situação."},
  "dar": {"ipa":"dar","ex":"Dá-me um copo de água.","exE":"Give me a glass of water.","note":"Em muitas expressões: 'dar um passeio', 'dar-se bem'.","noteE":"In many phrases: 'dar um passeio' (take a walk), 'dar-se bem' (get along)."},
  "de": {"ipa":"duh","ex":"Sou de Coimbra, mas moro no Porto.","exE":"I'm from Coimbra, but I live in Porto.","note":"Contrai com artigos e demonstrativos: do, da, dos, das, deste, disso, dele. Também exprime posse, onde o inglês usa 'apóstrofo s': o carro do João.","noteE":"There is no 's possessive in Portuguese: 'John's car' is o carro do João. De also swallows following words — do, da, deste, dele — and those contractions are obligatory."},
  "de nada": {"ipa":"duh NAH-dah","ex":"— Obrigado! — De nada.","exE":"— Thank you! — You're welcome.","note":"Literalmente 'de nada'; também se ouve 'não tem de quê'.","noteE":"Literally 'of nothing'; you'll also hear 'não tem de quê'."},
  "decidir": {"ipa":"duh-see-DEER","ex":"Decidimos ficar mais uma noite.","exE":"We decided to stay one more night.","note":"Liga-se diretamente ao infinitivo (decidi ir). Na forma reflexa, «decidir-se» pede «por»: decidiu-se pelo comboio.","noteE":"It links straight to an infinitive (decidi ir). Reflexive decidir-se takes por: decidiu-se pelo comboio."},
  "declarar": {"ipa":"duh-klah-RAR","ex":"Declarou que não sabia de nada.","exE":"He stated that he knew nothing about it.","note":"Declarar que + indicativo. Declarar-se é confessar sentimentos ou assumir uma posição. Muito usado no fisco: declarar rendimentos.","noteE":"Declarar que + indicative. Declarar-se means to declare your feelings or take a public stance. Very common in tax contexts: declarar rendimentos."},
  "dedicar": {"ipa":"duh-dee-KAR","ex":"Dedico as manhãs ao estudo.","exE":"I devote my mornings to studying.","note":"Dedicar algo a alguém ou a algo, com contração (ao estudo, à família). Dedicar-se a é ocupar-se de uma atividade a tempo inteiro.","noteE":"Dedicar something a someone or something, contracted (ao estudo, à família). Dedicar-se a means to devote oneself to an activity."},
  "defender": {"ipa":"duh-feh (nasal)-DEHR","ex":"Ele defendeu a irmã na discussão.","exE":"He stood up for his sister in the argument.","note":"Regular. «Defender-se de» é proteger-se de algo, e no futebol o guarda-redes «defende» a bola.","noteE":"Regular. Defender-se de means to protect yourself from something; in football the keeper defende (saves) the ball."},
  "definir": {"ipa":"duh-fee-NEER","ex":"Ainda não definimos a data.","exE":"We haven't settled on the date yet.","note":"Regular em -ir. No dia a dia usa-se muito no sentido de fixar ou decidir algo, como definir uma hora ou um preço.","noteE":"A regular -ir verb. In everyday use it often means to set or fix something, like a time or a price."},
  "deitar-se": {"ipa":"day-TAR-suh","ex":"Deito-me sempre antes da meia-noite.","exE":"I always go to bed before midnight.","note":"Pronominal: deito-me, deitas-te, deita-se, deitamo-nos. Sem pronome, deitar é pôr ou despejar — e deitar fora significa mandar para o lixo.","noteE":"Pronominal: deito-me, deitas-te, deita-se, deitamo-nos. Without the pronoun, deitar means to pour or put — and deitar fora is the European way to say 'throw away'."},
  "deixar": {"ipa":"day-SHAR","ex":"Deixa a chave em cima da mesa.","exE":"Leave the key on the table.","note":"Com de mais infinitivo significa parar de fazer algo: deixei de fumar. Sem preposição significa permitir: deixa-me ver.","noteE":"With de plus an infinitive it means to stop doing something: deixei de fumar, I gave up smoking. With no preposition it means to let: deixa-me ver."},
  "dela": {"ipa":"DEH-lah","ex":"A mala dela é azul.","exE":"Her bag is blue.","note":"Contração de de + ela, invariável e colocada depois do substantivo. Atenção ao contraste de vogais: dela tem e aberto e dele tem e fechado.","noteE":"A contraction of de + ela, invariable and placed after the noun. Mind the vowel contrast: dela has an open e, dele a closed one."},
  "dele": {"ipa":"DAY-luh","ex":"Este é o carro dele.","exE":"This is his car.","note":"Contração de de + ele; é invariável e vem sempre depois do substantivo. Concorda com o dono (masculino singular), nunca com a coisa possuída: a casa dele, os livros dele.","noteE":"A contraction of de + ele; it never changes form and always follows the noun. It agrees with the owner (masculine singular), never with the thing owned: a casa dele, os livros dele."},
  "deles / delas": {"ipa":"DAY-lush / DEH-lush","ex":"Os filhos deles estudam cá.","exE":"Their children study here.","note":"Contrações de de + eles e de + elas; escolhe-se a forma pelo género dos donos, não pela coisa possuída. Um grupo misto leva sempre deles.","noteE":"Contractions of de + eles and de + elas; the form depends on the gender of the owners, not of the thing owned. A mixed group always takes deles."},
  "demasiado / demais": {"ipa":"duh-mah-zee-AH-doo / duh-MYSH","ex":"Está demasiado calor para andar a pé.","exE":"It's too hot to walk.","note":"\"Demasiado\" é invariável como advérbio, mas concorda como determinante (demasiada gente, demasiados carros). \"Demais\" vem depois do verbo: comi demais.","noteE":"Demasiado is invariable as an adverb but agrees as a determiner. Demais follows the verb, as in comi demais."},
  "demonstrar": {"ipa":"duh-moh (nasal)sh-TRAR","ex":"Ele demonstrou muita paciência.","exE":"He showed a great deal of patience.","note":"Registo formal; na fala corrente usa-se mostrar. Demonstrar que + indicativo. Não confundir com manifestar-se, que é protestar na rua.","noteE":"Formal register; in everyday speech people say mostrar. Demonstrar que + indicative. Don't confuse it with manifestar-se, to demonstrate in the street."},
  "dentro": {"ipa":"DEH (nasal)-troo","ex":"As chaves estão dentro da mala.","exE":"The keys are inside the bag.","note":"Usa-se \"dentro de\" + nome; \"cá dentro\" refere o interior onde estamos. Com tempo, \"dentro de uma hora\" significa daqui a uma hora.","noteE":"Use dentro de plus a noun, and cá dentro for the inside where you are. With time expressions dentro de uma hora means within an hour."},
  "depender": {"ipa":"duh-peh (nasal)-DEHR","ex":"Depende do tempo que fizer amanhã.","exE":"It depends on the weather tomorrow.","note":"Pede sempre «de»: depende de ti, depende do preço. Sozinho, «depende» é uma resposta muito usada.","noteE":"It always takes de: depende de ti, depende do preço. On its own, depende is a very common reply."},
  "depois": {"ipa":"duh-POYSH","ex":"Depois do jantar, vamos passear.","exE":"After dinner, we'll go for a walk.","note":"Com complemento é \"depois de\" + nome ou infinitivo (depois de comer). Para orações com sujeito diferente usa-se o infinitivo pessoal: depois de tu saíres.","noteE":"With a complement it becomes depois de plus noun or infinitive. When the subjects differ, use the personal infinitive, as in depois de tu saíres."},
  "depressa": {"ipa":"duh-PREH-sah","ex":"Anda depressa, vamos perder o autocarro!","exE":"Hurry up, we're going to miss the bus!","note":"É a palavra do dia a dia para rapidamente e nunca funciona como adjetivo (aí usa-se \"rápido\"). Muito usada em \"o mais depressa possível\".","noteE":"This is the everyday word for quickly and never works as an adjective, where rápido is used instead. It appears often in o mais depressa possível."},
  "desaparecer": {"ipa":"duh-zah-pah-ruh-SEHR","ex":"As chaves desapareceram outra vez.","exE":"The keys have vanished again.","note":"Intransitivo — não leva objeto direto; para «fazer desaparecer» usa-se mesmo essa perífrase. Conjuga-se como conhecer, com ç antes de a/o: eu desapareço.","noteE":"Intransitive — it takes no direct object; to say 'make something disappear' you use fazer desaparecer. Conjugated like conhecer, with ç before a/o: eu desapareço."},
  "descer": {"ipa":"dush-SEHR","ex":"Desço na próxima paragem.","exE":"I'm getting off at the next stop.","note":"Contrário de «subir». O «c» passa a «ç» antes de «a» e «o»: desço, desça. Usa-se também para sair de um transporte.","noteE":"The opposite of subir. The c becomes ç before a and o: desço, desça. It is also how you say to get off a bus or train."},
  "descobrir": {"ipa":"dush-koo-BREER","ex":"Descobri um café ótimo perto de casa.","exE":"I found a great café near home.","note":"Conjuga-se como «cobrir», com o particípio irregular «descoberto». No presente: descubro, descobres, descobre.","noteE":"It follows cobrir and has the irregular participle descoberto. Present: descubro, descobres, descobre."},
  "desconhecido": {"ipa":"dush-koo-nyuh-SEE-doo","ex":"O número que ligou era desconhecido.","exE":"The number that called was unknown.","note":"Também funciona como nome, \"um desconhecido\", para um estranho. Concorda: desconhecida, desconhecidos, desconhecidas.","noteE":"It also works as a noun, \"um desconhecido\", meaning a stranger. It agrees: desconhecida, desconhecidos, desconhecidas."},
  "descrever": {"ipa":"dush-kruh-VEHR","ex":"Descreve-me a casa, por favor.","exE":"Describe the house to me, please.","note":"Particípio irregular descrito, tal como escrever dá escrito. Descrever algo a alguém, com enclítico: descreve-me.","noteE":"Irregular participle descrito, just as escrever gives escrito. Descrever something a someone, with the pronoun attached: descreve-me."},
  "desculpa": {"ipa":"dush-KOOL-pah","ex":"Desculpa o atraso!","exE":"Sorry I'm late!","note":"Informal (tu); com amigos e família.","noteE":"Informal (tu); with friends and family."},
  "desculpe": {"ipa":"dush-KOOL-puh","ex":"Desculpe, onde fica a estação?","exE":"Excuse me, where is the station?","note":"Formal (você); a versão informal é 'desculpa'.","noteE":"Formal (você); the informal version is 'desculpa'."},
  "desde": {"ipa":"DESH-duh","ex":"Moro aqui desde 2010.","exE":"I've lived here since 2010.","note":"Com \"desde\" usa-se o presente onde o inglês usa o present perfect: \"espero desde as três\" = tenho estado à espera. Também marca origem espacial: desde o Porto até Faro.","noteE":"Portuguese uses the present tense with desde where English needs 'have been': espero desde as três = 'I have been waiting since three'."},
  "desejar": {"ipa":"duh-zuh-ZHAR","ex":"Desejo-lhe um bom fim de semana.","exE":"I wish you a good weekend.","note":"Registo formal, típico de lojas e cartas, com pronome enclítico (desejo-lhe, desejamos-vos). No dia a dia usa-se querer ou apetecer.","noteE":"Formal register, typical of shops and letters, with the enclitic pronoun (desejo-lhe, desejamos-vos). Day to day you use querer or apetecer."},
  "desenvolver": {"ipa":"duh-zeh (nasal)-vol-VEHR","ex":"A empresa está a desenvolver uma aplicação nova.","exE":"The company is developing a new app.","note":"Regular em -er. Reflexivamente, «desenvolver-se» aplica-se a crianças, plantas e projetos que crescem ou evoluem.","noteE":"A regular -er verb. Reflexive desenvolver-se is used for children, plants or projects that grow and evolve."},
  "designar": {"ipa":"duh-zeeg-NAR","ex":"Foi designado para o cargo.","exE":"He was appointed to the post.","note":"Designar alguém para um cargo; designar-se significa chamar-se, em registo formal. O g antes de n pronuncia-se, ao contrário do que acontece em inglês.","noteE":"Designar someone para a post; designar-se means 'to be called', in formal register. The g before n is pronounced, unlike in English."},
  "desonesto": {"ipa":"duh-zoo-NEHSH-too","ex":"Foi uma jogada desonesta.","exE":"It was a dishonest move.","note":"Vem depois do nome e concorda: desonesta, desonestos, desonestas. Usa-se com \"ser\", tal como \"honesto\".","noteE":"It follows the noun and agrees: desonesta, desonestos, desonestas. Use it with \"ser\", just like \"honesto\"."},
  "destacar": {"ipa":"dush-tah-KAR","ex":"O professor destacou dois erros comuns.","exE":"The teacher highlighted two common mistakes.","note":"Antes de «e» escreve-se «qu»: destaquei, destaque. «Destacar-se» é sobressair num grupo.","noteE":"Spelling changes to qu before e: destaquei, destaque. Destacar-se means to stand out in a group."},
  "determinar": {"ipa":"duh-tuhr-mee-NAR","ex":"O exame vai determinar o tratamento.","exE":"The test will determine the treatment.","note":"Registo formal, comum em textos técnicos e legais. «Estar determinado a» significa estar decidido a fazer algo.","noteE":"A formal register, common in technical and legal texts. Estar determinado a means to be set on doing something."},
  "devagar": {"ipa":"duh-vah-GAR","ex":"Fala mais devagar, por favor.","exE":"Speak more slowly, please.","note":"É invariável e não tem forma em -mente. O diminutivo \"devagarinho\" é muito usado e o contrário é \"depressa\".","noteE":"It is invariable and has no -mente form. The diminutive devagarinho is very common, and its opposite is depressa."},
  "dever": {"ipa":"duh-VEHR","ex":"Deves chegar antes das oito.","exE":"You should arrive before eight.","note":"Seguido de infinitivo exprime obrigação; com de exprime probabilidade: deve de estar em casa. Sozinho com objeto significa ter uma dívida: devo-te dez euros.","noteE":"Followed by an infinitive it expresses obligation; with de it expresses likelihood: deve de estar em casa, he must be at home. With a direct object it means to owe: devo-te dez euros."},
  "diferente": {"ipa":"dee-fuh-REH (nasal)-tuh","ex":"Este queijo é diferente do outro.","exE":"This cheese is different from the other one.","note":"Igual nos dois géneros, plural \"diferentes\", e liga-se com \"de\". Antes do nome significa \"vários\": diferentes pessoas disseram o mesmo.","noteE":"The same in both genders, plural \"diferentes\", and it links with \"de\". Before the noun it means \"various\": diferentes pessoas disseram o mesmo."},
  "difícil": {"ipa":"dee-FEE-seel","ex":"É difícil arranjar estacionamento aqui.","exE":"It is difficult to find parking here.","note":"Igual nos dois géneros, plural \"difíceis\". Com um nome antes, leva \"de\": um livro difícil de ler.","noteE":"The same in both genders, plural \"difíceis\". With a preceding noun it takes \"de\": um livro difícil de ler."},
  "discutir": {"ipa":"deesh-koo-TEER","ex":"Não vale a pena discutir com ele.","exE":"There's no point arguing with him.","note":"Discutir com alguém é zangar-se; discutir um assunto, sem preposição, é debatê-lo. É a preposição que decide o sentido.","noteE":"Discutir com alguém means to have a row; discutir um assunto, with no preposition, means to debate it. The preposition decides which meaning you get."},
  "disponível": {"ipa":"deesh-poo-NEE-vel","ex":"O médico só está disponível amanhã.","exE":"The doctor is only available tomorrow.","note":"Igual nos dois géneros e faz o plural \"disponíveis\". Pede \"para\" antes de um infinitivo: disponível para ajudar.","noteE":"The same in both genders and pluralises as \"disponíveis\". It takes \"para\" before an infinitive: disponível para ajudar."},
  "dispor": {"ipa":"deesh-POHR","ex":"A casa dispõe de dois quartos.","exE":"The house has two bedrooms.","note":"Composto de pôr, logo irregular: eu disponho, ele dispõe, pretérito dispus. Dispor de é ter à disposição; dispor algo é arrumá-lo.","noteE":"A compound of pôr, so irregular: eu disponho, ele dispõe, past dispus. Dispor de means to have available; dispor algo means to arrange it."},
  "divertido": {"ipa":"dee-vuhr-TEE-doo","ex":"A festa foi muito divertida.","exE":"The party was great fun.","note":"Com \"ser\" a coisa é divertida; com \"estar\" a pessoa está a divertir-se. Concorda: divertida, divertidos, divertidas.","noteE":"With \"ser\" the thing is fun; with \"estar\" the person is having fun. It agrees: divertida, divertidos, divertidas."},
  "divertir-se": {"ipa":"dee-vuhr-TEER-suh","ex":"Divertimo-nos imenso na festa.","exE":"We had a great time at the party.","note":"Pronominal com alternância vocálica: eu divirto-me, tu divertes-te, eles divertem-se. Na 1.ª pessoa do plural o -s cai antes de -nos: divertimo-nos.","noteE":"Pronominal with a stem change: eu divirto-me, tu divertes-te, eles divertem-se. In the nós form the final -s drops before -nos: divertimo-nos."},
  "dividir": {"ipa":"dee-vee-DEER","ex":"Vamos dividir a conta ao meio.","exE":"Let's split the bill in half.","note":"Dividir por na matemática (dez a dividir por dois), mas dividir com alguém quando se partilha. Dividir-se em indica as partes resultantes.","noteE":"Dividir por in maths (dez a dividir por dois), but dividir com alguém when sharing. Dividir-se em gives the resulting parts."},
  "dizer": {"ipa":"dee-ZER","ex":"Diz-me a verdade.","exE":"Tell me the truth.","note":"Irregular: 'digo, dizes, diz…'.","noteE":"Irregular: 'digo, dizes, diz…'."},
  "doente": {"ipa":"doo-EH (nasal)-tuh","ex":"A minha mãe está doente há dois dias.","exE":"My mother has been ill for two days.","note":"Anda com \"estar\" ou \"ficar\", nunca com \"ser\", pois é um estado. Forma única nos dois géneros, plural \"doentes\", e serve também de nome: o doente.","noteE":"It goes with \"estar\" or \"ficar\", never \"ser\", since it is a state. One form for both genders, plural \"doentes\", and it also works as a noun: o doente."},
  "dormir": {"ipa":"door-MEER","ex":"Ontem dormi muito mal.","exE":"I slept really badly last night.","note":"O «o» do radical muda para «u» na primeira pessoa: durmo, dormes, dorme. «Adormecer» é o momento de cair no sono.","noteE":"The stem o changes to u in the first person: durmo, dormes, dorme. Adormecer is the moment of falling asleep."},
  "durante": {"ipa":"doo-RUH (nasal)-tuh","ex":"Choveu durante toda a noite.","exE":"It rained during the whole night.","note":"Serve para \"during\" e para \"for\" com duração: estudei durante duas horas. Não se usa \"por\" nesse sentido, ao contrário do espanhol.","noteE":"It covers both 'during' and 'for' with a length of time: estudei durante duas horas ('I studied for two hours'). Don't reach for por there."},
  "duro": {"ipa":"DOO-roo","ex":"O pão de ontem está duro.","exE":"Yesterday's bread is hard.","note":"Refere-se à textura, não à dificuldade; para isso usa-se \"difícil\". Concorda: dura, duros, duras.","noteE":"It refers to texture, not difficulty; for that use \"difícil\". It agrees: dura, duros, duras."},
  "e": {"ipa":"ee","ex":"Comprei pão e leite.","exE":"I bought bread and milk.","note":"Pronuncia-se como um \"i\" fechado, não como a letra E do alfabeto. Liga elementos do mesmo tipo e não muda de forma antes de palavras começadas por i-.","noteE":"It is pronounced like a closed ee, not like the letter name. It joins like with like and never changes form before words starting with i."},
  "educado": {"ipa":"ee-doo-KAH-doo","ex":"Ele é sempre muito educado com os vizinhos.","exE":"He is always very polite with the neighbours.","note":"Significa \"bem-comportado\", não \"instruído\"; para isso diz-se \"instruído\" ou \"culto\". Concorda: educada, educados, educadas.","noteE":"It means \"well-mannered\", not \"educated\"; for that say \"instruído\" or \"culto\". It agrees: educada, educados, educadas."},
  "ela": {"ipa":"EH-lah","ex":"Ela mora perto do rio.","exE":"She lives near the river.","note":"A diferença audível para «ele» está na vogal: «ela» tem «e» aberto, «ele» tem «e» fechado.","noteE":"The audible difference from 'ele' is the vowel: 'ela' has an open e, 'ele' a closed one."},
  "elas": {"ipa":"EH-lush","ex":"Elas são irmãs.","exE":"They are sisters.","note":"Só se usa quando todas as pessoas ou coisas referidas são femininas.","noteE":"Used only when everyone or everything referred to is feminine."},
  "ele": {"ipa":"AY-luh","ex":"Ele chega às oito da manhã.","exE":"He arrives at eight in the morning.","note":"Também substitui coisas de género masculino depois de preposição: «o comboio? Vim com ele».","noteE":"It also stands for masculine things after a preposition: 'o comboio? Vim nele' (the train? I came on it)."},
  "eleger": {"ipa":"ee-luh-ZHEHR","ex":"Elegeram um novo presidente da junta.","exE":"They elected a new parish council president.","note":"O «g» passa a «j» antes de «a» e «o»: elejo, eleja. O particípio com ser ou estar é «eleito».","noteE":"The g becomes j before a and o: elejo, eleja. The participle with ser/estar is eleito."},
  "eles": {"ipa":"AY-lush","ex":"Eles trabalham ao sábado de manhã.","exE":"They work on Saturday mornings.","note":"Um grupo misto leva sempre «eles», mesmo que haja só um homem entre muitas mulheres.","noteE":"A mixed group always takes 'eles', even if there is just one man among many women."},
  "em": {"ipa":"eh (nasal)","ex":"Os teus óculos estão na cozinha.","exE":"Your glasses are in the kitchen.","note":"Cobre \"in\", \"on\" e \"at\" do inglês, mas contrai sempre com o artigo: no, na, nos, nas, num, numa.","noteE":"One preposition does the job of English in, on and at. It never stands alone before an article — it fuses into no, na, num, numa."},
  "em baixo": {"ipa":"eh (nasal) BYE-shoo","ex":"O gato está em baixo da cama.","exE":"The cat is under the bed.","note":"Em Portugal escreve-se em duas palavras (no Brasil, \"embaixo\"). Também se diz \"debaixo de\" e \"lá em baixo\" significa no andar de baixo.","noteE":"In Portugal it is written as two words, unlike the Brazilian embaixo. Debaixo de is an alternative, and lá em baixo means downstairs."},
  "em cima": {"ipa":"eh (nasal) SEE-mah","ex":"O livro está em cima da mesa.","exE":"The book is on top of the table.","note":"Indica contacto com uma superfície e liga-se com \"de\": em cima do frigorífico. \"Lá em cima\" significa no andar de cima.","noteE":"It indicates contact with a surface and links with de. Lá em cima means upstairs."},
  "embora": {"ipa":"eh (nasal)-BAW-rah","ex":"Embora esteja frio, vou correr.","exE":"Although it's cold, I'm going running.","note":"Pede SEMPRE o conjuntivo (embora seja, embora tenha) e a oração vem normalmente à frente, separada por vírgula. Atenção: \"ir embora\" significa partir.","noteE":"It ALWAYS takes the subjunctive and its clause usually comes first, set off by a comma. Note the separate expression ir embora, meaning to leave."},
  "encontrar": {"ipa":"eh (nasal)-koh (nasal)-TRAR","ex":"Não encontro o meu telemóvel.","exE":"I can't find my phone.","note":"Direto significa achar; na forma reflexiva com com significa ter um encontro: encontrei-me com a Ana. Encontrar-se também quer dizer estar situado.","noteE":"Used directly it means to find; reflexive with com it means to meet up: encontrei-me com a Ana. Encontrar-se also means to be located."},
  "enfrentar": {"ipa":"eh (nasal)-freh (nasal)-TAR","ex":"Temos de enfrentar o problema.","exE":"We have to face the problem.","note":"Leva objeto direto, sem preposição (enfrentar uma dificuldade, enfrentar o adversário). Enfrentar-se com alguém é confrontar-se abertamente.","noteE":"Takes a direct object with no preposition (enfrentar uma dificuldade, enfrentar o adversário). Enfrentar-se com alguém means to confront them openly."},
  "engraçado": {"ipa":"ee (nasal)-gruh-SAH-doo","ex":"Ele contou uma história engraçada.","exE":"He told a funny story.","note":"Significa \"que faz rir\" e também \"giro, simpático\". Vem depois do nome e concorda: engraçada, engraçados, engraçadas.","noteE":"It means \"laughter-raising\" and also \"cute, charming\". It follows the noun and agrees: engraçada, engraçados, engraçadas."},
  "entender": {"ipa":"eh (nasal)-teh (nasal)-DEHR","ex":"Não entendi o que ele disse.","exE":"I didn't understand what he said.","note":"Em Portugal usa-se muito mais «perceber» na conversa do dia a dia. «Entender-se com alguém» é dar-se bem com essa pessoa.","noteE":"In Portugal perceber is far more common in everyday speech. Entender-se com alguém means to get on with them."},
  "entrar": {"ipa":"eh (nasal)-TRAR","ex":"Entra em casa, está frio.","exE":"Come inside, it's cold.","note":"Pede em, nunca a: entrar no comboio, entrar na sala. Entrar para significa juntar-se a um grupo: entrou para a equipa.","noteE":"It takes em, never a: entrar no comboio, entrar na sala. Entrar para means to join a group: entrou para a equipa."},
  "entre": {"ipa":"EH (nasal)-truh","ex":"O banco fica entre a farmácia e o café.","exE":"The bank is between the pharmacy and the café.","note":"É idêntico à forma verbal \"entre\" (de entrar), por isso o contexto decide. Com pronomes usa-se a forma tónica: entre mim e ti.","noteE":"Identical in spelling to entre from entrar ('come in'), so context decides. With pronouns take the stressed forms: entre mim e ti, never entre eu e tu."},
  "entregar": {"ipa":"eh (nasal)-truh-GAR","ex":"Entreguei o trabalho na segunda-feira.","exE":"I handed the assignment in on Monday.","note":"Antes de «e» escreve-se «gu»: entreguei, entregue. Usa-se para encomendas, trabalhos e chaves.","noteE":"Spelling changes to gu before e: entreguei, entregue. It is used for parcels, assignments and keys."},
  "entretanto": {"ipa":"eh (nasal)-truh-TAN (nasal)-too","ex":"Eu faço o jantar; entretanto, põe a mesa.","exE":"I'll make dinner; meanwhile, set the table.","note":"Conector adverbial no início da oração, com vírgula e indicativo. Em Portugal significa \"neste intervalo\"; no Brasil usa-se muitas vezes com o sentido de \"no entanto\".","noteE":"It is an adverbial connector opening the clause, with a comma and the indicative. In Portugal it means in the meantime, unlike the Brazilian however sense."},
  "então": {"ipa":"eh (nasal)-TOW (nasal)","ex":"Então, o que é que vamos fazer?","exE":"So, what are we going to do?","note":"Muito frequente como abre-conversa em Portugal (\"Então, tudo bem?\"). Também marca consequência depois de uma condição: se chover, então ficamos.","noteE":"It is extremely common as a conversational opener in Portugal. It also marks consequence after a condition, as in se chover, então ficamos."},
  "envergonhado": {"ipa":"ee (nasal)-vuhr-goo-NYAH-doo","ex":"Ele ficou envergonhado com o elogio.","exE":"He got embarrassed by the compliment.","note":"Usa-se com \"estar\" ou \"ficar\", nunca com \"ser\". A alternativa mais comum é \"ter vergonha\", e concorda: envergonhada, envergonhados.","noteE":"Use it with \"estar\" or \"ficar\", never with \"ser\". The more common alternative is \"ter vergonha\", and it agrees: envergonhada, envergonhados."},
  "enviar": {"ipa":"eh (nasal)-vee-AR","ex":"Enviei-te uma mensagem para o telemóvel.","exE":"I sent you a message on your mobile.","note":"Enviar algo a alguém; no dia a dia mandar é bem mais frequente. Nas formas tónicas o i é acentuado na pronúncia: eu envio, tu envias.","noteE":"Enviar something a someone; in everyday speech mandar is far commoner. In the stressed forms the i carries the stress: eu envio, tu envias."},
  "envolver": {"ipa":"eh (nasal)-vol-VEHR","ex":"O projeto envolve muitas pessoas.","exE":"The project involves a lot of people.","note":"«Envolver-se em» é meter-se numa situação ou relação. Tem também o sentido físico de embrulhar.","noteE":"Envolver-se em means to get involved in a situation or relationship. It also has the physical sense of wrapping."},
  "erguer": {"ipa":"er-GEHR","ex":"Ergueu a mão para responder.","exE":"He raised his hand to answer.","note":"O u só se escreve antes de e/i: eu ergo, tu ergues, ele ergue. É mais literário do que levantar; erguer-se é pôr-se de pé.","noteE":"The u only appears before e/i: eu ergo, tu ergues, ele ergue. More literary than levantar; erguer-se means to rise to one's feet."},
  "errado": {"ipa":"ee-RRAH-doo","ex":"Desculpa, apanhei o autocarro errado.","exE":"Sorry, I took the wrong bus.","note":"Coloca-se depois do nome e concorda: errada, errados, erradas. Para dizer que alguém se enganou, diz-se \"estar enganado\" mais do que \"estar errado\".","noteE":"It goes after the noun and agrees: errada, errados, erradas. To say a person is mistaken, \"estar enganado\" is more common than \"estar errado\"."},
  "escolher": {"ipa":"ish-koo-LYEHR","ex":"Escolhe tu o restaurante.","exE":"You choose the restaurant.","note":"O grupo «lh» soa como o «lli» de million. Antes de «a» e «o» o som mantém-se: escolho, escolha.","noteE":"The lh sounds like the lli in million. The sound stays the same before a and o: escolho, escolha."},
  "escrever": {"ipa":"shkruh-VEHR","ex":"Escrevi um postal aos meus pais.","exE":"I wrote a postcard to my parents.","note":"Particípio passado irregular: escrito. O pretérito perfeito também é irregular na terceira pessoa: ele escreveu, mas eu escrevi.","noteE":"Irregular past participle: escrito. Note also that the initial es before a consonant is pronounced like sh, with no vowel at all."},
  "escuro": {"ipa":"ish-KOO-roo","ex":"Já está escuro lá fora.","exE":"It is already dark outside.","note":"Concorda: escura, escuros, escuras, e forma compostos com cores: verde-escuro. Para a noite usa-se \"está escuro\", não \"é escuro\".","noteE":"It agrees: escura, escuros, escuras, and forms compounds with colours: verde-escuro. For nightfall say \"está escuro\", not \"é escuro\"."},
  "esperar": {"ipa":"shpuh-RAR","ex":"Espero por ti à porta do cinema.","exE":"I'll wait for you outside the cinema.","note":"Com por ou direto significa aguardar; estar à espera de é ainda mais comum na fala. Com o sentido de ter esperança, esperar que pede conjuntivo: espero que venhas.","noteE":"With por or directly it means to wait; estar à espera de is even more common in speech. In the sense of to hope, esperar que takes the subjunctive: espero que venhas."},
  "esperto": {"ipa":"ish-PEHR-too","ex":"Aquele miúdo é muito esperto.","exE":"That kid is very clever.","note":"Refere-se a vivacidade prática e pode ter um tom de malandrice. Concorda: esperta, espertos, espertas.","noteE":"It refers to practical quick-wittedness and can carry a hint of craftiness. It agrees: esperta, espertos, espertas."},
  "esquecer": {"ipa":"ish-kuh-SEHR","ex":"Esqueci-me da chave outra vez.","exE":"I forgot my key again.","note":"Na fala corrente é reflexo e pede «de»: esquecer-se de algo. Sem pronome também existe: esqueci o nome dele.","noteE":"In everyday speech it is reflexive and takes de: esquecer-se de algo. The plain form also exists: esqueci o nome dele."},
  "esse / essa": {"ipa":"AY-suh / EH-sah","ex":"Esse casaco fica-te bem.","exE":"That coat suits you.","note":"Marca o que está perto da pessoa com quem se fala, no sistema de três graus este / esse / aquele. Contrai-se: desse, nessa.","noteE":"Marks what is near the person you are talking to, in the three-way system este / esse / aquele. It contracts: desse, nessa."},
  "esses / essas": {"ipa":"AY-sush / EH-sush","ex":"Esses sapatos são teus?","exE":"Are those shoes yours?","note":"Plural de esse e essa, sempre ligado ao espaço do ouvinte. Em Portugal a distinção entre esse e aquele mantém-se muito viva na fala do dia a dia.","noteE":"The plural of esse and essa, always tied to the listener's space. In Portugal the distinction between esse and aquele is still very much alive in everyday speech."},
  "estabelecer": {"ipa":"ish-tah-buh-luh-SEHR","ex":"A empresa estabeleceu novas regras.","exE":"The company set new rules.","note":"O «c» passa a «ç» antes de «a» e «o»: estabeleço, estabeleça. «Estabelecer-se» é instalar-se ou abrir negócio.","noteE":"The c becomes ç before a and o: estabeleço, estabeleça. Estabelecer-se means to settle or set up in business."},
  "estar": {"ipa":"ish-TAR","ex":"Estou cansado hoje.","exE":"I'm tired today.","note":"Estar é temporário: estados e localização. 'Estou em casa.'","noteE":"Estar is for temporary states and location: 'Estou em casa' = I'm at home."},
  "este / esta": {"ipa":"AYSHT-uh / EHSH-tah","ex":"Esta camisola é muito quente.","exE":"This jumper is very warm.","note":"Refere-se ao que está perto de quem fala. Contrai-se com de e em: deste, desta, neste, nesta.","noteE":"Refers to what is near the speaker. It contracts with de and em: deste, desta, neste, nesta."},
  "estender": {"ipa":"shteh (nasal)-DEHR","ex":"Estendi a roupa na varanda.","exE":"I hung the washing out on the balcony.","note":"Estender a roupa é pendurá-la a secar, uso diário em Portugal. O particípio é estendido; extenso é adjetivo, não particípio.","noteE":"Estender a roupa means to hang the washing out to dry, an everyday phrase in Portugal. The participle is estendido — extenso is an adjective, not a participle."},
  "estes / estas": {"ipa":"AYSH-tush / EHSH-tush","ex":"Estes livros são do meu pai.","exE":"These books are my father's.","note":"Plural de este e esta, também com contrações: destes, nestas. Repare que o e de estes é fechado e o de estas é aberto.","noteE":"The plural of este and esta, with the same contractions: destes, nestas. Note that the e in estes is closed while the one in estas is open."},
  "estreito": {"ipa":"ish-TRAY-too","ex":"As ruas da Alfama são muito estreitas.","exE":"The streets of Alfama are very narrow.","note":"É o oposto de \"largo\" e coloca-se depois do nome. Concorda: estreita, estreitos, estreitas.","noteE":"It is the opposite of \"largo\" and goes after the noun. It agrees: estreita, estreitos, estreitas."},
  "estudar": {"ipa":"ish-too-DAR","ex":"Estou a estudar para o exame de quinta.","exE":"I'm studying for Thursday's exam.","note":"Regular. Diz-se «estudar em» para a escola ou universidade e «estudar para» quando há um exame à vista.","noteE":"Regular. Use estudar em for the institution and estudar para when there is an exam coming up."},
  "estúpido": {"ipa":"ish-TOO-pee-doo","ex":"Foi uma ideia estúpida.","exE":"It was a stupid idea.","note":"Aplicado a pessoas é bastante ofensivo, mais do que em inglês; a coisas é mais leve. Concorda: estúpida, estúpidos, estúpidas.","noteE":"Applied to people it is quite offensive, more so than in English; applied to things it is milder. It agrees: estúpida, estúpidos, estúpidas."},
  "eu": {"ipa":"ay-oo","ex":"Eu não sabia disso.","exE":"I didn't know that.","note":"O sujeito costuma omitir-se, porque a terminação do verbo já o indica; «eu» aparece sobretudo para dar ênfase ou marcar contraste.","noteE":"Subject pronouns are usually dropped since the verb ending shows the person; 'eu' appears mainly for emphasis or contrast."},
  "evitar": {"ipa":"ee-vee-TAR","ex":"Evito sair à hora de ponta.","exE":"I avoid going out at rush hour.","note":"Liga-se diretamente ao infinitivo, sem preposição: evitar falar. Com frase usa-se «evitar que» mais conjuntivo.","noteE":"It links straight to an infinitive with no preposition: evitar falar. With a clause use evitar que plus the subjunctive."},
  "exceto": {"ipa":"ish-SEH-too","ex":"Trabalho todos os dias exceto ao domingo.","exE":"I work every day except on Sunday.","note":"Depois do Acordo Ortográfico escreve-se sem o \"p\" (antes \"excepto\"), mas ainda se vê a grafia antiga em livros mais velhos. Sinónimos: salvo, à exceção de.","noteE":"Since the spelling reform the silent p is gone (it used to be excepto), though older Portuguese books still show it. Synonyms: salvo, à exceção de."},
  "exercer": {"ipa":"ee-zuhr-SEHR","ex":"Ele exerce medicina há vinte anos.","exE":"He has practised medicine for twenty years.","note":"Registo formal: exercer uma profissão, um cargo, pressão, influência. Cedilha antes de a/o: eu exerço, que ele exerça.","noteE":"Formal register: exercer a profession, a post, pressure, influence. Cedilla before a/o: eu exerço, que ele exerça."},
  "exigir": {"ipa":"ee-zee-ZHEER","ex":"O trabalho exige muita paciência.","exE":"The job demands a lot of patience.","note":"O «g» passa a «j» antes de «a» e «o»: exijo, exija. Depois de «exigir que» usa-se sempre o conjuntivo.","noteE":"The g becomes j before a and o: exijo, exija. After exigir que you always use the subjunctive."},
  "existir": {"ipa":"ee-zish-TEER","ex":"Existem várias soluções para isso.","exE":"There are several solutions for that.","note":"Ao contrário de haver, concorda com o sujeito: existe um problema, existem problemas. É mais formal do que há.","noteE":"Unlike haver, it agrees with its subject: existe um problema, existem problemas. It is more formal than há."},
  "explicar": {"ipa":"eesh-plee-KAR","ex":"Podes explicar-me isto outra vez?","exE":"Can you explain this to me again?","note":"O «x» lê-se como «sh» antes de consoante. Antes de «e» escreve-se «qu»: expliquei, explique.","noteE":"The x is pronounced sh before a consonant. Spelling changes to qu before e: expliquei, explique."},
  "facilmente": {"ipa":"fah-seel-MEH (nasal)-tuh","ex":"Encontro estacionamento facilmente aqui.","exE":"I find parking easily here.","note":"Vem de \"fácil\", que perde o acento gráfico ao juntar -mente. Coloca-se normalmente depois do verbo.","noteE":"It comes from fácil, which drops its written accent once -mente is added. It normally follows the verb."},
  "falar": {"ipa":"fah-LAR","ex":"Falas inglês?","exE":"Do you speak English?","note":"Regular -ar; 'falar com' = to talk to.","noteE":"Regular -ar verb; 'falar com' = to talk to."},
  "faltar": {"ipa":"fal-TAR","ex":"Faltam dois dias para as férias.","exE":"There are two days to go until the holidays.","note":"Costuma vir com pronome indireto e concorda com a coisa em falta: falta-me tempo, faltam-me dois euros. «Faltar a» é não comparecer.","noteE":"It usually takes an indirect pronoun and agrees with the thing lacking: falta-me tempo, faltam-me dois euros. Faltar a means to miss an event."},
  "famoso": {"ipa":"fuh-MOH-zoo","ex":"Este pastel é famoso em todo o país.","exE":"This pastry is famous all over the country.","note":"Vem depois do nome e liga-se com \"por\": famoso pelos azulejos. Concorda: famosa, famosos, famosas.","noteE":"It follows the noun and links with \"por\": famoso pelos azulejos. It agrees: famosa, famosos, famosas."},
  "fazer": {"ipa":"fah-ZER","ex":"O que fazes ao fim de semana?","exE":"What do you do at the weekend?","note":"Irregular; também para o tempo: 'faz frio' = it's cold.","noteE":"Irregular; also used for weather: 'faz frio' = it's cold."},
  "fechado": {"ipa":"fuh-SHAH-doo","ex":"A loja está fechada ao domingo.","exE":"The shop is closed on Sundays.","note":"Com \"estar\" descreve o estado; com \"ser\" indica o hábito: a loja é fechada ao domingo. Concorda: fechada, fechados, fechadas.","noteE":"With \"estar\" it describes the state; with \"ser\" it states the habit: a loja é fechada ao domingo. It agrees: fechada, fechados, fechadas."},
  "fechar": {"ipa":"fuh-SHAR","ex":"Fecha a janela, está frio.","exE":"Close the window, it's cold.","note":"Contrário de «abrir». «Fechar à chave» é trancar, e as lojas «fecham» ao domingo.","noteE":"The opposite of abrir. Fechar à chave means to lock, and shops fecham (close) on Sundays."},
  "feio": {"ipa":"FAY-oo","ex":"Este prédio novo é muito feio.","exE":"This new building is very ugly.","note":"Vem depois do nome e concorda: feia, feios, feias. Com pessoas soa duro, por isso os portugueses preferem dizer \"não é muito bonito\".","noteE":"It follows the noun and agrees: feia, feios, feias. Applied to people it sounds harsh, so the Portuguese often soften it to \"não é muito bonito\"."},
  "feliz": {"ipa":"fuh-LEESH","ex":"Fico muito feliz por te ver.","exE":"I am very happy to see you.","note":"Tem a mesma forma nos dois géneros e faz o plural \"felizes\". Com \"ser\" indica feitio permanente, com \"estar\" um estado de agora.","noteE":"It has the same form for both genders and pluralises as \"felizes\". With \"ser\" it describes a lasting disposition, with \"estar\" a passing mood."},
  "felizmente": {"ipa":"fuh-leezh-MEH (nasal)-tuh","ex":"Felizmente, o comboio não se atrasou.","exE":"Fortunately, the train wasn't delayed.","note":"Funciona como comentário sobre toda a frase, normalmente no início e seguido de vírgula. Na fala é comum \"ainda bem que...\".","noteE":"It comments on the whole sentence, usually opening it and followed by a comma. In speech ainda bem que is the common alternative."},
  "ficar": {"ipa":"fee-KAR","ex":"Fico em casa esta noite.","exE":"I'm staying home tonight.","note":"Faz o trabalho de três verbos: stay, become e be located.","noteE":"Does the work of three English verbs: to stay, to become, and to be located."},
  "fixar": {"ipa":"feek-SAR","ex":"Ainda não fixámos a data.","exE":"We still haven't set the date.","note":"Fixar uma data, um preço, uma regra; fixar-se em é concentrar-se ou instalar-se num sítio. Note o acento agudo do pretérito nós fixámos, que o distingue do presente.","noteE":"Fixar a date, a price, a rule; fixar-se em means to fix on something or to settle somewhere. Note the acute accent in the past nós fixámos, which distinguishes it from the present."},
  "fora": {"ipa":"FAW-rah","ex":"Vamos jantar fora esta noite.","exE":"We're going to eat out tonight.","note":"Com complemento é \"fora de\" (fora de casa). \"Lá fora\" significa no exterior e \"estar fora\" quer dizer estar ausente ou de viagem.","noteE":"With a complement it becomes fora de, as in fora de casa. Lá fora means outside, and estar fora means to be away."},
  "formar": {"ipa":"foor-MAR","ex":"Formámos um grupo de estudo.","exE":"We formed a study group.","note":"Na forma pronominal significa concluir um curso: formei-me em Direito. Também se diz tirar um curso na conversa do dia a dia.","noteE":"In the pronominal form it means to graduate: formei-me em Direito. Everyday speech also uses tirar um curso."},
  "fornecer": {"ipa":"foor-nuh-SEHR","ex":"Esta loja fornece os restaurantes locais.","exE":"This shop supplies the local restaurants.","note":"Fornecer algo a alguém, ou fornecer alguém de algo. Cedilha antes de a/o, como conhecer: eu forneço, que ele forneça.","noteE":"Fornecer something a someone, or fornecer someone de something. Cedilla before a/o, like conhecer: eu forneço, que ele forneça."},
  "forte": {"ipa":"FAWR-tuh","ex":"O vento estava muito forte na praia.","exE":"The wind was very strong on the beach.","note":"Forma única para os dois géneros, plural \"fortes\". Serve para força física, sabores e cheiros: um café forte.","noteE":"One form for both genders, plural \"fortes\". It covers physical strength as well as tastes and smells: um café forte."},
  "fraco": {"ipa":"FRAH-koo","ex":"Sinto-me fraco depois da gripe.","exE":"I feel weak after the flu.","note":"Concorda: fraca, fracos, fracas. Também significa \"de má qualidade\": o filme foi fraco.","noteE":"It agrees: fraca, fracos, fracas. It also means \"poor quality\": o filme foi fraco."},
  "frequentemente": {"ipa":"fruh-kweh (nasal)-tuh-MEH (nasal)-tuh","ex":"Vou frequentemente ao mercado ao sábado.","exE":"I often go to the market on Saturdays.","note":"Advérbio em -mente formado sobre o feminino do adjetivo. Na fala do dia a dia é mais natural dizer \"muitas vezes\".","noteE":"It is a -mente adverb built on the feminine adjective. In everyday speech muitas vezes sounds far more natural."},
  "frio": {"ipa":"FREE-oo","ex":"A água da praia estava muito fria.","exE":"The sea water was very cold.","note":"Concorda: fria, frios, frias. A pessoa \"tem frio\" e o tempo \"está frio\"; dizer \"estou frio\" está errado.","noteE":"It agrees: fria, frios, frias. A person \"tem frio\" and the weather \"está frio\"; saying \"estou frio\" is wrong."},
  "fugir": {"ipa":"foo-ZHEER","ex":"O gato fugiu de casa ontem.","exE":"The cat ran away from home yesterday.","note":"Pede «de» com aquilo de que se foge. O «u» abre para «o» no presente: fujo, foges, foge, fugimos, fogem.","noteE":"It takes de for what you flee from. The u opens to o in the present: fujo, foges, foge, fugimos, fogem."},
  "funcionar": {"ipa":"foo (nasal)-syoo-NAR","ex":"O elevador não está a funcionar.","exE":"The lift isn't working.","note":"Usa-se para máquinas, sistemas e planos, nunca para uma pessoa no emprego — nesse caso é trabalhar. Note o progressivo estar a funcionar.","noteE":"Used for machines, systems and plans, never for a person's job — that is trabalhar. Note the European progressive estar a funcionar, never 'funcionando'."},
  "fácil": {"ipa":"FAH-seel","ex":"Este exercício é muito fácil.","exE":"This exercise is very easy.","note":"Não muda no feminino e faz o plural \"fáceis\". Segue-se-lhe infinitivo com \"de\": é fácil de perceber.","noteE":"It does not change in the feminine and pluralises as \"fáceis\". It takes an infinitive with \"de\": é fácil de perceber."},
  "ganhar": {"ipa":"gah-NYAR","ex":"A nossa equipa ganhou o jogo.","exE":"Our team won the match.","note":"Serve para vencer, receber salário e adquirir: ganhar a vida, ganhar peso. Tem particípio duplo, sendo ganho o mais usado.","noteE":"It covers winning, earning and gaining: ganhar a vida, ganhar peso. It has a double participle, with ganho the more common one."},
  "garantir": {"ipa":"gah-rah (nasal)-TEER","ex":"Garanto-te que vale a pena.","exE":"I promise you it's worth it.","note":"Regular em -ir. Depois de «garantir que» usa-se o indicativo, porque se afirma algo como certo.","noteE":"A regular -ir verb. After garantir que you use the indicative, since you are stating something as certain."},
  "gerar": {"ipa":"zhuh-RAR","ex":"Esta máquina gera muito ruído.","exE":"This machine generates a lot of noise.","note":"Sobretudo técnico ou jornalístico (gerar energia, empregos, polémica); na fala corrente usa-se criar ou causar. Gerar-se = formar-se.","noteE":"Mostly technical or journalistic (gerar energia, empregos, polémica); in everyday speech you say criar or causar. Gerar-se means to build up or form."},
  "gostar": {"ipa":"goosh-TAR","ex":"Gosto muito de bacalhau assado.","exE":"I really like roast cod.","note":"Leva sempre de, tanto antes de nome como de infinitivo: gosto de ler. Sem o de a frase fica agramatical.","noteE":"It always takes de, before both nouns and infinitives: gosto de ler. Without the de the sentence is ungrammatical."},
  "grande": {"ipa":"GRA (nasal)-duh","ex":"Uma casa grande.","exE":"A big house.","note":"Invariável no género: 'um homem grande', 'uma casa grande'.","noteE":"Same for both genders: 'um homem grande', 'uma casa grande'."},
  "gritar": {"ipa":"gree-TAR","ex":"Não grites comigo, por favor.","exE":"Don't shout at me, please.","note":"Gritar com alguém é ralhar; gritar por alguém é chamá-lo aos gritos. O imperativo negativo usa o conjuntivo: não grites.","noteE":"Gritar com alguém means to shout at someone in anger; gritar por alguém is to call out for them. The negative imperative uses the subjunctive: não grites."},
  "guardar": {"ipa":"gwar-DAR","ex":"Guarda o pão no armário.","exE":"Put the bread away in the cupboard.","note":"Em Portugal significa antes de mais arrumar, pôr no sítio, além de conservar. Expressões fixas: guardar segredo, guardar lugar.","noteE":"In Portugal it means first of all to put away or tidy something into its place, as well as to keep. Fixed phrases: guardar segredo, guardar lugar."},
  "haver": {"ipa":"ah-VEHR","ex":"Há muita gente na paragem.","exE":"There are a lot of people at the stop.","note":"Como verbo existencial fica sempre no singular, mesmo com plural: há dois comboios. Em Portugal não se usa tem com este sentido, ao contrário do Brasil.","noteE":"As an existential verb it always stays singular, even with a plural: há dois comboios. In Portugal tem is never used this way, unlike in Brazil."},
  "hoje": {"ipa":"OH-zhuh","ex":"Hoje vou almoçar fora.","exE":"Today I'm going to have lunch out.","note":"Combina-se livremente: hoje de manhã, hoje à tarde, hoje à noite. \"Hoje em dia\" significa nos dias que correm.","noteE":"It combines freely with times of day, and the fixed phrase hoje em dia means nowadays."},
  "honesto": {"ipa":"oo-NEHSH-too","ex":"Ele é um homem honesto e trabalhador.","exE":"He is an honest and hard-working man.","note":"O h não se lê. Vai com \"ser\", por ser um traço de carácter, e concorda: honesta, honestos, honestas.","noteE":"The h is silent. It goes with \"ser\", being a character trait, and it agrees: honesta, honestos, honestas."},
  "horrível": {"ipa":"oo-RREE-vel","ex":"O cheiro na cozinha estava horrível.","exE":"The smell in the kitchen was horrible.","note":"Igual nos dois géneros, plural \"horríveis\". Vem depois do nome e é forte o bastante para dispensar \"muito\".","noteE":"The same in both genders, plural \"horríveis\". It follows the noun and is strong enough not to need \"muito\"."},
  "identificar": {"ipa":"ee-deh (nasal)-tee-fee-KAR","ex":"Consegues identificar esta planta?","exE":"Can you identify this plant?","note":"Identificar algo ou alguém, com objeto direto. Identificar-se com é rever-se em algo; identificar-se, sem complemento, é mostrar o documento de identificação.","noteE":"Identificar something or someone, with a direct object. Identificar-se com means to relate to something; identificar-se on its own means to show your ID."},
  "igual": {"ipa":"ee-GWAL","ex":"O meu casaco é igual ao teu.","exE":"My coat is the same as yours.","note":"Forma única nos dois géneros e plural \"iguais\". Pede a preposição \"a\": igual ao original.","noteE":"One form for both genders and the plural \"iguais\". It takes the preposition \"a\": igual ao original."},
  "imaginar": {"ipa":"ee-mah-zhee-NAR","ex":"Imagina que ganhavas a lotaria!","exE":"Imagine you won the lottery!","note":"Não pede preposição: imaginar que + indicativo para suposições. «Nem imaginas» é uma expressão muito ouvida para introduzir novidades.","noteE":"Takes no preposition: imaginar que + indicative for suppositions. «Nem imaginas» (you have no idea) is a very common way to introduce news."},
  "impedir": {"ipa":"ee (nasal)-puh-DEER","ex":"A chuva impediu-nos de sair.","exE":"The rain stopped us going out.","note":"Impedir alguém de + infinitivo, ou impedir que + conjuntivo. Conjuga-se como pedir: eu impeço, ele impede.","noteE":"Impedir someone de + infinitive, or impedir que + subjunctive. Conjugated like pedir: eu impeço, ele impede."},
  "importante": {"ipa":"ee (nasal)-poor-TA (nasal)-tuh","ex":"Amanhã tenho uma reunião importante.","exE":"Tomorrow I have an important meeting.","note":"Forma única nos dois géneros, plural \"importantes\", e vem depois do nome. Com oração seguinte pede conjuntivo: é importante que venhas.","noteE":"One form for both genders, plural \"importantes\", and it follows the noun. With a following clause it takes the subjunctive: é importante que venhas."},
  "importar": {"ipa":"ee (nasal)-poor-TAR","ex":"Importas-te de fechar a janela?","exE":"Would you mind closing the window?","note":"Importas-te de + infinitivo é a fórmula educada para pedir um favor. Não importa significa «não faz mal»; e importar também é trazer mercadorias de fora.","noteE":"Importas-te de + infinitive is the polite way to ask a favour. Não importa means 'it doesn't matter'; importar also means to import goods."},
  "incluir": {"ipa":"ee (nasal)-kloo-EER","ex":"O preço inclui o pequeno-almoço.","exE":"The price includes breakfast.","note":"Segue o padrão dos verbos em -uir: incluo, incluis, inclui, incluímos. Repare no i com acento em incluímos e incluí.","noteE":"It follows the -uir pattern: incluo, incluis, inclui, incluímos. Note the accented i in incluímos and incluí."},
  "indicar": {"ipa":"ee (nasal)-dee-KAR","ex":"Pode indicar-me o caminho para a estação?","exE":"Could you show me the way to the station?","note":"Antes de «e» escreve-se «qu»: indiquei, indique. Serve para apontar direções e para recomendar alguém.","noteE":"Spelling changes to qu before e: indiquei, indique. It covers giving directions and recommending someone."},
  "infelizmente": {"ipa":"ee (nasal)-fuh-leezh-MEH (nasal)-tuh","ex":"Infelizmente, não posso ir à festa.","exE":"Unfortunately, I can't go to the party.","note":"É o oposto de felizmente e serve para recusar convites com delicadeza. Abre a frase, separado por vírgula.","noteE":"It is the opposite of felizmente and is the polite way to turn down an invitation. It opens the sentence, set off by a comma."},
  "informar": {"ipa":"ee (nasal)-foor-MAR","ex":"Informa-me quando chegares.","exE":"Let me know when you arrive.","note":"Informar alguém de algo, ou informar-se sobre algo. Repare no enclítico informa-me e no futuro do conjuntivo depois de quando (chegares).","noteE":"Informar someone de something, or informar-se sobre something. Note the attached pronoun informa-me and the future subjunctive after quando (chegares)."},
  "iniciar": {"ipa":"ee-nee-see-AR","ex":"A aula inicia-se às nove em ponto.","exE":"The class starts at nine sharp.","note":"É mais formal do que «começar», que domina na fala. Com sujeito não humano usa-se muitas vezes a forma reflexa «iniciar-se».","noteE":"More formal than começar, which dominates in speech. With a non-human subject the reflexive iniciar-se is often used."},
  "inseguro": {"ipa":"ee (nasal)-suh-GOO-roo","ex":"Sinto-me insegura a falar em público.","exE":"I feel insecure speaking in public.","note":"Aplica-se a lugares perigosos e a pessoas sem confiança, conforme o contexto. Concorda: insegura, inseguros, inseguras.","noteE":"It applies both to unsafe places and to people lacking confidence, depending on context. It agrees: insegura, inseguros, inseguras."},
  "integrar": {"ipa":"ee (nasal)-tuh-GRAR","ex":"Ela integra a equipa desde janeiro.","exE":"She has been part of the team since January.","note":"Uso muito português: integrar algo, sem preposição, significa fazer parte desse conjunto. Integrar-se em é adaptar-se a um grupo ou lugar.","noteE":"A very Portuguese use: integrar something, with no preposition, means to be a member of it. Integrar-se em means to fit in or settle into a group or place."},
  "inteligente": {"ipa":"ee (nasal)-tuh-lee-ZHEH (nasal)-tuh","ex":"A tua filha é muito inteligente.","exE":"Your daughter is very intelligent.","note":"Forma única nos dois géneros, plural \"inteligentes\". Vem depois do nome e usa-se com \"ser\", por ser uma qualidade estável.","noteE":"One form for both genders, plural \"inteligentes\". It follows the noun and takes \"ser\", since it is a stable quality."},
  "interessar": {"ipa":"ee (nasal)-tuh-ruh-SAR","ex":"Isso não me interessa nada.","exE":"That doesn't interest me at all.","note":"Constrói-se com pronome de complemento indireto: interessa-me, interessa-te, interessa-lhe. Interessar-se por é ter interesse em algo.","noteE":"Built with an indirect object pronoun: interessa-me, interessa-te, interessa-lhe. Interessar-se por means to take an interest in something."},
  "ir": {"ipa":"eer","ex":"Vou ao mercado.","exE":"I'm going to the market.","note":"'Ir + infinitivo' forma o futuro próximo: 'vou comer'.","noteE":"'Ir + infinitive' makes the near future: 'vou comer' = I'm going to eat."},
  "isso": {"ipa":"EE-soo","ex":"Não digas isso, por favor.","exE":"Don't say that, please.","note":"Forma neutra ligada ao ouvinte; aparece em expressões muito frequentes como isso mesmo, por isso e é isso.","noteE":"The neuter form tied to the listener; it shows up in very common expressions such as isso mesmo (that's right), por isso (that's why) and é isso (that's it)."},
  "isto": {"ipa":"EESH-too","ex":"O que é isto?","exE":"What is this?","note":"Forma neutra: nunca acompanha um substantivo nem muda de género. Usa-se para uma coisa não identificada ou para uma ideia inteira; contrai-se em disto e nisto.","noteE":"The neuter form: it never accompanies a noun and never changes gender. Use it for an unidentified object or a whole idea; it contracts to disto and nisto."},
  "jantar": {"ipa":"zhah (nasal)-TAR","ex":"Jantamos por volta das oito.","exE":"We have dinner around eight.","note":"É verbo e nome ao mesmo tempo: o jantar está pronto. As outras refeições são o pequeno-almoço, o almoço e o lanche.","noteE":"It is both verb and noun: o jantar está pronto. The other meals are o pequeno-almoço (breakfast), o almoço (lunch) and o lanche (afternoon snack)."},
  "jogar": {"ipa":"zhoo-GAR","ex":"Jogamos à bola no parque ao sábado.","exE":"We play football in the park on Saturdays.","note":"Em Portugal diz-se «jogar à bola» e «jogar às cartas», com artigo. Para instrumentos musicais usa-se «tocar», nunca «jogar».","noteE":"In Portugal you say jogar à bola and jogar às cartas, with the article. For instruments you use tocar, never jogar."},
  "jovem": {"ipa":"ZHAW-vay (nasal)","ex":"Ele é demasiado jovem para conduzir.","exE":"He is too young to drive.","note":"Tem uma só forma no singular para os dois géneros e faz o plural em \"jovens\". Na fala do dia a dia, os portugueses dizem antes \"novo\" ou \"nova\".","noteE":"It has one singular form for both genders and pluralises as \"jovens\". In everyday speech the Portuguese more often say \"novo\" or \"nova\"."},
  "julgar": {"ipa":"zhool-GAR","ex":"Julgo que ele já saiu.","exE":"I think he's already left.","note":"Além do sentido jurídico, usa-se muito para «achar» ou supor: julgo que sim. Antes de «e» escreve-se «gu»: julguei.","noteE":"Besides the legal sense, it is very common for thinking or supposing: julgo que sim. Spelling: julguei before e."},
  "juntar": {"ipa":"zhoo (nasal)-TAR","ex":"Juntámo-nos todos no café.","exE":"We all met up at the café.","note":"Juntar algo a algo; juntar-se a alguém é fazer-lhe companhia. Na 1.ª pessoa do plural com pronome, o -s cai: juntámo-nos.","noteE":"Juntar something a something; juntar-se a alguém means to join them. In the nós form with a pronoun, the final -s drops: juntámo-nos."},
  "já": {"ipa":"zhah","ex":"Já almoçaste?","exE":"Have you had lunch already?","note":"Aparece normalmente com o pretérito perfeito. \"Já não\" quer dizer que algo deixou de acontecer e \"já vou\" significa vou imediatamente.","noteE":"It usually pairs with the simple past. Já não marks something that no longer happens, while já vou means I'm coming right away."},
  "já agora": {"ipa":"zhah ah-GAW-rah","ex":"Já agora, tens o número dela?","exE":"By the way, do you have her number?","note":"Expressão muito portuguesa para acrescentar um pedido ou pergunta relacionada, sempre no início e seguida de vírgula. Os brasileiros dizem antes \"a propósito\".","noteE":"This is a very European Portuguese way to tack on a related question or request, always sentence-initial with a comma. Brazilians say a propósito instead."},
  "já que": {"ipa":"zhah kuh","ex":"Já que estás aqui, ajuda-me com isto.","exE":"Since you're here, help me with this.","note":"Apresenta uma razão já conhecida dos dois falantes, leva indicativo e abre normalmente a frase. \"Uma vez que\" é o equivalente mais formal.","noteE":"It presents a reason both speakers already know, takes the indicative and usually opens the sentence. Uma vez que is the more formal equivalent."},
  "lançar": {"ipa":"lah (nasal)-SAR","ex":"A banda lançou um disco novo.","exE":"The band released a new album.","note":"O «ç» passa a «c» antes de «e»: lancei, lance. Vale para atirar objetos e para lançar produtos, livros ou campanhas.","noteE":"The ç becomes c before e: lancei, lance. It covers throwing things and launching products, books or campaigns."},
  "largo": {"ipa":"LAR-goo","ex":"Esta rua é larga e tem árvores.","exE":"This street is wide and has trees.","note":"Aplicado a roupa quer dizer \"folgado\", não \"comprido\": estas calças estão largas. Concorda: larga, largos, largas.","noteE":"Applied to clothes it means \"loose\", not \"long\": estas calças estão largas. It agrees: larga, largos, largas."},
  "lembrar-se": {"ipa":"leh (nasal)-BRAR-suh","ex":"Não me lembro do nome dela.","exE":"I can't remember her name.","note":"Na forma pronominal pede de: lembro-me de ti. Sem pronome significa fazer lembrar a outra pessoa: lembra-me de comprar pão.","noteE":"In the pronominal form it takes de: lembro-me de ti. Without the pronoun it means to remind someone else: lembra-me de comprar pão."},
  "lento": {"ipa":"LEH (nasal)-too","ex":"A internet aqui é muito lenta.","exE":"The internet here is very slow.","note":"Como advérbio diz-se \"lentamente\" ou \"devagar\", não \"lento\". Concorda: lenta, lentos, lentas.","noteE":"As an adverb say \"lentamente\" or \"devagar\", not \"lento\". It agrees: lenta, lentos, lentas."},
  "ler": {"ipa":"layr","ex":"Leio o jornal ao pequeno-almoço.","exE":"I read the paper at breakfast.","note":"Irregular: leio, lês, lê, lemos, leem, e no passado li, leste, leu. Não confundir a forma lê com o pronome lhe.","noteE":"Irregular: leio, lês, lê, lemos, leem, and in the past li, leste, leu. Don't confuse the form lê with the pronoun lhe."},
  "levantar": {"ipa":"luh-vah (nasal)-TAR","ex":"Ela levantou a mão para falar.","exE":"She raised her hand to speak.","note":"Na forma reflexa, «levantar-se» significa sair da cama ou pôr-se de pé: levanto-me às sete. Também se usa para levantar dinheiro.","noteE":"Reflexive levantar-se means to get up or stand up (levanto-me às sete). It also means to withdraw cash."},
  "levar": {"ipa":"luh-VAR","ex":"Levo o guarda-chuva por causa da chuva.","exE":"I'll take the umbrella because of the rain.","note":"Opõe-se a trazer: leva-se para longe de quem fala, traz-se para junto de quem fala. Também significa demorar: leva duas horas.","noteE":"It contrasts with trazer: you levar things away from the speaker and trazer them towards the speaker. It also means to take time: leva duas horas."},
  "leve": {"ipa":"LEH-vuh","ex":"A mala está leve, posso levá-la.","exE":"The suitcase is light, I can carry it.","note":"Forma única nos dois géneros, plural \"leves\", e refere-se ao peso. Para a luz usa-se \"claro\", nunca \"leve\".","noteE":"One form for both genders, plural \"leves\", and it refers to weight. For light as brightness use \"claro\", never \"leve\"."},
  "lhe": {"ipa":"lyuh","ex":"Dei-lhe as chaves ontem.","exE":"I gave him the keys yesterday.","note":"«Lhe» é objeto indireto e não distingue género; para desfazer a ambiguidade acrescenta-se «a ele» ou «a ela».","noteE":"'Lhe' is the indirect object and does not mark gender; add 'a ele' or 'a ela' to disambiguate."},
  "lhes": {"ipa":"lyush","ex":"Contei-lhes tudo o que aconteceu.","exE":"I told them everything that happened.","note":"Plural de «lhe»; nunca se usa como objeto direto: «vi-os», não «vi-lhes».","noteE":"Plural of 'lhe' and never a direct object: say 'vi-os' (I saw them), not 'vi-lhes'."},
  "ligar": {"ipa":"lee-GAR","ex":"Liga-me quando chegares a casa.","exE":"Call me when you get home.","note":"Três usos: ligar A alguém (telefonar), ligar o telemóvel (acender) e ligar uma coisa a outra. Não ligar a algo é não lhe dar importância.","noteE":"Three uses: ligar A someone (phone them), ligar o telemóvel (switch on), and ligar one thing to another. Não ligar a algo means to pay it no attention."},
  "limpo": {"ipa":"LEE (nasal)-poo","ex":"A casa de banho já está limpa.","exE":"The bathroom is already clean.","note":"Usa-se com \"estar\" para o resultado da limpeza. Concorda: limpa, limpos, limpas.","noteE":"Use it with \"estar\" for the result of cleaning. It agrees: limpa, limpos, limpas."},
  "logo": {"ipa":"LAW-goo","ex":"Até logo, vemo-nos à noite.","exE":"See you later, we'll see each other tonight.","note":"Refere-se a mais tarde no mesmo dia (até logo). \"Logo que\" pede o futuro do conjuntivo (logo que possas) e, em registo formal, \"logo\" liga uma conclusão.","noteE":"It points to later the same day, as in até logo. The connective logo que takes the future subjunctive, and in formal writing logo can mean therefore."},
  "longe": {"ipa":"LOH (nasal)-zhuh","ex":"O aeroporto fica longe daqui?","exE":"Is the airport far from here?","note":"Invariável e normalmente com \"de\": longe da praia. Costuma aparecer depois do verbo, sobretudo com \"ficar\" e \"morar\".","noteE":"Invariable and normally used with \"de\": longe da praia. It typically appears after the verb, especially with \"ficar\" and \"morar\"."},
  "mais": {"ipa":"mysh","ex":"Queres mais um café?","exE":"Do you want another coffee?","note":"Forma o comparativo com \"do que\" (mais alto do que eu) e o superlativo com artigo (o mais rápido). Para \"not any more\" prefere-se \"já não\".","noteE":"It builds comparatives with do que and superlatives with an article. For not any more, European Portuguese prefers já não."},
  "mal": {"ipa":"mahl","ex":"Dormi mal esta noite.","exE":"I slept badly last night.","note":"Advérbio (dormi mal), enquanto \"mau\" é o adjetivo. Como conjunção significa \"assim que\" e pede o futuro do conjuntivo: mal chegares, avisa.","noteE":"It is the adverb, whereas mau is the adjective. As a conjunction it means as soon as and takes the future subjunctive."},
  "mal-educado / malcriado": {"ipa":"mal-ee-doo-KAH-doo / mal-kree-AH-doo","ex":"Não sejas mal-educado com a tua avó.","exE":"Don't be rude to your grandmother.","note":"\"Malcriado\" ouve-se mais com crianças; \"mal-educado\" serve para qualquer idade. Ambos concordam: mal-educada, malcriados.","noteE":"\"Malcriado\" is heard more about children; \"mal-educado\" works for any age. Both agree: mal-educada, malcriados."},
  "mandar": {"ipa":"mah (nasal)-DAR","ex":"Mandei-lhe uma mensagem ontem à noite.","exE":"I sent him a message last night.","note":"Serve para enviar e para dar ordens: mandar alguém fazer algo. «Quem manda aqui?» significa quem é que decide.","noteE":"It covers both sending and giving orders (mandar alguém fazer algo). Quem manda aqui? means who's in charge here?"},
  "manter": {"ipa":"mah (nasal)-TEHR","ex":"Mantém a porta fechada, por favor.","exE":"Keep the door closed, please.","note":"Conjuga-se exatamente como ter: mantenho, mantém, mantivemos. Manter-se significa continuar num estado: mantém-se calmo.","noteE":"It conjugates exactly like ter: mantenho, mantém, mantivemos. Manter-se means to stay in a state: mantém-se calmo."},
  "maravilhoso": {"ipa":"muh-ruh-vee-LYOH-zoo","ex":"A vista daqui é maravilhosa.","exE":"The view from here is wonderful.","note":"Vem depois do nome e concorda: maravilhosa, maravilhosos, maravilhosas. É bastante enfático, por isso dispensa \"muito\".","noteE":"It follows the noun and agrees: maravilhosa, maravilhosos, maravilhosas. It is already emphatic, so it needs no \"muito\"."},
  "marcar": {"ipa":"mar-KAR","ex":"Marquei consulta no dentista para sexta.","exE":"I booked a dentist's appointment for Friday.","note":"Antes de «e» escreve-se «qu»: marquei, marque. Em Portugal marca-se uma consulta, uma mesa e também um golo.","noteE":"Spelling changes to qu before e: marquei, marque. In Portugal you marcar an appointment, a table, and also a goal."},
  "mas": {"ipa":"mush","ex":"Queria ir, mas estou cansado.","exE":"I wanted to go, but I'm tired.","note":"Liga duas orações e fica sempre no início da segunda, com vírgula antes. Leva indicativo; \"no entanto\" e \"contudo\" são equivalentes mais formais.","noteE":"It joins two clauses and always opens the second one, with a comma before it. It takes the indicative, with no entanto and contudo as formal equivalents."},
  "matar": {"ipa":"mah-TAR","ex":"Este calor mata-me.","exE":"This heat is killing me.","note":"Particípio irregular com ser ou estar: «morto». Também se usa em «matar a sede», «matar a fome» e «matar saudades».","noteE":"Irregular participle with ser/estar: morto. It also appears in matar a sede/fome (quench thirst, satisfy hunger) and matar saudades."},
  "mau": {"ipa":"mow","ex":"Faz mau tempo.","exE":"The weather's bad.","note":"Masculino; feminino 'má'. Não confundir com 'mal' (advérbio, = badly).","noteE":"Masculine; feminine 'má'. Don't confuse with 'mal' (adverb, = badly)."},
  "me": {"ipa":"muh","ex":"Ele deu-me um livro.","exE":"He gave me a book.","note":"Em Portugal o clítico vem depois do verbo, com hífen, na frase afirmativa simples; passa para antes com negação, pergunta ou palavras como «já», «que», «não»: «não me deu nada».","noteE":"In Portugal the clitic follows the verb with a hyphen in simple affirmative sentences, but moves before it after negatives, questions or words like 'já' and 'que': 'não me deu nada'."},
  "melhor": {"ipa":"muh-LYOR","ex":"Este pão é melhor do que o outro.","exE":"This bread is better than the other one.","note":"Comparativo irregular de bom e de bem — nunca \"mais bom\". É adjetivo (\"é melhor\") e advérbio (\"canta melhor\"). Uma só forma para os dois géneros; só o plural muda: melhores. Compara-se com \"do que\": melhor do que.","noteE":"Irregular comparative of both bom and bem — never \"mais bom\". It works as an adjective (\"é melhor\") and as an adverb (\"canta melhor\"). One form for both genders; only the plural changes: melhores. Compare with \"do que\", not \"que\"."},
  "menos": {"ipa":"MAY-noosh","ex":"Hoje há menos gente na praia.","exE":"Today there are fewer people at the beach.","note":"Comparativo com \"do que\" (menos caro do que...). \"Pelo menos\" significa no mínimo e \"a menos que\" pede o conjuntivo.","noteE":"It forms comparatives with do que. Pelo menos means at least, and the conjunction a menos que takes the subjunctive."},
  "mesmo": {"ipa":"MAYZH-moo","ex":"Isto é mesmo bom!","exE":"This is really good!","note":"Como advérbio é invariável (mesmo assim, mesmo que + conjuntivo); como adjetivo concorda: a mesma coisa, os mesmos erros.","noteE":"As an adverb it never changes, as in mesmo assim and mesmo que plus subjunctive. As an adjective it agrees, giving a mesma coisa."},
  "meter": {"ipa":"muh-TEHR","ex":"Mete a chave no bolso.","exE":"Put the key in your pocket.","note":"Muito coloquial em Portugal e implica pôr dentro de algo; para pousar em cima usa-se pôr. Meter-se com alguém é provocar essa pessoa.","noteE":"Very colloquial in Portugal and implies putting something inside something; for placing on top use pôr. Meter-se com alguém means to provoke or pick on them."},
  "meu / minha": {"ipa":"MAY-oo / MEE-nyah","ex":"O meu telemóvel está sem bateria.","exE":"My mobile phone has no battery.","note":"Em Portugal mantém-se o artigo antes do possessivo: «o meu carro». O possessivo concorda com a coisa possuída, não com o dono.","noteE":"European Portuguese keeps the article before the possessive: 'o meu carro'. It agrees with the thing owned, not the owner."},
  "mim": {"ipa":"mee (nasal)","ex":"Isto é para mim?","exE":"Is this for me?","note":"Depois de preposição usa-se «mim», não «eu». Com «com» há contração: «comigo».","noteE":"After a preposition use 'mim', not 'eu'. With 'com' it contracts to 'comigo'."},
  "mole": {"ipa":"MAW-luh","ex":"Este queijo é mole e cremoso.","exE":"This cheese is soft and creamy.","note":"Tem forma única nos dois géneros, plural \"moles\". Para tecidos e pele diz-se antes \"macio\"; \"mole\" sugere falta de firmeza.","noteE":"It has one form for both genders, plural \"moles\". For fabrics and skin say \"macio\"; \"mole\" suggests a lack of firmness."},
  "molhado": {"ipa":"moo-LYAH-doo","ex":"Cuidado, o chão está molhado.","exE":"Careful, the floor is wet.","note":"Anda quase sempre com \"estar\", porque é um estado passageiro. Concorda: molhada, molhados, molhadas.","noteE":"It almost always goes with \"estar\", because it is a temporary state. It agrees: molhada, molhados, molhadas."},
  "morar": {"ipa":"moo-RAR","ex":"Moro em Lisboa há dez anos.","exE":"I've lived in Lisbon for ten years.","note":"Morar em + lugar, sempre com a ideia de residência; viver é mais geral e abrange o modo de vida. Note o presente com há a traduzir o present perfect inglês.","noteE":"Morar em + place, always about where you reside; viver is broader and covers how you live. Note the present tense with há where English uses the present perfect."},
  "morrer": {"ipa":"moo-RREHR","ex":"Estou a morrer de fome!","exE":"I'm starving!","note":"Com de exprime exagero comum: morrer de fome, de frio, de rir. O particípio passado é irregular: morto.","noteE":"With de it forms common exaggerations: morrer de fome, de frio, de rir. The past participle is irregular: morto."},
  "mostrar": {"ipa":"moosh-TRAR","ex":"Mostra-me as fotografias da viagem.","exE":"Show me the photos from the trip.","note":"Mostra-se algo a alguém, e o pronome vem depois do verbo no imperativo afirmativo: mostra-me. Mostrar-se significa revelar-se de certa maneira.","noteE":"You mostrar something a someone, and the pronoun follows the verb in affirmative commands: mostra-me. Mostrar-se means to show oneself to be a certain way."},
  "mudar": {"ipa":"moo-DAR","ex":"Mudei de ideias à última hora.","exE":"I changed my mind at the last minute.","note":"Quando se troca uma coisa por outra pede «de»: mudar de casa, de emprego, de roupa. Sem preposição significa alterar algo.","noteE":"When swapping one thing for another it takes de: mudar de casa, de emprego. Without a preposition it means to alter something."},
  "mudar-se": {"ipa":"moo-DAR-suh","ex":"Vamos mudar-nos para o Porto em setembro.","exE":"We're moving to Porto in September.","note":"É a forma reflexa usada só para mudar de residência, e pede «para» com o destino. O pronome vem depois do verbo em frases afirmativas.","noteE":"This reflexive form is only for moving house, and it takes para with the destination. The pronoun follows the verb in affirmative sentences."},
  "muito": {"ipa":"MWEE (nasal)-too","ex":"Está muito frio hoje.","exE":"It's very cold today.","note":"Como advérbio é invariável antes de adjetivos e advérbios (muito caro, muito bem). Como determinante concorda: muitos livros, muitas pessoas.","noteE":"As an adverb before adjectives and adverbs it never changes. As a determiner it agrees, giving muitos livros and muitas pessoas."},
  "nada": {"ipa":"NAH-dah","ex":"Não comi nada ao pequeno-almoço.","exE":"I didn't eat anything for breakfast.","note":"A dupla negação é obrigatória quando nada vem depois do verbo. Aparece na resposta mais comum a obrigado: de nada.","noteE":"The double negative is compulsory when nada follows the verb. It appears in the standard reply to thank you: de nada, you're welcome."},
  "nascer": {"ipa":"nash-SEHR","ex":"Nasci em Coimbra em maio.","exE":"I was born in Coimbra in May.","note":"Em português é um verbo simples, sem voz passiva: nasci, não fui nascido. Primeira pessoa do presente com ç: eu nasço.","noteE":"In Portuguese it is a plain active verb, with no passive: nasci, never fui nascido. The first person present takes ç: eu nasço."},
  "nem": {"ipa":"neh (nasal)","ex":"Não gosto de chá nem de café.","exE":"I don't like tea or coffee.","note":"Equivale a \"e não\" e mantém o \"não\" antes do verbo. \"Nem sequer\" significa nem mesmo e \"nem... nem...\" liga dois elementos negados.","noteE":"It means and not, and the não before the verb stays. Nem sequer means not even, and nem... nem... links two negated items."},
  "nenhum / nenhuma": {"ipa":"nuh-NYOO (nasal) / nuh-NYOO-mah","ex":"Não tenho nenhuma dúvida.","exE":"I have no doubt at all.","note":"Depois do verbo exige o não antes dele: não vi nenhum. Se vier antes do verbo, o não desaparece: nenhum aluno faltou.","noteE":"After the verb it requires não in front of it: não vi nenhum. If it comes before the verb, the não drops: nenhum aluno faltou."},
  "nervoso": {"ipa":"nuhr-VOH-zoo","ex":"Fico nervoso antes dos exames.","exE":"I get nervous before exams.","note":"Com \"estar\" quer dizer ansioso agora; com \"ser\" indica alguém irritadiço por natureza. Concorda: nervosa, nervosos, nervosas.","noteE":"With \"estar\" it means anxious right now; with \"ser\" it describes someone edgy by nature. It agrees: nervosa, nervosos, nervosas."},
  "ninguém": {"ipa":"nee (nasal)-GEH (nasal)","ex":"Não está ninguém em casa.","exE":"There is nobody home.","note":"Como nenhum, exige o não quando vem depois do verbo: não vi ninguém. Antes do verbo dispensa-o: ninguém veio.","noteE":"Like nenhum, it requires não when it follows the verb: não vi ninguém. Before the verb the não is dropped: ninguém veio."},
  "no entanto": {"ipa":"noo eh (nasal)-TAN (nasal)-too","ex":"Estava a chover; no entanto, saímos à mesma.","exE":"It was raining; however, we went out anyway.","note":"Conector de frase, normalmente no início da segunda oração e entre vírgulas, com indicativo. É mais formal do que \"mas\" e pode trocar-se por \"contudo\" ou \"todavia\".","noteE":"It is a sentence connector, usually opening the second clause between commas, with the indicative. It is more formal than mas."},
  "nos": {"ipa":"noosh","ex":"Ele viu-nos na rua.","exE":"He saw us in the street.","note":"Quando o verbo termina em -mos, o -s cai antes de «nos»: «vemo-nos amanhã». Não confundir com «nós», que é tónico e tem «ó» aberto.","noteE":"When the verb ends in -mos, that s drops before 'nos': 'vemo-nos amanhã'. Don't confuse it with stressed 'nós'."},
  "nosso / nossa": {"ipa":"NAW-soo / NAW-sah","ex":"A nossa casa fica perto do rio.","exE":"Our house is near the river.","note":"Concorda em género e número com a coisa possuída: o nosso carro, as nossas malas. O o é aberto, como em nós.","noteE":"It agrees in gender and number with the thing owned: o nosso carro, as nossas malas. The o is open, as in nós."},
  "notar": {"ipa":"noo-TAR","ex":"Notaste alguma diferença?","exE":"Did you notice any difference?","note":"Notar que + indicativo; nota-se que é impessoal e traduz «you can tell that». Não confundir com anotar, que é tomar nota por escrito.","noteE":"Notar que + indicative; the impersonal nota-se que translates 'you can tell that'. Don't confuse it with anotar, to write something down."},
  "novo": {"ipa":"NOH-voo","ex":"Comprei uns sapatos novos ontem.","exE":"I bought some new shoes yesterday.","note":"Depois do nome significa \"acabado de comprar\"; antes do nome significa \"outro, mais um\" (um novo problema). Aplicado a pessoas, quer dizer \"jovem\": ela é muito nova.","noteE":"After the noun it means \"brand new\"; before the noun it means \"another, one more\" (um novo problema). Applied to people it means \"young\": ela é muito nova."},
  "nunca": {"ipa":"NOON (nasal)-kah","ex":"Nunca fui ao Porto de comboio.","exE":"I have never been to Porto by train.","note":"Antes do verbo dispensa o \"não\"; depois do verbo exige-o (não vou nunca). A dupla negação é obrigatória e normal.","noteE":"Placed before the verb it needs no não, but after the verb the não is compulsory. Double negatives are standard here, not an error."},
  "não": {"ipa":"nown (nasal)","ex":"Não, não quero mais, obrigado.","exE":"No, I don't want any more, thank you.","note":"Coloca-se imediatamente antes do verbo e atrai os pronomes para essa posição: \"chama-se\" torna-se \"não se chama\". Convive com outras negativas (não vejo ninguém).","noteE":"It sits directly before the verb and pulls clitic pronouns in front of it, so chama-se becomes não se chama. It coexists with other negative words."},
  "não percebi": {"ipa":"now (nasal) per-suh-BEE","ex":"Desculpe, não percebi. Pode repetir?","exE":"Sorry, I didn't understand. Can you repeat?","note":"Em Portugal 'perceber' é 'entender'; 'não entendi' também serve.","noteE":"In Portugal 'perceber' means to understand; 'não entendi' works too."},
  "não só… mas também…": {"ipa":"nown (nasal) saw ... mush tah (nasal)-BEH (nasal)","ex":"Ele não só cozinha, mas também limpa a casa.","exE":"He not only cooks, but also cleans the house.","note":"Par correlativo: os dois elementos ligados devem ser do mesmo tipo (dois verbos, dois nomes). Ambas as orações levam indicativo e pode dizer-se \"como também\".","noteE":"It is a correlative pair, so the two linked elements must be parallel. Both clauses take the indicative, and como também is an alternative second half."},
  "não… nem…": {"ipa":"nown (nasal) ... neh (nasal)","ex":"Não bebo café nem chá.","exE":"I drink neither coffee nor tea.","note":"Em português mantém-se o \"não\" antes do verbo, ao contrário do inglês. Se a frase começa pela negação dupla, dispensa-se o \"não\": Nem come nem bebe.","noteE":"Portuguese keeps the não before the verb, unlike English. If the sentence opens with the doubled nem... nem..., the não is dropped."},
  "nós": {"ipa":"nawsh","ex":"Nós vamos de comboio até ao Porto.","exE":"We're going to Porto by train.","note":"Na fala é muito comum «a gente» com o verbo na 3.ª pessoa: «a gente vai». O «ó» é aberto, ao contrário do clítico «nos».","noteE":"In speech 'a gente' + third-person verb is very common ('a gente vai'). Note the open o, unlike the clitic 'nos'."},
  "o": {"ipa":"oo","ex":"O comboio para Lisboa já partiu.","exE":"The train to Lisbon has already left.","note":"Usa-se o artigo com nomes próprios de pessoas (o João, a Maria) e com possessivos (o meu carro), ao contrário do inglês.","noteE":"Portuguese uses the article where English drops it: with first names (o João) and before possessives (o meu carro, literally 'the my car')."},
  "o / a": {"ipa":"oo / ah","ex":"O bilhete? Já o comprei.","exE":"The ticket? I've already bought it.","note":"Depois de verbo terminado em -r, -s ou -z, estas formas passam a -lo/-la e a consoante cai: «comprá-lo», «fá-lo».","noteE":"After a verb ending in -r, -s or -z, these become -lo/-la and the consonant drops: 'comprá-lo', 'fá-lo'."},
  "o acordo": {"ipa":"ah-KOHR-doo","ex":"Chegámos a acordo sobre o preço da casa.","exE":"We reached an agreement about the price of the house.","note":"Aprende as duas expressões fixas: \"de acordo com\" (according to) e \"estar de acordo\" (to agree). Repara que se diz \"chegar a acordo\", sem artigo.","noteE":"Learn the two set phrases: \"de acordo com\" (according to) and \"estar de acordo\" (to agree). Note it is \"chegar a acordo\", with no article."},
  "o ambiente": {"ipa":"oo a (nasal)-bee-E (nasal)-tuh","ex":"O ambiente do restaurante era acolhedor.","exE":"The restaurant's atmosphere was welcoming.","note":"Para ecologia diz-se \"o meio ambiente\"; sozinho, ambiente refere-se muitas vezes à atmosfera ou ao clima de um lugar.","noteE":"For ecology Portuguese says o meio ambiente; on its own, ambiente often means the atmosphere or vibe of a place."},
  "o amigo / a amiga": {"ipa":"ah-MEE-goo / ah-MEE-gah","ex":"Vou jantar com uma amiga do trabalho.","exE":"I'm having dinner with a friend from work.","note":"«Amigo» é mais forte do que o inglês «friend»; para alguém que se conhece pouco diz-se «conhecido».","noteE":"'Amigo' implies a real friendship — for a mere acquaintance Portuguese says 'um conhecido'."},
  "o amor": {"ipa":"ah-MOHR","ex":"Ele fala do trabalho com muito amor.","exE":"He talks about his work with great love.","note":"«Meu amor» é tratamento carinhoso entre casais e para com crianças. Atenção a «amor-próprio», que é a autoestima e não o amor por si mesmo no sentido negativo.","noteE":"\"Meu amor\" is an endearment for partners and children. \"Amor-próprio\" means self-esteem, not narcissism."},
  "o animal": {"ipa":"ah-nee-MAL","ex":"Não podes levar animais para o comboio.","exE":"You can't take animals on the train.","note":"O plural faz-se em -ais: \"animais\", como \"jornais\" e \"hospitais\". Para pets diz-se \"animais de estimação\".","noteE":"The plural ends in -ais: \"animais\", like \"jornais\" and \"hospitais\". Pets are \"animais de estimação\"."},
  "o ano": {"ipa":"oo AH-noo","ex":"Tenho trinta anos.","exE":"I'm thirty years old.","note":"A idade diz-se com 'ter': 'ter … anos', não 'ser'.","noteE":"Age uses 'ter' (to have): 'ter … anos', not 'to be'."},
  "o apoio": {"ipa":"ah-POY-oo","ex":"Contamos com o teu apoio nesta fase.","exE":"We're counting on your support at this stage.","note":"Diz-se «dar apoio a alguém» e «apoio ao cliente». Cuidado com a acentuação: o substantivo é «apoio», mas o verbo na primeira pessoa é «apoio» com o mesmo som.","noteE":"The phrases are \"dar apoio a alguém\" and \"apoio ao cliente\". Note the noun and the first-person verb form of \"apoiar\" are identical."},
  "o ar": {"ipa":"ar","ex":"Vamos comer ao ar livre, está bom tempo.","exE":"Let's eat outdoors, the weather's nice.","note":"\"Ao ar livre\" é a expressão fixa para outdoors. \"Ter ar de\" significa parecer: \"tens ar de cansado\".","noteE":"\"Ao ar livre\" is the set phrase for outdoors. \"Ter ar de\" means to look like: \"tens ar de cansado\" (you look tired)."},
  "o armário": {"ipa":"ar-MAH-ree-oo","ex":"Guarda a louça no armário da cozinha.","exE":"Put the dishes away in the kitchen cupboard.","note":"Serve para o armário da cozinha e para o guarda-roupa; para roupa também se diz «o roupeiro». «Sair do armário» tem o mesmo sentido do inglês.","noteE":"It covers kitchen cupboards and wardrobes; for clothes you can also say \"o roupeiro\". \"Sair do armário\" means to come out, as in English."},
  "o artigo": {"ipa":"oo ar-TEE-goo","ex":"Li um artigo interessante no jornal.","exE":"I read an interesting article in the paper.","note":"Além do artigo de jornal e do artigo gramatical, significa produto à venda: \"artigos de higiene\", \"artigos desportivos\".","noteE":"Beyond a newspaper article and a grammatical article, it means a product for sale: artigos de higiene, artigos desportivos."},
  "o aspeto": {"ipa":"oo ash-PEH-too","ex":"Este bolo tem muito bom aspeto.","exE":"This cake looks really good.","note":"Depois do acordo ortográfico perdeu o c (era aspecto), mas o e mantém-se aberto. \"Ter bom aspeto\" diz-se de comida ou de pessoas com boa aparência.","noteE":"The spelling reform dropped the c (formerly aspecto), though the e stays open. Ter bom aspeto is said of food or people that look good."},
  "o assunto": {"ipa":"ah-SOON (nasal)-too","ex":"Vamos mudar de assunto, se não te importas.","exE":"Let's change the subject, if you don't mind.","note":"É o tema de uma conversa ou o campo «Assunto» de um email. A disciplina escolar não é «assunto», mas «a disciplina» ou «a cadeira».","noteE":"It is a topic of conversation or the \"Subject\" line of an email. A school subject is \"a disciplina\" or \"a cadeira\", not \"assunto\"."},
  "o aumento": {"ipa":"oo ow-ME (nasal)-too","ex":"Ele pediu um aumento ao chefe.","exE":"He asked his boss for a raise.","note":"Serve tanto para uma subida de preços como para o aumento de salário. O verbo é aumentar; o contrário é redução ou descida.","noteE":"It covers both a rise in prices and a pay rise. The verb is aumentar and the opposite is redução or descida."},
  "o autor / a autora": {"ipa":"ow-TOHR / ow-TOH-rah","ex":"A autora vai apresentar o livro na livraria.","exE":"The author is presenting the book at the bookshop.","note":"Tem forma feminina própria, «a autora» — não é invariável como «líder». «Da autoria de» é a fórmula usada em créditos e notícias.","noteE":"Unlike \"líder\", this word has a real feminine form, \"a autora\". \"Da autoria de\" is the set phrase used in credits and news reports."},
  "o avô": {"ipa":"oo ah-VOH","ex":"O meu avô ainda conduz o carro.","exE":"My grandfather still drives the car.","note":"O circunflexo fecha a vogal e distingue-o de \"a avó\" (com ó aberto). No plural, \"os avós\" designa avô e avó juntos.","noteE":"The circumflex closes the vowel and is the only thing separating him from avó, grandmother. The plural os avós means 'the grandparents' as a pair."},
  "o banco": {"ipa":"BAH (nasal)-koo","ex":"Sentámo-nos num banco do jardim.","exE":"We sat down on a bench in the park.","note":"A mesma palavra serve para banco de dinheiro, banco de jardim e banquinho de cozinha; só o contexto decide. Em hospital, \"o banco\" é a urgência.","noteE":"The same word covers a bank, a park bench and a kitchen stool; only context decides. In a hospital, \"o banco\" is A&E."},
  "o braço": {"ipa":"oo BRAH-soo","ex":"Parti o braço a jogar futebol.","exE":"I broke my arm playing football.","note":"\"Partir\" é o verbo normal para fraturar em Portugal, onde o Brasil usaria \"quebrar\". \"De braço dado\" significa de braço no braço de outra pessoa.","noteE":"In Portugal you partir a bone; Brazilians say quebrar. De braço dado means 'arm in arm'."},
  "o cabelo": {"ipa":"oo kah-BAY-loo","ex":"Vou cortar o cabelo amanhã.","exE":"I'm getting my hair cut tomorrow.","note":"Usa-se no singular para toda a cabeleira: \"tenho o cabelo curto\". O plural \"os cabelos\" refere-se a fios individuais e soa poético.","noteE":"Stays singular for a whole head of hair: tenho o cabelo curto. The plural cabelos means individual strands and sounds literary."},
  "o caminho": {"ipa":"kah-MEE-nyoo","ex":"Vamos a caminho de casa dos meus pais.","exE":"We're on the way to my parents' house.","note":"«A caminho de» significa a dirigir-se para; «no caminho» significa ao longo do percurso. Não confundir com «estrada», que é a via asfaltada.","noteE":"\"A caminho de\" = heading towards; \"no caminho\" = along the way. \"Estrada\" is the paved road itself."},
  "o campo": {"ipa":"KAH (nasal)-poo","ex":"Passámos o fim de semana no campo.","exE":"We spent the weekend in the countryside.","note":"\"No campo\" opõe-se a \"na cidade\" e significa o campo rural. Também é o campo de futebol e a área de estudo: \"o campo da medicina\".","noteE":"\"No campo\" is the opposite of \"na cidade\" and means the countryside. It is also a football pitch and a field of study: \"o campo da medicina\"."},
  "o candidato / a candidata": {"ipa":"oo ka (nasal)-dee-DAH-too / ah ka (nasal)-dee-DAH-tah","ex":"A candidata respondeu bem a todas as perguntas.","exE":"The candidate answered all the questions well.","note":"O verbo é reflexo e pede a preposição a: \"candidatar-se a um emprego\". Não se usa \"aplicar\" nesse sentido, que é um anglicismo.","noteE":"The verb is reflexive and takes a: candidatar-se a um emprego. Do not use aplicar for to apply for a job; that is an English borrowing."},
  "o cargo": {"ipa":"oo KAR-goo","ex":"Ela ocupa um cargo importante na empresa.","exE":"She holds an important position in the company.","note":"Falso amigo: cargo é um posto ou função, não mercadoria, que se diz \"carga\". \"Estar a cargo de\" significa ser da responsabilidade de.","noteE":"False friend: cargo is a post or role, not freight, which is carga. Estar a cargo de means to be the responsibility of."},
  "o carro": {"ipa":"KAH-rroo","ex":"Deixei o carro estacionado perto da estação.","exE":"I left the car parked near the station.","note":"Em Portugal conduz-se um carro — o verbo é «conduzir», nunca «dirigir». «Automóvel» é o termo formal e «viatura» aparece na linguagem policial.","noteE":"In Portugal you \"conduzir\" a car, never \"dirigir\" (Brazilian). \"Automóvel\" is the formal word; \"viatura\" is police-speak."},
  "o casaco": {"ipa":"kah-ZAH-koo","ex":"Veste o casaco antes de sair.","exE":"Put your coat on before you go out.","note":"Abrange casaco, blusão e casaco de malha — o contexto decide. O verbo é «vestir o casaco», enquanto para sapatos e chapéus se diz «calçar» e «pôr».","noteE":"It covers coats, jackets and cardigans alike — context decides. You \"vestir\" a coat, whereas shoes are \"calçar\" and hats \"pôr\"."},
  "o caso": {"ipa":"oo KAH-zoo","ex":"Nesse caso, é melhor ficarmos em casa.","exE":"In that case, we'd better stay home.","note":"O \"s\" entre vogais lê-se como \"z\". Colocação fixa muito útil: \"em caso de\", \"no caso de\", \"fazer caso de\" (dar importância a).","noteE":"The s between vowels is pronounced z, so it rhymes with 'razoo'. Useful set phrases: em caso de ('in case of') and fazer caso de ('to pay attention to')."},
  "o centro": {"ipa":"SEH (nasal)-troo","ex":"Moro no centro, perto da estação.","exE":"I live in the centre, near the station.","note":"\"O centro\" sozinho é a baixa da cidade. Atenção: \"centro comercial\" é um shopping mall, não um bairro de escritórios.","noteE":"\"O centro\" on its own means the town centre. Careful: \"centro comercial\" is a shopping mall, not a business district."},
  "o chão": {"ipa":"shown (nasal)","ex":"O gato está a dormir no chão.","exE":"The cat is sleeping on the floor.","note":"«No chão» é a superfície onde se pisa; o piso de um edifício é «o andar». Plural irregular: os chãos.","noteE":"'Chão' is the ground you walk on; a storey of a building is 'o andar'. Irregular plural: os chãos."},
  "o cinto": {"ipa":"SEEN (nasal)-too","ex":"Aperta o cinto de segurança, por favor.","exE":"Fasten your seatbelt, please.","note":"«Cinto de segurança» é o cinto do carro e diz-se «apertar o cinto». Não confundir com «a cinta», que é uma faixa elástica de vestuário.","noteE":"\"Cinto de segurança\" is the seatbelt, and you \"apertar\" it. Don't confuse it with \"a cinta\", an elasticated body band."},
  "o clube": {"ipa":"oo KLOO-buh","ex":"O meu irmão é sócio do clube.","exE":"My brother is a member of the club.","note":"É masculino apesar de terminar em -e. \"Ser sócio de um clube\" é a expressão usada para pertencer a ele.","noteE":"It is masculine despite the -e ending. Membership is expressed as ser sócio de um clube."},
  "o comércio": {"ipa":"koo-MEHR-see-oo","ex":"O comércio local fecha ao domingo.","exE":"Local shops close on Sundays.","note":"«Comércio» designa muitas vezes as lojas de rua em conjunto: «o comércio tradicional».","noteE":"Often means the shops/retail trade collectively, not just abstract commerce: 'o comércio tradicional' = the old high-street shops."},
  "o congresso": {"ipa":"ko (nasal)-GREH-soo","ex":"O congresso de medicina decorre em Coimbra.","exE":"The medical conference is taking place in Coimbra.","note":"Em Portugal é sobretudo um encontro científico ou partidário, não uma câmara legislativa (essa é a Assembleia da República).","noteE":"In Portugal this usually means an academic or party conference, not a legislature — parliament is the Assembleia da República."},
  "o conhecimento": {"ipa":"oo koo-nyuh-see-ME (nasal)-too","ex":"Ela tem um bom conhecimento de história.","exE":"She has a good knowledge of history.","note":"Usa-se muitas vezes no plural, \"conhecimentos\", para falar de saberes adquiridos; \"tomar conhecimento de\" significa ficar a saber, em registo formal.","noteE":"Often used in the plural, conhecimentos, for skills or learning acquired; tomar conhecimento de is the formal way to say to be informed of."},
  "o conjunto": {"ipa":"koh (nasal)-ZHOON (nasal)-too","ex":"No conjunto, a proposta parece razoável.","exE":"On the whole, the proposal seems reasonable.","note":"«No conjunto» significa no geral e «em conjunto» significa juntos. Também designa um grupo musical e um fato de duas peças a condizer.","noteE":"\"No conjunto\" means overall; \"em conjunto\" means together. It also names a musical group or a matching two-piece outfit."},
  "o conselho": {"ipa":"oo ko (nasal)-SAY-lyoo","ex":"Dá-me um conselho, por favor.","exE":"Give me some advice, please.","note":"Não confundir com \"concelho\", que se pronuncia igual mas significa município. Ao contrário do inglês, conselho é contável: \"dois conselhos\".","noteE":"Do not confuse it with concelho, pronounced identically but meaning a municipality. Unlike English advice, conselho is countable: dois conselhos."},
  "o contacto": {"ipa":"ko (nasal)-TAHK-too","ex":"Estou em contacto com ela todas as semanas.","exE":"I'm in contact with her every week.","note":"Em Portugal escreve-se e pronuncia-se o «c»: «contacto» (no Brasil, «contato»). Diz-se «estar em contacto com».","noteE":"In Portugal the c is written and pronounced: 'contacto' (Brazil writes 'contato'). Use 'estar em contacto com'."},
  "o continente": {"ipa":"koh (nasal)-tee-NEH (nasal)-tuh","ex":"Vivi nos Açores, mas nasci no continente.","exE":"I lived in the Azores, but I was born on the mainland.","note":"Em Portugal, \"o continente\" é sobretudo o território continental, por oposição aos Açores e à Madeira. É também o nome de uma grande cadeia de supermercados.","noteE":"In Portugal \"o continente\" mostly means the mainland, as opposed to the Azores and Madeira. It is also the name of a big supermarket chain."},
  "o conto": {"ipa":"KOH (nasal)-too","ex":"Ela leu um conto às filhas antes de dormir.","exE":"She read the girls a tale before bed.","note":"«Conto» é uma narrativa curta de ficção; para acontecimentos reais diz-se «história» ou «relato». Antigamente um «conto» eram mil escudos.","noteE":"A \"conto\" is a short fictional tale; for real events use \"história\". Older Portuguese also used \"conto\" for a thousand escudos."},
  "o coração": {"ipa":"oo koo-rah-SOW (nasal)","ex":"Ele agradeceu de coração.","exE":"He thanked them from the heart.","note":"\"Saber de cor\" significa saber de memória e vem justamente de \"cor\", coração em latim. O plural é corações.","noteE":"Saber de cor means to know by heart and comes from cor, Latin for heart. The plural is corações."},
  "o corpo": {"ipa":"oo KOHR-poo","ex":"Depois do treino, dói-me o corpo todo.","exE":"After training, my whole body aches.","note":"Com partes do corpo usa-se o artigo definido e não o possessivo: \"dói-me a cabeça\", não \"dói a minha cabeça\". Repare no pronome enclítico.","noteE":"With body parts Portuguese uses the definite article plus a pronoun, not a possessive: dói-me a cabeça, literally 'the head hurts me'."},
  "o correio": {"ipa":"oo koo-RRAY-oo","ex":"Vou ao correio enviar esta encomenda.","exE":"I'm going to the post office to send this parcel.","note":"Serve para o serviço e para as cartas recebidas; em Portugal os correios são os CTT. E-mail diz-se \"correio eletrónico\" em registo formal, mas na fala usa-se \"e-mail\".","noteE":"It covers both the postal service and the post you receive; in Portugal the post office is the CTT. Email is formally correio eletrónico, but people say e-mail."},
  "o cotovelo": {"ipa":"oo koo-too-VAY-loo","ex":"Apoiou os cotovelos na mesa.","exE":"He rested his elbows on the table.","note":"\"Dor de cotovelo\" é uma expressão idiomática para ciúme ou despeito amoroso, e não uma dor física.","noteE":"Dor de cotovelo literally 'elbow ache' is the idiom for jealousy or heartache after a breakup, not a physical pain."},
  "o crescimento": {"ipa":"kruhsh-see-MEN (nasal)-too","ex":"O crescimento da empresa abrandou este ano.","exE":"The company's growth slowed this year.","note":"O grupo «sc» lê-se «sh-s»: «cresh-cimento». O verbo é «crescer».","noteE":"The 'sc' is pronounced sh-s. The related verb is 'crescer' (to grow)."},
  "o crime": {"ipa":"KREE-muh","ex":"A polícia está a investigar o crime.","exE":"The police are investigating the crime.","note":"O verbo é «cometer um crime»; a pessoa é «o criminoso», não «o crime».","noteE":"The verb is 'cometer um crime'. The person is 'o criminoso' — don't reuse 'crime' for the offender."},
  "o curso": {"ipa":"oo KOOR-soo","ex":"Ela tirou o curso de Direito em Coimbra.","exE":"She did her law degree in Coimbra.","note":"Em Portugal, \"tirar um curso\" significa fazer uma licenciatura completa; uma disciplina isolada é \"uma cadeira\" e uma aula é \"uma aula\".","noteE":"In Portugal tirar um curso means completing a whole degree; a single subject is uma cadeira and a lesson is uma aula."},
  "o custo": {"ipa":"KOOSH-too","ex":"O custo de vida subiu muito em Lisboa.","exE":"The cost of living has risen a lot in Lisbon.","note":"«A custo» é uma expressão diferente: significa com muita dificuldade.","noteE":"Careful: the phrase 'a custo' does not mean 'at a cost' — it means 'with great difficulty'."},
  "o cão": {"ipa":"kown (nasal)","ex":"O cão do vizinho ladra a noite toda.","exE":"The neighbour's dog barks all night.","note":"O plural é irregular: «os cães». Em Portugal «cachorro» é um cachorro-quente ou, raramente, um cão bebé — o animal adulto é sempre «cão».","noteE":"The plural is irregular: \"os cães\". In Portugal \"cachorro\" mostly means a hot dog, so use \"cão\" for the animal."},
  "o céu": {"ipa":"oo seh-oo","ex":"O céu está limpo esta manhã.","exE":"The sky is clear this morning.","note":"A mesma palavra serve para o céu físico e para o céu religioso, que o inglês separa em sky e heaven. Diz-se \"no céu\", com em + o.","noteE":"One word covers both the sky and heaven, which English splits in two. You say no céu, from em plus o."},
  "o dado": {"ipa":"oo DAH-doo","ex":"Os dados do estudo ainda não são públicos.","exE":"The study's data is not public yet.","note":"No singular é o dado de jogar; para informação usa-se sempre o plural, \"os dados\", com verbo no plural. \"Dado que\" significa uma vez que.","noteE":"In the singular it is a gaming die; for information Portuguese always uses the plural os dados with a plural verb. Dado que means given that."},
  "o dedo": {"ipa":"oo DAY-doo","ex":"Cortei o dedo a preparar o jantar.","exE":"I cut my finger making dinner.","note":"A mesma palavra serve para os dedos da mão e do pé; se for preciso, diz-se \"dedo do pé\". O polegar tem nome próprio: \"o polegar\".","noteE":"One word for fingers and toes — say dedo do pé if you need to be specific. The thumb has its own name, o polegar."},
  "o desenvolvimento": {"ipa":"duh-zeh (nasal)-vol-vee-MEH (nasal)-too","ex":"O desenvolvimento do projeto está atrasado.","exE":"The development of the project is behind schedule.","note":"Palavra longa mas regular: a sílaba tónica é \"-men-\", nasalada. O verbo correspondente é \"desenvolver\", que também significa desenrolar.","noteE":"A long but regular word: the stress falls on the nasal \"-men-\". The matching verb is \"desenvolver\", which also means to unwrap."},
  "o deus": {"ipa":"deh-oosh","ex":"Os gregos tinham um deus para tudo.","exE":"The Greeks had a god for everything.","note":"Com maiúscula, \"Deus\", refere-se ao Deus único. A palavra aparece em expressões diárias sem sentido religioso: \"meu Deus!\", \"graças a Deus\", \"adeus\".","noteE":"Capitalised, \"Deus\" means the single God. It shows up in everyday phrases with no religious weight: \"meu Deus!\", \"graças a Deus\", \"adeus\"."},
  "o dia": {"ipa":"oo DEE-ah","ex":"Bom dia! Que dia lindo.","exE":"Good morning! What a lovely day.","note":"Masculino, apesar de terminar em -a; 'todos os dias' = every day.","noteE":"Masculine, despite ending in -a; 'todos os dias' = every day."},
  "o dinheiro": {"ipa":"dee-NYAY-roo","ex":"Não trago dinheiro, posso pagar com cartão?","exE":"I haven't got cash on me, can I pay by card?","note":"Não tem plural: é sempre \"dinheiro\", nunca \"dinheiros\". \"Pagar em dinheiro\" quer dizer pagar em numerário, por oposição a cartão.","noteE":"It has no plural: always \"dinheiro\", never \"dinheiros\". \"Pagar em dinheiro\" means to pay cash, as opposed to by card."},
  "o diploma": {"ipa":"dee-PLOH-mah","ex":"Ele tirou o diploma no ano passado.","exE":"He got his diploma last year.","note":"É masculino apesar de terminar em -a. Na linguagem jurídica, «diploma legal» é um texto de lei, sentido que não existe em inglês.","noteE":"Masculine despite the -a ending. In legal language a \"diploma legal\" is a piece of legislation — a sense English lacks."},
  "o direito": {"ipa":"oo dee-RAY-too","ex":"Toda a gente tem direito à educação.","exE":"Everyone has a right to education.","note":"Significa direito legal e também a disciplina de Direito. Como advérbio, \"em frente\" é que indica direção; \"à direita\" é o lado, e são coisas distintas.","noteE":"It means a legal right and also the university subject 'Law'. Don't confuse it with à direita ('on the right-hand side') — different word, different job."},
  "o documento": {"ipa":"doo-koo-MEN (nasal)-too","ex":"Traz os documentos do carro, por favor.","exE":"Bring the car's documents, please.","note":"No plural e sem mais contexto, «os documentos» são normalmente os documentos de identificação.","noteE":"In the plural with no further context, 'os documentos' usually means your ID papers."},
  "o efeito": {"ipa":"ee-FAY-too","ex":"O remédio já fez efeito.","exE":"The medicine has already taken effect.","note":"Diz-se «fazer efeito», não «tomar efeito». «Com efeito» é uma expressão formal que significa «de facto», comum na escrita.","noteE":"The verb is \"fazer efeito\", not a literal \"take effect\". \"Com efeito\" is a formal written way of saying \"indeed\"."},
  "o elemento": {"ipa":"ee-luh-MEN (nasal)-too","ex":"Cada elemento do grupo apresentou uma ideia.","exE":"Each member of the group presented an idea.","note":"Em português europeu «elemento» é muito usado para uma pessoa de um grupo ou equipa, onde o inglês diria «member». Também é o elemento químico.","noteE":"In European Portuguese \"elemento\" is regularly used for a person on a team, where English says \"member\". It is also a chemical element."},
  "o eletrodoméstico": {"ipa":"ee-leh-troo-doo-MEHSH-tee-koo","ex":"Este eletrodoméstico gasta pouca eletricidade.","exE":"This appliance uses little electricity.","note":"Escreve-se sem «c» desde o Acordo Ortográfico (antes «electro-»). Usa-se sobretudo no plural, para o conjunto de máquinas da casa.","noteE":"Spelled without the old \"c\" since the reform (\"electro-\"). It is used mostly in the plural, for household machines as a group."},
  "o encontro": {"ipa":"oo e (nasal)-KO (nasal)-troo","ex":"Tivemos um encontro muito agradável ontem.","exE":"We had a very pleasant meeting yesterday.","note":"Um encontro é entre pessoas (pode ser um encontro amoroso); para trabalho diz-se reunião. \"Ao encontro de\" significa a favor de, \"de encontro a\" significa contra.","noteE":"An encontro is between people and can mean a date; for work you say reunião. Careful: ao encontro de means in line with, de encontro a means against."},
  "o erro": {"ipa":"AY-rroo","ex":"Cometi um erro no exame.","exE":"I made a mistake in the exam.","note":"Diz-se «cometer» ou «dar» um erro, nunca «fazer». Um «engano» é uma confusão, não uma falha técnica.","noteE":"You 'cometer' or 'dar' an erro — never 'fazer um erro'. An 'engano' is a mix-up rather than a technical mistake."},
  "o escritor / a escritora": {"ipa":"shkree-TOR / shkree-TOH-rah","ex":"A escritora vai apresentar o livro amanhã.","exE":"The writer is presenting her book tomorrow.","note":"O «e» inicial quase desaparece na fala: diz-se «shcritor». O feminino é regular: escritora.","noteE":"The initial e almost vanishes in speech, giving 'shcritor'. The feminine is regular: escritora."},
  "o esforço": {"ipa":"shFOR-soo","ex":"Fez um grande esforço para vir.","exE":"He made a big effort to come.","note":"«Fazer um esforço» ou «esforçar-se por» + infinitivo; nunca «esforçar-se para fazer» na norma cuidada.","noteE":"Say 'fazer um esforço' or the reflexive 'esforçar-se por' + infinitive."},
  "o espaço": {"ipa":"sh-PAH-soo","ex":"Não há espaço para mais uma cadeira.","exE":"There isn't room for another chair.","note":"Serve tanto para o espaço sideral como para o espaço físico disponível — onde o inglês usa «room». «Espaço de tempo» é uma colocação fixa.","noteE":"Covers outer space and also plain \"room\" for something. \"Espaço de tempo\" (a span of time) is a fixed collocation."},
  "o espírito": {"ipa":"oo ish-PEE-ree-too","ex":"Ele tem muito espírito de equipa.","exE":"He has a great team spirit.","note":"\"Ter espírito\" pode também significar ter graça, ser espirituoso. As bebidas alcoólicas não são \"espíritos\": diz-se bebidas brancas ou destilados.","noteE":"Ter espírito can also mean to be witty. Alcoholic spirits are not espíritos; Portuguese says bebidas brancas or destilados."},
  "o estado": {"ipa":"oo ish-TAH-doo","ex":"O carro está em bom estado.","exE":"The car is in good condition.","note":"Com maiúscula (o Estado) refere-se ao poder político; com minúscula significa condição ou situação. Note-se a semelhança enganadora com a forma verbal \"estado\" (particípio de estar).","noteE":"Capitalised, o Estado is the political state; lower case it means condition ('in good shape'). It is also the past participle of estar, so tenho estado doente is unrelated."},
  "o estilo": {"ipa":"shTEE-loo","ex":"Gosto muito do teu estilo.","exE":"I really like your style.","note":"«Ao estilo de» = à maneira de. Para dizer que algo não é do nosso gosto, diz-se «não faz o meu género».","noteE":"'Ao estilo de' means in the manner of. To say something isn't your type, Portuguese says 'não faz o meu género'."},
  "o estrangeiro / a estrangeira": {"ipa":"oo ish-tra (nasal)-ZHAY-roo / ah ish-tra (nasal)-ZHAY-rah","ex":"Ele vive no estrangeiro há dez anos.","exE":"He has lived abroad for ten years.","note":"\"No estrangeiro\" significa fora do país e é a forma mais comum de dizer \"abroad\". Não confundir com \"estranho\", que significa esquisito.","noteE":"No estrangeiro means outside the country and is the usual way to say abroad. Do not confuse it with estranho, meaning strange."},
  "o estudo": {"ipa":"sh-TOO-doo","ex":"Este estudo mostra que dormimos pouco.","exE":"This study shows that we sleep too little.","note":"Falso amigo perigoso: \"estúdio\" (com acento) é um studio de televisão ou um apartamento pequeno; \"estudo\" é a investigação ou o ato de estudar.","noteE":"A dangerous false friend: \"estúdio\" is a TV studio or a studio flat, while \"estudo\" is research or the act of studying."},
  "o exterior": {"ipa":"oo aysh-tuh-ree-OR","ex":"Ele trabalhou no exterior durante dois anos.","exE":"He worked abroad for two years.","note":"\"No exterior\" quer dizer no estrangeiro, sobretudo em linguagem de notícias; para \"lá fora\" no sentido físico diz-se \"cá fora\" ou \"lá fora\".","noteE":"No exterior means abroad, especially in news language; for physically outside, Portuguese prefers cá fora or lá fora."},
  "o exército": {"ipa":"ee-ZEHR-see-too","ex":"O irmão dela está no exército.","exE":"Her brother is in the army.","note":"O «x» lê-se «z», como em «exame». Diz-se «estar no exército», não «ao exército».","noteE":"The x is pronounced z, as in 'exame'. You say 'estar no exército' to mean serving in the army."},
  "o facto": {"ipa":"FAH-too","ex":"De facto, tens razão.","exE":"In fact, you're right.","note":"Em Portugal escreve-se 'facto' (com c); no Brasil, 'fato'. 'De facto' = in fact.","noteE":"In Portugal it's spelled 'facto' (with a c); in Brazil 'fato'. 'De facto' = in fact."},
  "o fator": {"ipa":"fah-TOR","ex":"O tempo é um fator importante nesta decisão.","exE":"Time is an important factor in this decision.","note":"Depois do Acordo Ortográfico escreve-se «fator», sem o «c» mudo antigo («factor»).","noteE":"Since the 1990 spelling agreement it is written 'fator', without the old silent c of 'factor'."},
  "o filho": {"ipa":"oo FEE-lyoo","ex":"Eles têm um filho.","exE":"They have a son.","note":"'Os filhos' pode significar 'children' (filhos e filhas).","noteE":"'Os filhos' can mean 'children' (sons and daughters together)."},
  "o filme": {"ipa":"FEEL-muh","ex":"Vimos um filme português ontem à noite.","exE":"We watched a Portuguese film last night.","note":"Masculino apesar do -e. Repara na preposição: \"ver um filme\" mas \"ir ao cinema\". \"Fita\" é uma palavra antiquada para filme.","noteE":"Masculine despite the -e. Note the prepositions: \"ver um filme\" but \"ir ao cinema\". \"Fita\" is an old-fashioned word for a film."},
  "o fim": {"ipa":"fee (nasal)","ex":"Até ao fim de semana!","exE":"See you at the weekend!","note":"Nasal; 'fim de semana' = weekend; 'ao fim de' = at the end of.","noteE":"Nasal; 'fim de semana' = weekend; 'ao fim de' = at the end of."},
  "o final": {"ipa":"fee-NAL","ex":"O final do filme deixou-me a chorar.","exE":"The end of the film left me in tears.","note":"Cuidado com o género: \"o final\" é o desfecho, mas \"a final\" é o jogo decisivo de uma competição. Diz-se \"no final de contas\".","noteE":"Watch the gender: \"o final\" is the ending, but \"a final\" is the deciding match of a competition. Note the phrase \"no final de contas\" (at the end of the day)."},
  "o fogão": {"ipa":"foo-GOWN (nasal)","ex":"Deixaste a panela ao lume no fogão.","exE":"You left the pot on the heat on the stove.","note":"É o aparelho completo, com placa e forno; cada queimador é «um bico». Não confundir com «forno», que é só a parte de assar.","noteE":"It is the whole appliance, hob plus oven; each burner is \"um bico\". Don't mix it up with \"forno\", which is only the baking part."},
  "o forno": {"ipa":"FOHR-noo","ex":"O bolo já está no forno há meia hora.","exE":"The cake has been in the oven for half an hour.","note":"«No forno» é a forma normal de indicar o modo de cozinhar: «bacalhau no forno». «Isto está um forno» diz-se quando está muito calor.","noteE":"\"No forno\" is how you say oven-baked: \"bacalhau no forno\". \"Isto está um forno\" means the place is boiling hot."},
  "o frigorífico": {"ipa":"free-goo-REE-fee-koo","ex":"Põe o leite no frigorífico, se fazes favor.","exE":"Put the milk in the fridge, please.","note":"É a palavra de Portugal; no Brasil diz-se «geladeira». Na fala familiar encurta-se para «o frigo».","noteE":"This is the Portugal word; Brazil says \"geladeira\". Informally it gets clipped to \"o frigo\"."},
  "o frio": {"ipa":"FREE-oo","ex":"Tenho frio, fecha a janela.","exE":"I'm cold, close the window.","note":"A pessoa «tem frio»; a coisa ou o tempo «está frio». Nunca «sou frio» para o estado físico.","noteE":"People 'have' cold (tenho frio); things and weather 'are' cold (está frio). Never translate 'I am cold' with ser."},
  "o fundo": {"ipa":"FOON (nasal)-doo","ex":"A casa de banho é ao fundo do corredor.","exE":"The bathroom is at the end of the corridor.","note":"\"Ao fundo\" indica o extremo de um corredor ou sala; \"no fundo\" significa \"deep down, really\". No plural, \"fundos\" são verbas.","noteE":"\"Ao fundo\" points to the far end of a corridor or room; \"no fundo\" means \"deep down, really\". In the plural, \"fundos\" means funds."},
  "o futuro": {"ipa":"foo-TOO-roo","ex":"No futuro quero morar perto do mar.","exE":"In the future I want to live near the sea.","note":"Diz-se «no futuro», não «em futuro». Na fala, o tempo futuro é quase sempre substituído por «ir + infinitivo»: «vou fazer» em vez de «farei».","noteE":"The phrase is \"no futuro\". In speech the future tense is usually replaced by \"ir + infinitive\": \"vou fazer\" rather than \"farei\"."},
  "o gato": {"ipa":"GAH-too","ex":"O gato dorme sempre em cima do sofá.","exE":"The cat always sleeps on the couch.","note":"A fêmea é «a gata» e o diminutivo «gatinho» é muito usado. «Comprar gato por lebre» significa ser enganado num negócio.","noteE":"Female is \"a gata\", and \"gatinho\" (kitty) is common. \"Comprar gato por lebre\" means to be sold a dud."},
  "o governador": {"ipa":"goo-vuhr-nah-DOR","ex":"O governador do banco central falou hoje.","exE":"The central bank governor spoke today.","note":"Em Portugal usa-se sobretudo para o Banco de Portugal; as regiões autónomas têm «presidente do governo regional», não governador.","noteE":"In Portugal this mainly refers to the Bank of Portugal; the autonomous regions have a 'presidente do governo regional', not a governor."},
  "o governo": {"ipa":"oo goo-VAYR-noo","ex":"O governo aprovou a nova lei.","exE":"The government approved the new law.","note":"Leva sempre verbo no singular, ao contrário do inglês britânico: \"o governo decidiu\". Em Portugal, \"o Governo\" com maiúscula designa o executivo nacional.","noteE":"Always takes a singular verb — unlike British English, you never say 'the government have'. Capitalised it refers to the national executive."},
  "o grupo": {"ipa":"oo GROO-poo","ex":"Fazemos parte do mesmo grupo de estudo.","exE":"We're part of the same study group.","note":"Leva verbo no singular: \"o grupo chegou\", não \"chegaram\". Não confundir com \"a equipa\" (team), que em Portugal se escreve com -pa, não \"equipe\".","noteE":"Takes a singular verb: o grupo chegou. Note the European spelling of the related word for team — equipa, whereas Brazilians write equipe."},
  "o género": {"ipa":"ZHEH-nuh-roo","ex":"Que género de música é que preferes?","exE":"What kind of music do you prefer?","note":"Grafia europeia com acento agudo, «género» (no Brasil, «gênero»). Serve para género gramatical, género social e tipo/estilo.","noteE":"European spelling uses the acute: género (Brazil writes gênero). It covers grammatical gender, social gender, and genre or kind."},
  "o homem": {"ipa":"oo OH-meh (nasal)","ex":"O homem à porta é o meu pai.","exE":"The man at the door is my father.","note":"Plural irregular: 'os homens'.","noteE":"Irregular plural: 'os homens'."},
  "o indivíduo": {"ipa":"ee (nasal)-dee-VEE-doo-oo","ex":"Cada indivíduo tem os seus direitos.","exE":"Each individual has their rights.","note":"Em contexto formal é neutro, mas na fala pode soar depreciativo, como «aquele tipo».","noteE":"Neutral in formal writing, but in speech it can sound dismissive, like English 'that individual' or 'that guy'."},
  "o instrumento": {"ipa":"ee (nasal)-shtroo-MEN (nasal)-too","ex":"Tocas algum instrumento?","exE":"Do you play any instrument?","note":"Usa-se «tocar» um instrumento, nunca «jogar» (que é só para desportos e jogos).","noteE":"You 'tocar' an instrument — never 'jogar', which is only for sports and games."},
  "o interior": {"ipa":"oo ee (nasal)-tuh-ree-OR","ex":"Os meus avós vivem no interior do país.","exE":"My grandparents live in the interior of the country.","note":"Além de \"parte de dentro\", designa em Portugal as regiões afastadas da costa, por oposição ao litoral.","noteE":"Beyond meaning the inside of something, in Portugal it names the inland regions away from the coast, as opposed to o litoral."},
  "o investimento": {"ipa":"ee (nasal)-vesh-tee-MEN (nasal)-too","ex":"Este curso foi um bom investimento.","exE":"This course was a good investment.","note":"O verbo é «investir em»: «investi em ações». Note o «s» antes de consoante lido como «ch».","noteE":"The verb is 'investir em' (invest in). Note the s before a consonant is pronounced 'sh'."},
  "o início": {"ipa":"oo ee-NEE-see-oo","ex":"No início, não percebia nada.","exE":"At the beginning, I didn't understand anything.","note":"\"No início\" corresponde a \"at first\". Distingue-se do verbo \"iniciar\", mais formal do que \"começar\" na conversa do dia a dia.","noteE":"No início is the natural way to say 'at first'. The related verb iniciar is formal — in conversation people say começar."},
  "o irmão": {"ipa":"oo eer-MOW (nasal)","ex":"O meu irmão é mais novo.","exE":"My brother is younger.","note":"Plural irregular 'os irmãos'; 'mais novo' = younger.","noteE":"Irregular plural 'os irmãos'; 'mais novo' = younger."},
  "o joelho": {"ipa":"oo zhoo-AY-lyoo","ex":"Caí e magoei o joelho.","exE":"I fell and hurt my knee.","note":"O \"j\" tem o som de \"s\" em \"pleasure\" e o \"lh\" soa como o \"lli\" de \"million\". \"De joelhos\" significa ajoelhado.","noteE":"The j is the 's' in 'pleasure' and lh is the 'lli' in 'million'. De joelhos means 'kneeling'."},
  "o jogador / a jogadora": {"ipa":"oo zhoo-gah-DOR / ah zhoo-gah-DOH-rah","ex":"Este jogador marcou dois golos.","exE":"This player scored two goals.","note":"Vale para desporto e para jogos de mesa, mas também designa quem joga a dinheiro. Em Portugal diz-se \"golo\", não \"gol\".","noteE":"It covers sport and board games, but also a gambler. In Portugal a goal is golo, not the Brazilian gol."},
  "o jogo": {"ipa":"ZHOH-goo","ex":"O jogo do Benfica é amanhã à noite.","exE":"Benfica's match is tomorrow evening.","note":"Uma só palavra para game e match — o inglês distingue, o português não. \"Estar em jogo\" significa estar em causa, at stake.","noteE":"One word covers both game and match, a distinction English makes and Portuguese doesn't. \"Estar em jogo\" means to be at stake."},
  "o jornal": {"ipa":"zhoor-NAL","ex":"O meu avô lê o jornal todas as manhãs.","exE":"My grandfather reads the newspaper every morning.","note":"Em Portugal, \"o jornal\" é também o noticiário da televisão (\"o Jornal da Noite\"). O plural é \"jornais\"; um diário pessoal é \"um diário\".","noteE":"In Portugal \"o jornal\" is also the TV news bulletin (\"o Jornal da Noite\"). The plural is \"jornais\"; a personal diary is \"um diário\"."},
  "o lado": {"ipa":"oo LAH-doo","ex":"A farmácia fica ao lado do café.","exE":"The pharmacy is next to the café.","note":"\"Ao lado de\" é a maneira normal de dizer \"next to\". \"Por outro lado\" introduz um contra-argumento, tal como \"on the other hand\".","noteE":"Ao lado de is the everyday way to say 'next to', and por outro lado is exactly English 'on the other hand' when weighing two views."},
  "o lago": {"ipa":"LAH-goo","ex":"Há um lago pequeno no meio do parque.","exE":"There's a small lake in the middle of the park.","note":"Distingue de \"a lagoa\", que é uma laguna ou lago pouco profundo junto ao mar, como a Lagoa de Óbidos. Em Portugal há mais lagoas do que lagos.","noteE":"Distinguish it from \"a lagoa\", a lagoon or shallow coastal lake, like the Lagoa de Óbidos. Portugal has more lagoas than lagos."},
  "o largo": {"ipa":"oo LAR-goo","ex":"Encontramo-nos no largo da igreja.","exE":"Let's meet in the square by the church.","note":"Um largo é uma praça pequena, muito comum nos topónimos portugueses. A mesma palavra é também o adjetivo que significa amplo.","noteE":"A largo is a small square, very common in Portuguese place names. The same word is also the adjective meaning wide."},
  "o livro": {"ipa":"oo LEE-vroo","ex":"Estou a ler um livro muito bom.","exE":"I'm reading a very good book.","note":"No plural, o \"s\" final soa \"sh\": \"livros\". Não confundir com \"livre\" (free) nem com \"a livraria\", que é a loja de livros, ao passo que a biblioteca é onde se requisita.","noteE":"False friend alert: a livraria is a bookshop, while a library is a biblioteca. In the plural livros the final s is pronounced 'sh'."},
  "o local": {"ipa":"loo-KAL","ex":"O local do concerto ainda não foi anunciado.","exE":"The venue for the concert hasn't been announced yet.","note":"Como substantivo é mais formal e específico do que \"lugar\" — refere-se ao sítio onde algo acontece. A mesma palavra também é adjetivo: \"o comércio local\".","noteE":"As a noun it is more formal and specific than \"lugar\" — the site where something happens. The same word is also an adjective: \"o comércio local\"."},
  "o lugar": {"ipa":"oo loo-GAR","ex":"Este lugar está ocupado?","exE":"Is this seat taken?","note":"Serve para sítio e também para lugar sentado no comboio ou no cinema. \"Em vez de\" é que traduz \"instead of\", não \"em lugar\" sozinho.","noteE":"Covers both 'place' and 'seat' on a train or at the cinema. For 'instead of' say em vez de (or em lugar de) — never lugar alone."},
  "o mar": {"ipa":"mar","ex":"O mar está frio, mas vou nadar.","exE":"The sea is cold, but I'm going for a swim.","note":"É masculino: \"o mar\". Nota \"à beira-mar\" (by the sea) e que os portugueses dizem \"ir à praia\", não \"ir ao mar\", para um dia de praia.","noteE":"It is masculine: \"o mar\". Note \"à beira-mar\" (seaside), and that Portuguese people say \"ir à praia\", not \"ir ao mar\", for a beach day."},
  "o marido": {"ipa":"oo mah-REE-doo","ex":"O marido dela trabalha num banco.","exE":"Her husband works at a bank.","note":"O feminino não é \"marida\": diz-se \"a mulher\" ou, mais formalmente, \"a esposa\". \"Esposo\" existe mas soa pomposo na fala corrente.","noteE":"There is no 'marida' — the wife is a mulher, or more formally a esposa. The matching esposo exists but sounds stiff in everyday speech."},
  "o material": {"ipa":"mah-tuh-ree-AHL","ex":"Trouxeste o material para a aula?","exE":"Did you bring the supplies for the class?","note":"O plural é «materiais». Em Portugal «material escolar» são os cadernos e canetas, e «material» pode ser qualquer equipamento necessário.","noteE":"The plural is \"materiais\". \"Material escolar\" means school supplies, and \"material\" can mean any needed equipment or kit."},
  "o medo": {"ipa":"oo MAY-doo","ex":"Tenho medo de andar de avião.","exE":"I'm afraid of flying.","note":"Usa-se com ter, não com estar: \"tenho medo de\". \"Receio\" existe mas é bastante mais formal e escrito.","noteE":"It goes with ter, not estar: tenho medo de. Receio exists but is noticeably more formal and written."},
  "o meio": {"ipa":"MAY-oo","ex":"A mesa está no meio da sala.","exE":"The table is in the middle of the room.","note":"Como advérbio, «meio» não varia: «ela está meio cansada». Como adjetivo, concorda: «meia hora».","noteE":"As an adverb 'meio' never changes ('ela está meio cansada'), but as an adjective it agrees ('meia hora')."},
  "o membro": {"ipa":"MEN (nasal)-broo","ex":"Ela é membro da associação há dez anos.","exE":"She has been a member of the association for ten years.","note":"Costuma manter a forma masculina mesmo referindo mulheres («ela é membro»). Em anatomia, «os membros» são os braços e as pernas.","noteE":"It usually stays masculine even for women (\"ela é membro\"). In anatomy, \"os membros\" are the limbs."},
  "o mercado": {"ipa":"mer-KAH-doo","ex":"Ao domingo vamos ao mercado comprar legumes.","exE":"On Sundays we go to the market to buy vegetables.","note":"\"Mercado\" é a praça ou o mercado municipal; para as compras da semana os portugueses vão \"ao supermercado\" ou \"às compras\".","noteE":"\"Mercado\" is the market square or covered market; for the weekly shop Portuguese people go \"ao supermercado\" or \"às compras\"."},
  "o metro": {"ipa":"MEH-troo","ex":"Vou de metro para o trabalho.","exE":"I go to work by underground.","note":"Em Portugal é «o metro» (do Porto, de Lisboa); a forma brasileira «metrô» não se usa. Também significa a unidade de medida.","noteE":"In Portugal the underground is 'o metro' — the Brazilian 'metrô' is never used. It also means metre."},
  "o ministro / a ministra": {"ipa":"mee-NEESH-troo / mee-NEESH-trah","ex":"O primeiro-ministro vai falar ao país.","exE":"The prime minister is going to address the nation.","note":"Ao contrário de \"presidente\", tem forma feminina própria: \"a ministra\". O chefe do governo português é \"o primeiro-ministro\", com hífen.","noteE":"Unlike \"presidente\", it has its own feminine form: \"a ministra\". The Portuguese head of government is \"o primeiro-ministro\", hyphenated."},
  "o minuto": {"ipa":"oo mee-NOO-too","ex":"Espera um minuto, já venho.","exE":"Wait a minute, I'll be right back.","note":"Cuidado com o género: é masculino, ao contrário de \"a hora\". \"Ao minuto\" significa em direto ou atualizado ao instante.","noteE":"Masculine, unlike a hora, so it's um minuto but uma hora. Ao minuto means 'live' or 'up to the minute' in news reporting."},
  "o modo": {"ipa":"MOH-doo","ex":"De qualquer modo, vou ligar-lhe amanhã.","exE":"In any case, I'll call him tomorrow.","note":"Na fala corrente ouve-se mais \"maneira\"; \"modo\" fica em expressões fixas como \"de qualquer modo\", \"de modo que\" e \"modo de usar\" nas embalagens.","noteE":"In everyday speech \"maneira\" is commoner; \"modo\" survives in set phrases like \"de qualquer modo\", \"de modo que\" and \"modo de usar\" on packaging."},
  "o momento": {"ipa":"oo moo-MEH (nasal)-too","ex":"Neste momento não posso falar.","exE":"I can't talk right now.","note":"\"Neste momento\" e \"de momento\" traduzem \"right now\" e \"for the time being\". \"Um momento!\" é a fórmula para pedir a alguém que espere.","noteE":"Neste momento is 'right now' and de momento is 'for the time being'. Um momento! is how you ask someone to hold on."},
  "o motivo": {"ipa":"moo-TEE-voo","ex":"Não há motivo para preocupação.","exE":"There's no reason to worry.","note":"Quase sinónimo de «razão», mas «motivo» é o que leva alguém a agir; também significa padrão decorativo.","noteE":"Close to 'razão', but 'motivo' is what drives someone to act; it also means a decorative pattern or motif."},
  "o movimento": {"ipa":"moo-vee-MEH (nasal)-too","ex":"Há muito movimento na rua ao sábado.","exE":"There's a lot of activity on the street on Saturdays.","note":"Além de \"movimento\" físico, usa-se para o bulício de um sítio: \"um café com muito movimento\" é um café cheio de gente.","noteE":"Beyond physical movement, it describes how busy a place is: \"um café com muito movimento\" is a bustling café."},
  "o mundo": {"ipa":"oo MOON-doo","ex":"É o melhor do mundo.","exE":"It's the best in the world.","note":"Em Portugal 'toda a gente' = everyone, não 'todo o mundo'.","noteE":"In Portugal 'everyone' is 'toda a gente', not 'todo o mundo'."},
  "o médico": {"ipa":"oo MEH-dee-koo","ex":"Amanhã vou ao médico de família.","exE":"Tomorrow I'm going to the family doctor.","note":"Diz-se \"ir ao médico\", com a preposição a. A forma feminina é \"a médica\"; ao dirigir-se a ele trata-se por \"senhor doutor\".","noteE":"You say ir ao médico, with the preposition a. The feminine is a médica, and you address one as senhor doutor."},
  "o método": {"ipa":"oo MEH-too-doo","ex":"Este método funciona muito melhor.","exE":"This method works much better.","note":"A sílaba tónica é a primeira, por causa do acento. Para algo mais informal, os portugueses dizem \"maneira\" ou \"forma\".","noteE":"The accent puts the stress on the first syllable. For something less technical, Portuguese speakers say maneira or forma."},
  "o mês": {"ipa":"oo maysh","ex":"No mês passado fui a Espanha.","exE":"Last month I went to Spain.","note":"O plural é \"os meses\" e perde o acento. Os nomes dos meses escrevem-se com minúscula em português: janeiro, fevereiro.","noteE":"Plural is meses, dropping the accent. Month names are written in lower case in Portuguese — janeiro, not Janeiro, since the spelling reform."},
  "o nariz": {"ipa":"oo nah-REESH","ex":"Estou constipado e tenho o nariz entupido.","exE":"I have a cold and my nose is blocked.","note":"Plural \"narizes\". Cuidado com o falso amigo \"constipado\": em Portugal significa estar com uma constipação (a cold), não prisão de ventre.","noteE":"Plural narizes. Big false friend nearby: estar constipado means 'to have a cold' in Portugal, not the English 'constipated'."},
  "o negócio": {"ipa":"nuh-GAW-syoo","ex":"Ele abriu um negócio de comida na baixa.","exE":"He opened a food business downtown.","note":"No singular é um negócio concreto ou uma empresa; no plural, «os negócios», é a atividade comercial em geral. A negociação em si é «a negociação».","noteE":"Singular is one concrete deal or firm; the plural \"os negócios\" is commerce in general. The act of negotiating is \"a negociação\"."},
  "o nome": {"ipa":"oo NOH-muh","ex":"Qual é o teu nome?","exE":"What's your name?","note":"Mais comum: 'como te chamas?'.","noteE":"More common: 'como te chamas?' = what's your name?"},
  "o norte": {"ipa":"NAWR-tuh","ex":"O Porto fica no norte do país.","exE":"Porto is in the north of the country.","note":"\"No norte\" é dentro da região; \"a norte de\" é para lá dela (\"Braga fica a norte do Porto\"). Escreve-se com maiúscula quando é a região: o Norte.","noteE":"\"No norte\" is inside the region; \"a norte de\" is beyond it (\"Braga fica a norte do Porto\"). Capitalised when it names the region: o Norte."},
  "o nível": {"ipa":"NEE-vehl","ex":"O meu nível de português está a melhorar.","exE":"My level of Portuguese is improving.","note":"O plural muda de forma: \"os níveis\", com o acento a desaparecer. \"A nível de\" e \"ao nível de\" são muito usados em linguagem formal.","noteE":"The plural changes shape: \"os níveis\", losing the accent. \"A nível de\" and \"ao nível de\" are common in formal register."},
  "o número": {"ipa":"NOO-muh-roo","ex":"Qual é o teu número de telefone?","exE":"What's your phone number?","note":"Acento no 'ú': NÚ-me-ro.","noteE":"Stress on the 'ú': NOO-muh-roo."},
  "o objetivo": {"ipa":"awb-zhuh-TEE-voo","ex":"O nosso objetivo é acabar até junho.","exE":"Our goal is to finish by June.","note":"Escreve-se sem c desde o Acordo Ortográfico (antes \"objectivo\"). A mesma palavra é adjetivo, \"uma análise objetiva\", e a lente de uma máquina.","noteE":"Written without the c since the spelling reform (formerly \"objectivo\"). The same word is an adjective, \"uma análise objetiva\", and a camera lens."},
  "o objeto": {"ipa":"oo awb-ZHEH-too","ex":"Encontrei um objeto estranho na gaveta.","exE":"I found a strange object in the drawer.","note":"Depois do acordo ortográfico escreve-se sem c (objeto), mas o o mantém-se aberto na pronúncia europeia. Não confundir com \"objetivo\", que é o propósito.","noteE":"Since the spelling reform it is written without the c, but the o stays open in European pronunciation. Do not confuse it with objetivo, meaning aim."},
  "o oceano": {"ipa":"oo-see-AH-noo","ex":"O oceano Atlântico banha toda a costa.","exE":"The Atlantic Ocean washes the whole coast.","note":"Mais técnico e geográfico do que \"mar\" — no dia a dia diz-se sempre \"o mar\", mesmo à beira do Atlântico. O nome próprio leva maiúscula: o Oceano Atlântico.","noteE":"More technical and geographical than \"mar\" — day to day people always say \"o mar\", even standing by the Atlantic. The proper name is capitalised: o Oceano Atlântico."},
  "o ocidente / oeste": {"ipa":"aw-see-DEH (nasal)-tuh / WEHSH-tuh","ex":"A costa oeste é mais fria e ventosa.","exE":"The west coast is colder and windier.","note":"\"Oeste\" é o ponto cardeal; \"o Ocidente\", com maiúscula, é o mundo ocidental em sentido político e cultural. Não se misturam.","noteE":"\"Oeste\" is the compass point; \"o Ocidente\", capitalised, is the West in the political and cultural sense. They aren't interchangeable."},
  "o olho": {"ipa":"oo OH-lyoo","ex":"Tenho uma coisa no olho.","exE":"I have something in my eye.","note":"O plural muda de som: \"os olhos\" abre a vogal. \"Custar os olhos da cara\" significa ser caríssimo, e \"olho\" no imperativo vem do verbo olhar.","noteE":"The plural olhos opens the vowel, so it shifts sound. Custar os olhos da cara is the idiom for 'to cost a fortune'."},
  "o ombro": {"ipa":"oo OH (nasal)-broo","ex":"Levava o saco ao ombro.","exE":"He was carrying the bag on his shoulder.","note":"O \"om\" inicial é nasal e não se pronuncia o \"m\". \"Encolher os ombros\" é o gesto de indiferença, o equivalente a \"to shrug\".","noteE":"The opening om is a nasal vowel — no m sound is actually pronounced. Encolher os ombros is the idiom for 'to shrug'."},
  "o oriente / este": {"ipa":"oo-ree-EH (nasal)-tuh / EHSH-tuh","ex":"O sol nasce a este, mesmo ali.","exE":"The sun rises in the east, right there.","note":"Como \"este\" (east) se confunde com \"este\" (this), muitos preferem dizer \"leste\", sobretudo na meteorologia. \"O Oriente\" refere-se às culturas asiáticas.","noteE":"Because \"este\" (east) clashes with \"este\" (this), many people say \"leste\" instead, especially in weather reports. \"O Oriente\" refers to Asian cultures."},
  "o padre": {"ipa":"oo PAH-druh","ex":"O padre celebrou a missa das nove.","exE":"The priest celebrated the nine o'clock mass.","note":"Apesar de parecer \"father\", nunca significa pai de família; pai é \"o pai\". Trata-se por \"senhor padre\" ou \"padre\" seguido do nome próprio.","noteE":"Despite looking like father, it never means a family father, which is o pai. He is addressed as senhor padre or padre plus a first name."},
  "o pai": {"ipa":"oo pie","ex":"O meu pai chama-se João.","exE":"My father's name is João.","note":"Plural 'os pais' = parents (não só 'fathers').","noteE":"Plural 'os pais' means 'parents', not just 'fathers'."},
  "o papel": {"ipa":"pah-PEHL","ex":"Ele teve um papel importante na decisão.","exE":"He played an important part in the decision.","note":"Significa paper e também role — \"desempenhar um papel\" é to play a role. O plural é \"papéis\", e \"papel higiénico\" é o de casa de banho.","noteE":"It means both paper and role — \"desempenhar um papel\" is to play a role. The plural is \"papéis\", and \"papel higiénico\" is toilet paper."},
  "o partido": {"ipa":"par-TEE-doo","ex":"Ela nunca votou nesse partido.","exE":"She has never voted for that party.","note":"Só serve para partido político — a festa é «a festa». É também o particípio de «partir» (partido = partido ao meio) e «tirar partido de» significa aproveitar.","noteE":"Only the political sense — a celebration is \"a festa\". It doubles as the participle of \"partir\" (broken), and \"tirar partido de\" means to make the most of."},
  "o passado": {"ipa":"pah-SAH-doo","ex":"No ano passado fomos de comboio até ao Porto.","exE":"Last year we took the train to Porto.","note":"Como adjetivo depois do substantivo significa «último»: «na semana passada», «no mês passado». Não confundir com «último», que é o final de uma série.","noteE":"As an adjective after the noun it means \"last\": \"na semana passada\". Don't swap it with \"último\", which means final in a sequence."},
  "o passo": {"ipa":"PAH-soo","ex":"Vamos com calma, um passo de cada vez.","exE":"Let's take it slowly, one step at a time.","note":"Diz-se \"dar um passo\", nunca \"fazer\". Não confundas o substantivo com \"passo\", a forma do verbo passar (\"eu passo\").","noteE":"You \"dar um passo\", never \"fazer\". Don't confuse the noun with \"passo\", the verb form of \"passar\" (I pass)."},
  "o país": {"ipa":"oo pah-EESH","ex":"Portugal é um país pequeno.","exE":"Portugal is a small country.","note":"Acento no 'í'; plural 'os países'. Não confundir com 'pais' (parents).","noteE":"Stress on the 'í'; plural 'os países'. Don't confuse with 'pais' (parents)."},
  "o peito": {"ipa":"oo PAY-too","ex":"Sentiu uma dor no peito.","exE":"He felt a pain in his chest.","note":"Serve para o peito de homem e de mulher e ainda para \"peito de frango\". Para o busto feminino usa-se também \"o peito\" no singular, de forma neutra.","noteE":"Covers the chest generally and also cuts of meat: peito de frango is chicken breast. It's the neutral, non-clinical word."},
  "o pelo": {"ipa":"oo PAY-loo","ex":"O gato tem o pelo muito macio.","exE":"The cat has very soft fur.","note":"Refere-se ao pelo do corpo e dos animais, nunca ao cabelo da cabeça. Escreve-se igual à contração \"pelo\" (por + o), distinguindo-se só pelo contexto.","noteE":"This is body hair or animal fur, never the hair on your head (that's cabelo). It's spelled identically to the contraction pelo (por + o)."},
  "o pensamento": {"ipa":"peh (nasal)-sah-MEN (nasal)-too","ex":"Perdi o fio ao pensamento.","exE":"I lost my train of thought.","note":"«Perder o fio ao pensamento» é a expressão feita; note a preposição «a», não «de».","noteE":"The fixed idiom is 'perder o fio ao pensamento' (lose the thread of thought) — with 'ao', not 'do'."},
  "o período": {"ipa":"puh-REE-oo-doo","ex":"Foi um período difícil da minha vida.","exE":"It was a difficult period of my life.","note":"Serve para intervalos de tempo e também para o período menstrual, tal como em inglês. Para o sinal de pontuação diz-se \"ponto final\", nunca \"período\".","noteE":"It covers stretches of time and the menstrual period, as in English. The punctuation mark is \"ponto final\", never \"período\"."},
  "o pescoço": {"ipa":"oo pish-KOH-soo","ex":"Acordei com o pescoço dorido.","exE":"I woke up with a sore neck.","note":"O \"ç\" garante o som de \"s\" antes de \"o\". Para a nuca diz-se \"a nuca\"; \"pescoço\" cobre a parte da frente e os lados.","noteE":"The cedilla keeps the s sound before o. For the back of the neck specifically, Portuguese has a nuca."},
  "o planeta": {"ipa":"oo plah-NEH-tah","ex":"Temos de proteger o planeta.","exE":"We have to protect the planet.","note":"É masculino apesar de terminar em -a, como \"o sistema\" e \"o problema\". Diz-se \"o planeta Terra\", com maiúscula só em Terra.","noteE":"Masculine despite ending in -a, like o sistema and o problema. In o planeta Terra only Terra takes a capital."},
  "o plano": {"ipa":"PLAH-noo","ex":"Tens algum plano para o fim de semana?","exE":"Have you got any plans for the weekend?","note":"Como adjetivo, \"plano\" significa flat (\"um terreno plano\"). Não confundas com \"a planta\", que é o plano desenhado de um edifício.","noteE":"As an adjective \"plano\" means flat (\"um terreno plano\"). Don't confuse it with \"a planta\", the drawn plan of a building."},
  "o ponto": {"ipa":"oo POH (nasal)-too","ex":"Não percebi esse ponto da explicação.","exE":"I didn't understand that point of the explanation.","note":"É também o sinal de pontuação: em Portugal escreve-se \"ponto final\" e usa-se vírgula nos decimais (3,5). \"Ponto de encontro\" é o local combinado.","noteE":"Also the punctuation mark. Remember Portugal uses a comma for decimals (3,5) and a point for thousands — the reverse of English."},
  "o povo": {"ipa":"POH-voo","ex":"O povo português é muito hospitaleiro.","exE":"The Portuguese people are very welcoming.","note":"Erro clássico: \"povo\" é um povo como coletivo ou nação, não \"people\" no sentido de várias pessoas. Para isso usa-se \"as pessoas\".","noteE":"Classic mistake: \"povo\" means a people or nation as a collective, not \"people\" meaning several individuals — that is \"as pessoas\"."},
  "o prazo": {"ipa":"oo PRAH-zoo","ex":"O prazo de entrega acaba na sexta.","exE":"The submission deadline ends on Friday.","note":"\"A curto/longo prazo\" significa a curto ou longo termo. \"Prazo de validade\" é a data de validade dos alimentos.","noteE":"A curto prazo and a longo prazo mean in the short and long term. Prazo de validade is a food expiry date."},
  "o presente": {"ipa":"pruh-ZEN (nasal)-tuh","ex":"Vive o presente sem pensar tanto no amanhã.","exE":"Live in the present without thinking so much about tomorrow.","note":"Para um objeto oferecido, os portugueses dizem quase sempre «prenda»; «presente» nesse sentido soa formal ou brasileiro. Como adjetivo significa «presente na sala».","noteE":"For a gift, Portuguese speakers nearly always say \"prenda\" — \"presente\" sounds formal or Brazilian. As an adjective it means present/in attendance."},
  "o preço": {"ipa":"PRAY-soo","ex":"O preço da casa subiu outra vez.","exE":"The price of the house has gone up again.","note":"Erro comum: não se diz \"preço barato\" — um preço é \"alto\" ou \"baixo\", e é o produto que é \"caro\" ou \"barato\". \"A que preço?\" pergunta quanto custa.","noteE":"Common mistake: you don't say \"preço barato\" — a price is \"alto\" or \"baixo\", and the product is \"caro\" or \"barato\". \"A que preço?\" asks how much."},
  "o primo / a prima": {"ipa":"oo PREE-moo / ah PREE-mah","ex":"A minha prima estuda em Coimbra.","exE":"My cousin studies in Coimbra.","note":"Ao contrário do inglês \"cousin\", a forma muda com o género. \"Primo\" é também o adjetivo em \"número primo\" e \"matéria-prima\".","noteE":"Unlike English 'cousin', the word shows gender: primo for a male, prima for a female. Primo also means 'prime' as in número primo."},
  "o princípio": {"ipa":"preen (nasal)-SEE-pyoo","ex":"No princípio foi difícil, mas agora já gosto.","exE":"At the beginning it was hard, but now I like it.","note":"«No princípio» é «ao início» e «por princípio» é por convicção. Não confundir com «príncipe», que é o filho do rei.","noteE":"\"No princípio\" means at the start; \"por princípio\" means on principle. Don't mix it up with \"príncipe\", the king's son."},
  "o problema": {"ipa":"oo proo-BLEH-mah","ex":"Não há problema.","exE":"No problem.","note":"Masculino apesar do -a (vem do grego): 'o problema'.","noteE":"Masculine despite the -a (it's from Greek): 'o problema'."},
  "o processo": {"ipa":"oo proo-SEH-soo","ex":"O processo demora algumas semanas.","exE":"The process takes a few weeks.","note":"Além de \"process\", significa \"processo judicial\" e ainda o dossiê de uma pessoa. Repare no \"e\" aberto na sílaba tónica.","noteE":"Besides 'process' it means a court case, and also a personal file or dossier. Note the open e in the stressed syllable: proo-SEH-soo."},
  "o produto": {"ipa":"proo-DOO-too","ex":"Estes produtos são todos feitos em Portugal.","exE":"These products are all made in Portugal.","note":"No supermercado, \"produtos frescos\" são os do talho, peixaria e legumes. Não confundas com \"a produção\", que é o processo, não a coisa.","noteE":"At the supermarket, \"produtos frescos\" are the meat, fish and veg. Don't confuse it with \"a produção\", which is the process rather than the thing."},
  "o professor / a professora": {"ipa":"proo-fuh-SOHR / proo-fuh-SAW-rah","ex":"A minha professora de português é do Porto.","exE":"My Portuguese teacher is from Porto.","note":"Repara que o o fecha em \"professor\" e abre em \"professora\". Usa-se para qualquer docente, da primária à universidade, e serve de tratamento: \"Bom dia, professora\".","noteE":"Note the o is closed in \"professor\" and open in \"professora\". It covers any teacher from primary school to university, and works as a form of address: \"Bom dia, professora\"."},
  "o programa": {"ipa":"proo-GRAH-mah","ex":"Este programa da televisão é muito engraçado.","exE":"This TV programme is very funny.","note":"Apesar do -a final, é masculino (origem grega), tal como \"problema\", \"sistema\" e \"tema\". Também significa um plano de diversão: \"que programa temos para hoje?\".","noteE":"Despite the final -a it is masculine (Greek origin), like \"problema\", \"sistema\" and \"tema\". It also means a fun plan: \"que programa temos para hoje?\"."},
  "o projeto": {"ipa":"oo proo-ZHEH-too","ex":"Estamos a trabalhar num projeto novo.","exE":"We're working on a new project.","note":"Depois do Acordo Ortográfico perdeu o \"c\" (era \"projecto\"), mas o \"e\" continua aberto na pronúncia europeia.","noteE":"Since the spelling reform the c is gone (formerly projecto), yet European speakers still pronounce the e open — proo-ZHEH-too."},
  "o prédio": {"ipa":"oo PREH-dee-oo","ex":"Moro num prédio antigo em Lisboa.","exE":"I live in an old apartment block in Lisbon.","note":"Em Portugal prédio é sobretudo o edifício de apartamentos onde se mora; \"edifício\" é mais formal ou usa-se para construções públicas.","noteE":"In Portugal prédio is mainly the apartment block you live in; edifício is more formal or used for public buildings."},
  "o prémio": {"ipa":"PREH-mee-oo","ex":"Ganhou o prémio de melhor filme.","exE":"It won the prize for best film.","note":"Grafia europeia «prémio», com «é» aberto (no Brasil, «prêmio», fechado).","noteE":"European spelling 'prémio' with an open é; Brazil writes 'prêmio' with a closed vowel."},
  "o próprio": {"ipa":"PRAW-pree-oo","ex":"Falei com o próprio diretor.","exE":"I spoke with the director himself.","note":"«O próprio» enfatiza a pessoa em si; antes do substantivo significa «meu/teu... próprio»: «a minha própria casa».","noteE":"'O próprio' emphasises the very person themselves; before a noun it means 'own': 'a minha própria casa'."},
  "o pulso": {"ipa":"oo POOL-soo","ex":"O relógio ficou-me largo no pulso.","exE":"The watch was loose on my wrist.","note":"Significa também a pulsação: \"medir o pulso\". Não confundir com \"o punho\", que é o punho fechado e também o punho da camisa.","noteE":"It also means the pulse you measure. Don't mix it with o punho, which is the clenched fist and also a shirt cuff."},
  "o pé": {"ipa":"oo peh","ex":"Vou a pé para o trabalho.","exE":"I walk to work.","note":"\"A pé\" é a maneira normal de dizer \"on foot\" e \"estar de pé\" significa estar em posição vertical. O acento agudo marca o \"e\" aberto.","noteE":"Ir a pé is the everyday 'to go on foot' and estar de pé means 'to be standing'. The acute accent marks the open e."},
  "o público": {"ipa":"oo POO-blee-koo","ex":"O público aplaudiu no fim do concerto.","exE":"The audience applauded at the end of the concert.","note":"Como substantivo é a assistência; como adjetivo significa estatal ou aberto a todos (escola pública). \"Em público\" quer dizer diante de outras pessoas.","noteE":"As a noun it's the audience or crowd; as an adjective it means state-run or open to all (escola pública). Em público means 'in front of others'."},
  "o quadro": {"ipa":"KWAH-droo","ex":"Há um quadro antigo na parede da sala.","exE":"There's an old painting on the living-room wall.","note":"«Quadro» é o quadro pintado, mas também o quadro da sala de aula e uma tabela de dados.","noteE":"Covers a framed painting, a classroom board, and a table/chart of data — context decides."},
  "o quarto": {"ipa":"KWAR-too","ex":"O meu quarto é o do fundo do corredor.","exE":"My bedroom is the one at the end of the hall.","note":"Também significa «um quarto» como fração: «um quarto de hora», «as três e um quarto». «Quarto de casal» é o quarto com cama de casal.","noteE":"It also means a quarter: \"um quarto de hora\", \"as três e um quarto\". A \"quarto de casal\" is a double bedroom."},
  "o queixo": {"ipa":"oo KAY-shoo","ex":"Bateu com o queixo na mesa.","exE":"He hit his chin on the table.","note":"Não confundir com \"a queixa\" (complaint) nem com o verbo \"queixar-se\" (to complain), que são palavras próximas mas sem relação.","noteE":"Don't confuse it with a queixa ('a complaint') or queixar-se ('to complain') — they look alike but are unrelated."},
  "o quilómetro": {"ipa":"oo kee-LAW-muh-troo","ex":"A praia fica a dois quilómetros daqui.","exE":"The beach is two kilometres from here.","note":"Em Portugal escreve-se com acento agudo, quilómetro, com o aberto; no Brasil escreve-se quilômetro, com o fechado. Abrevia-se km.","noteE":"Portugal writes it with an acute accent and an open o; Brazil writes quilômetro with a closed o. The abbreviation is km."},
  "o rabo": {"ipa":"oo RRAH-boo","ex":"O cão abanou o rabo todo contente.","exE":"The dog wagged its tail happily.","note":"É a cauda de um animal e, em registo familiar, o traseiro de uma pessoa — informal mas não obsceno em Portugal. Em contexto formal diz-se \"o traseiro\".","noteE":"An animal's tail, and colloquially a person's bottom — casual but not obscene in Portugal. In formal contexts use o traseiro."},
  "o rapaz / o menino": {"ipa":"oo rrah-PAHSH / oo muh-NEE-noo","ex":"Aquele rapaz é o filho da vizinha.","exE":"That boy is the neighbour's son.","note":"Rapaz é a palavra corrente em Portugal para rapaz e jovem; menino é mais próprio de crianças pequenas ou de tratamento carinhoso. O plural é rapazes.","noteE":"Rapaz is the everyday Portuguese word for a boy or young man; menino suits small children or affectionate address. The plural is rapazes."},
  "o recurso": {"ipa":"rruh-KOOR-soo","ex":"Em último recurso, pedimos ajuda ao vizinho.","exE":"As a last resort, we asked the neighbour for help.","note":"Cobre três sentidos: meios disponíveis («recursos humanos»), último remédio («em último recurso») e o recurso judicial de uma sentença.","noteE":"Three senses in one word: available means (\"recursos humanos\"), a last resort (\"em último recurso\"), and a legal appeal."},
  "o rei": {"ipa":"rray","ex":"O rei vivia neste palácio.","exE":"The king lived in this palace.","note":"O plural é «os reis» e o Dia de Reis é a 6 de janeiro. O «r» inicial pronuncia-se na garganta, como o «rr» de «carro».","noteE":"Plural \"os reis\", and \"Dia de Reis\" is 6 January. The initial \"r\" is the throaty one, like the \"rr\" in \"carro\"."},
  "o respeito": {"ipa":"oo rrush-PAY-too","ex":"Trata os colegas com respeito.","exE":"He treats his colleagues with respect.","note":"\"A respeito de\" significa acerca de, sobre algum assunto. O verbo respeitar não leva preposição: \"respeitar alguém\".","noteE":"A respeito de means regarding or about a topic. The verb respeitar takes no preposition: respeitar alguém."},
  "o resto": {"ipa":"oo RREHSH-too","ex":"Comi o resto do bolo ao pequeno-almoço.","exE":"I ate the rest of the cake at breakfast.","note":"No plural, \"os restos\" são as sobras de comida. \"De resto\" é uma expressão de ligação que significa aliás, além disso.","noteE":"In the plural, os restos means leftovers. De resto is a linking phrase meaning besides or for that matter."},
  "o resultado": {"ipa":"rruh-zool-TAH-doo","ex":"O resultado do exame sai na sexta-feira.","exE":"The exam result comes out on Friday.","note":"\"Dar resultado\" significa funcionar, ter êxito: \"o remédio deu resultado\". Começa com r guttural, apesar de o r estar no início da palavra.","noteE":"\"Dar resultado\" means to work, to pay off: \"o remédio deu resultado\". It opens with the guttural r, since the r starts the word."},
  "o rio": {"ipa":"RREE-oo","ex":"O rio Tejo passa mesmo ao lado.","exE":"The river Tagus runs right alongside.","note":"O nome vem antes em português: \"o rio Douro\", ao contrário de \"the Douro river\". Começa com r guttural, como em \"rua\".","noteE":"The word comes first in Portuguese: \"o rio Douro\", the reverse of \"the Douro river\". It starts with the guttural r, as in \"rua\"."},
  "o risco": {"ipa":"RREESH-koo","ex":"Não vale a pena correr esse risco.","exE":"That risk isn't worth taking.","note":"«Correr o risco de» + infinitivo. «Risco» é também um traço feito com lápis.","noteE":"The pattern is 'correr o risco de' + infinitive. 'Risco' also means a line or scratch drawn on something."},
  "o sangue": {"ipa":"oo SA (nasal)-guh","ex":"Ele não suporta ver sangue.","exE":"He can't stand the sight of blood.","note":"No grupo -gue o u não se lê e o g é duro. \"Sangue-frio\" significa calma perante o perigo.","noteE":"In the -gue cluster the u is silent and the g is hard. Sangue-frio means composure in the face of danger."},
  "o santo / a santa": {"ipa":"SAH (nasal)-too / SAH (nasal)-tah","ex":"Santo António é o santo mais popular de Lisboa.","exE":"Saint Anthony is the most popular saint in Lisbon.","note":"Antes de nome próprio a forma muda: \"São\" antes de consoante (São João), \"Santo\" antes de vogal (Santo António) e \"Santa\" no feminino (Santa Maria).","noteE":"Before a name the form changes: \"São\" before a consonant (São João), \"Santo\" before a vowel (Santo António), \"Santa\" for women (Santa Maria)."},
  "o segundo": {"ipa":"oo suh-GOO (nasal)-doo","ex":"Faltam dez segundos para acabar.","exE":"There are ten seconds left to finish.","note":"É também o adjetivo ordinal \"segundo\" (o segundo lugar) e ainda a preposição \"segundo\" no sentido de \"de acordo com\": segundo o jornal.","noteE":"Three words in one: the unit of time, the ordinal 'second', and a preposition meaning 'according to' — segundo o jornal, 'according to the paper'."},
  "o senhor": {"ipa":"oo suh-NYOR","ex":"O senhor precisa de ajuda?","exE":"Do you need help, sir?","note":"Funciona como \"você\" formal e leva o verbo na terceira pessoa. Abrevia-se \"Sr.\" e é a forma segura para tratar desconhecidos mais velhos.","noteE":"It works as the polite 'you' and takes third-person verbs: o senhor precisa, not precisas. Abbreviated Sr., it is the safe way to address an older stranger."},
  "o sentido": {"ipa":"seh (nasal)-TEE-doo","ex":"Isso não faz sentido nenhum para mim.","exE":"That doesn't make any sense to me.","note":"\"Fazer sentido\" é a expressão para make sense, com o verbo fazer. Na estrada, \"sentido único\" é one-way, e os cinco sentidos são \"os cinco sentidos\".","noteE":"\"Fazer sentido\" is the phrase for to make sense, using fazer. On the road, \"sentido único\" means one-way, and the five senses are \"os cinco sentidos\"."},
  "o serviço": {"ipa":"oo sir-VEE-soo","ex":"O serviço neste restaurante é rápido.","exE":"The service in this restaurant is fast.","note":"Em Portugal, \"serviço\" também significa trabalho ou tarefa: \"tenho muito serviço\". \"Fora de serviço\" é o aviso nos elevadores e nas máquinas avariadas.","noteE":"In Portugal it also means work or a task: tenho muito serviço, 'I have a lot of work on'. Fora de serviço is the 'out of order' sign."},
  "o silêncio": {"ipa":"oo see-LAY (nasal)-syoo","ex":"Fizemos a viagem toda em silêncio.","exE":"We made the whole journey in silence.","note":"\"Em silêncio\" é a locução fixa; \"fazer silêncio\" é o pedido para calar. O circunflexo marca vogal fechada.","noteE":"Em silêncio is the fixed phrase; fazer silêncio is how you ask for quiet. The circumflex marks a closed vowel."},
  "o sinal": {"ipa":"see-NAHL","ex":"Ele fez-me sinal para entrar.","exE":"He signalled me to come in.","note":"Além de sinal/gesto, «sinal» é o depósito que se paga ao reservar algo: «dar um sinal». Plural: sinais.","noteE":"Besides sign or signal, 'sinal' is the deposit you pay to reserve something ('dar um sinal'). Plural: sinais."},
  "o sistema": {"ipa":"oo seesh-TAY-mah","ex":"O sistema está fora de serviço.","exE":"The system is out of order.","note":"É masculino apesar de terminar em -a, como todas as palavras de origem grega em -ema: o problema, o tema, o cinema.","noteE":"Masculine even though it ends in -a — like all the Greek-derived -ema words: o problema, o tema, o cinema. Never uma sistema."},
  "o sofá": {"ipa":"soo-FAH","ex":"Adormeci no sofá a ver o jogo.","exE":"I fell asleep on the couch watching the game.","note":"É masculino apesar de terminar em «á», e o plural é «sofás». O acento é obrigatório porque a sílaba tónica é a última.","noteE":"Masculine despite the final \"á\", plural \"sofás\". The accent is required because the stress falls on the last syllable."},
  "o sol": {"ipa":"sawl","ex":"Hoje está sol, vamos até à praia.","exE":"It's sunny today, let's go to the beach.","note":"«Está sol» é a forma normal de dizer que está de sol — sem adjetivo. «Apanhar sol» é apanhar banhos de sol; o «o» é aberto, como em «só».","noteE":"\"Está sol\" is the everyday way to say it's sunny, with no adjective. \"Apanhar sol\" is to sunbathe; the \"o\" is open, like in \"só\"."},
  "o som": {"ipa":"so (nasal)","ex":"Baixa o som da televisão, por favor.","exE":"Turn the TV volume down, please.","note":"No dia a dia «o som» é o volume ou a aparelhagem; «pôr o som mais alto» = aumentar o volume.","noteE":"In everyday speech 'o som' often means the volume or the stereo: 'pôr o som mais alto' = turn it up."},
  "o sonho": {"ipa":"SOH-nyoo","ex":"Tive um sonho muito estranho esta noite.","exE":"I had a very strange dream last night.","note":"Sonha-se «com» alguém: «sonhei contigo». Em Portugal, «sonhos» são também um doce frito de Natal.","noteE":"You dream 'com' someone: 'sonhei contigo'. In Portugal, 'sonhos' are also fried Christmas doughnuts."},
  "o sucesso": {"ipa":"soo-SEH-soo","ex":"A peça foi um grande sucesso.","exE":"The play was a great success.","note":"Cuidado: o verbo «suceder» significa acontecer ou vir a seguir, não «ter sucesso»; para isso diz-se «ter sucesso» ou «ser bem-sucedido».","noteE":"False friend alert: the verb 'suceder' means to happen or to follow, not to succeed. Use 'ter sucesso' or 'ser bem-sucedido'."},
  "o sul": {"ipa":"sool","ex":"No verão vamos sempre para o sul.","exE":"In summer we always head south.","note":"Para os portugueses \"o Sul\" é sobretudo o Algarve. Nota a diferença entre \"ir para o sul\" (deslocar-se) e \"ficar a sul de\" (estar situado).","noteE":"For Portuguese people \"o Sul\" mostly means the Algarve. Note the difference between \"ir para o sul\" (to travel) and \"ficar a sul de\" (to be located)."},
  "o século": {"ipa":"oo SEH-koo-loo","ex":"Esta igreja é do século XV.","exE":"This church is from the 15th century.","note":"Os séculos escrevem-se com numeração romana e lêem-se em ordinal até ao décimo: século III (terceiro), século XXI (vinte e um).","noteE":"Centuries take Roman numerals, read as ordinals up to the tenth and as cardinals after: século III is 'terceiro', século XXI is 'vinte e um'."},
  "o teatro": {"ipa":"tee-AH-troo","ex":"Ontem fomos ao teatro ver uma peça.","exE":"Yesterday we went to the theatre to see a play.","note":"Diz-se «ir ao teatro» e a obra representada é «a peça». «Fazer teatro» significa exagerar ou fingir emoções.","noteE":"You \"ir ao teatro\", and the work performed is \"a peça\". \"Fazer teatro\" means to be dramatic or put on an act."},
  "o telhado": {"ipa":"tuh-LYAH-doo","ex":"O telhado precisa de telhas novas.","exE":"The roof needs new tiles.","note":"Vem de «telha» e designa o telhado visto de fora, ao contrário de «teto». «Quem tem telhados de vidro não atira pedras» é o provérbio equivalente ao inglês.","noteE":"It comes from \"telha\" (roof tile) and means the roof from outside, unlike \"teto\". The glass-houses proverb exists here too."},
  "o tema": {"ipa":"TAY-mah","ex":"O tema da aula de hoje é a família.","exE":"Today's class topic is the family.","note":"Apesar de terminar em -a, «tema» é masculino: «este tema», «um tema difícil».","noteE":"Despite the -a ending, 'tema' is masculine (Greek origin, like 'problema', 'sistema'): 'este tema'."},
  "o tempo": {"ipa":"oo TEH (nasal)-poo","ex":"Não tenho tempo hoje.","exE":"I don't have time today.","note":"Significa 'tempo' e 'clima': 'o tempo está bom'.","noteE":"Means both 'time' and 'weather': 'o tempo está bom' = the weather's nice."},
  "o termo": {"ipa":"TAYR-moo","ex":"Não conheço esse termo técnico em português.","exE":"I don't know that technical term in Portuguese.","note":"Com o fechado é \"termo\" (a palavra ou o fim de algo); não confundas com \"térmico\", como em \"garrafa térmica\" (thermos). \"Em termos de\" é muito frequente.","noteE":"With a closed o it means a term or the end of something; don't confuse it with \"térmico\", as in \"garrafa térmica\" (thermos). \"Em termos de\" is very common."},
  "o território": {"ipa":"tuh-rree-TAW-ree-oo","ex":"O lobo defende o seu território.","exE":"The wolf defends its territory.","note":"O «ó» é aberto, como em «história»; muitos estrangeiros dizem erradamente «-tôrio».","noteE":"The ó is open (AW), as in 'história' — learners often close it wrongly to 'oh'."},
  "o teto": {"ipa":"TEH-too","ex":"Há uma mancha de humidade no teto.","exE":"There's a damp stain on the ceiling.","note":"É a superfície vista de dentro — o exterior é «o telhado». Escrevia-se «tecto» antes do Acordo Ortográfico; «teto máximo» é um limite.","noteE":"This is the surface seen from inside; the outside is \"o telhado\". It was spelled \"tecto\" before the reform, and \"teto máximo\" means a cap or limit."},
  "o texto": {"ipa":"TAYSH-too","ex":"Lê o texto e responde às perguntas.","exE":"Read the text and answer the questions.","note":"Falso amigo: uma mensagem de telemóvel não é \"um texto\" — diz-se \"uma mensagem\" ou \"um SMS\", e o verbo é \"mandar mensagem\", não \"textar\".","noteE":"False friend: a phone text is not \"um texto\" — say \"uma mensagem\" or \"um SMS\", and the verb is \"mandar mensagem\", not \"textar\"."},
  "o tio": {"ipa":"oo TEE-oo","ex":"O meu tio vive no Algarve.","exE":"My uncle lives in the Algarve.","note":"\"Os tios\" pode significar tio e tia juntos. Informalmente, \"ó tio\" é usado para chamar um homem desconhecido, mas soa rude com estranhos.","noteE":"Os tios can mean 'uncle and aunt' together. Informally ó tio is slangy for hailing a stranger, and it lands as rude — avoid it."},
  "o tipo": {"ipa":"oo TEE-poo","ex":"Que tipo de música é que ouves?","exE":"What kind of music do you listen to?","note":"Formalmente significa \"kind, sort\"; na gíria portuguesa \"o tipo\" é \"o gajo\" (bloke). Os jovens usam \"tipo\" como muleta, à maneira do \"like\" inglês.","noteE":"Formally 'kind, sort'; in Portuguese slang um tipo is 'a bloke'. Young speakers also drop tipo into sentences the way English uses 'like'."},
  "o tornozelo": {"ipa":"oo toor-noo-ZAY-loo","ex":"Torci o tornozelo na escada.","exE":"I twisted my ankle on the stairs.","note":"A colocação normal é \"torcer o tornozelo\". O \"z\" entre vogais mantém-se sonoro, ao contrário do \"s\" final que soa \"sh\".","noteE":"The standard collocation is torcer o tornozelo, 'to twist your ankle'. The z stays voiced between vowels."},
  "o trabalhador": {"ipa":"oo trah-bah-lyah-DOR","ex":"Os trabalhadores da fábrica fizeram greve.","exE":"The factory workers went on strike.","note":"Também é adjetivo e significa esforçado: \"ele é muito trabalhador\". O feminino é trabalhadora; \"trabalhador por conta própria\" é quem trabalha por conta própria.","noteE":"It is also an adjective meaning hardworking: ele é muito trabalhador. The feminine is trabalhadora, and trabalhador por conta própria means self-employed."},
  "o trabalho": {"ipa":"oo trah-BAH-lyoo","ex":"Vou para o trabalho.","exE":"I'm going to work.","note":"'Trabalho' = work/job; o verbo é 'trabalhar'.","noteE":"'Trabalho' = work/job; the verb is 'trabalhar'."},
  "o tribunal": {"ipa":"oo tree-boo-NAL","ex":"O caso vai a tribunal em setembro.","exE":"The case goes to court in September.","note":"\"Ir a tribunal\" é a expressão fixa, sem artigo. Corte, em português europeu, é a corte de um rei, não um tribunal.","noteE":"Ir a tribunal is the fixed phrase, with no article. Corte in European Portuguese means a royal court, not a courtroom."},
  "o título": {"ipa":"TEE-too-loo","ex":"Ainda não escolhi o título do trabalho.","exE":"I still haven't chosen the title of the paper.","note":"«A título de exemplo» significa «por exemplo» e é muito comum na escrita formal. No plural, «títulos» também são valores mobiliários.","noteE":"\"A título de exemplo\" means \"by way of example\" and is common in formal writing. In the plural, \"títulos\" can also mean securities."},
  "o uso": {"ipa":"oo OO-zoo","ex":"O uso do telemóvel é proibido aqui.","exE":"Using a mobile phone is forbidden here.","note":"O s lê-se z. \"Fazer uso de\" é formal; na conversa usa-se simplesmente o verbo usar.","noteE":"The s sounds like z. Fazer uso de is formal; in conversation people just use the verb usar."},
  "o vale": {"ipa":"VAH-luh","ex":"Recebi um vale de desconto no supermercado.","exE":"I got a discount voucher at the supermarket.","note":"Mesma forma para o vale entre montanhas, o vale de compras e o verbo «valer»: «vale a pena».","noteE":"Same form for a valley, a voucher, and the verb valer ('vale a pena' = it's worth it)."},
  "o valor": {"ipa":"oo vah-LOR","ex":"O valor total é vinte euros.","exE":"The total amount is twenty euros.","note":"Cobre o preço concreto e o valor moral (\"os valores da família\"). Para perguntar o preço, o normal é \"Quanto custa?\" e não \"Qual é o valor?\".","noteE":"Covers a monetary amount and moral values alike. To ask a price, though, say Quanto custa? — Qual é o valor? sounds bureaucratic."},
  "o vento": {"ipa":"VEH (nasal)-too","ex":"Hoje está muito vento na praia.","exE":"It's very windy at the beach today.","note":"Para dizer \"it's windy\" usa-se o substantivo: \"está muito vento\". Dizer \"está ventoso\" soa a boletim meteorológico e é raro na conversa.","noteE":"To say \"it's windy\" you use the noun: \"está muito vento\". Saying \"está ventoso\" sounds like a weather bulletin and is rare in speech."},
  "o voto": {"ipa":"VOH-too","ex":"O meu voto é secreto.","exE":"My vote is secret.","note":"Também significa desejo: «votos de felicidades». Vota-se «em» alguém, não «para».","noteE":"It also means a wish ('votos de felicidades'). You vote 'em' someone — votar em, not votar para."},
  "o órgão": {"ipa":"AWR-gown (nasal)","ex":"O coração é um órgão vital.","exE":"The heart is a vital organ.","note":"Palavra rara com duas nasais e acento na primeira sílaba; plural «os órgãos». Também significa entidade oficial: «órgão de comunicação social».","noteE":"Unusual word with two nasals and stress on the first syllable; plural 'os órgãos'. Also means an official body, as in 'órgão de comunicação social'."},
  "o/a artista": {"ipa":"oo/ah ar-TISH-tah","ex":"Aquela artista expõe no Porto.","exE":"That artist is exhibiting in Porto.","note":"Como todos os nomes em -ista, a forma serve para os dois géneros e só o artigo muda. Nas artes visuais diz-se \"artista plástico\".","noteE":"Like all -ista nouns, one form serves both genders and only the article changes. In the visual arts you say artista plástico."},
  "o/a chefe": {"ipa":"oo/ah SHEH-fuh","ex":"A minha chefe é muito compreensiva.","exE":"My boss is very understanding.","note":"A forma não muda com o género: só muda o artigo, o chefe ou a chefe. O cozinheiro principal de um restaurante é \"o chef\", palavra francesa.","noteE":"The form does not change for gender; only the article does, o chefe or a chefe. A restaurant chef is o chef, borrowed from French."},
  "o/a líder": {"ipa":"LEE-dehr","ex":"Ela é a líder da equipa desde janeiro.","exE":"She has been the team leader since January.","note":"A forma não muda com o género — só o artigo: «o líder», «a líder». O plural é «os líderes» e o verbo correspondente é «liderar».","noteE":"The word itself doesn't change for gender; only the article does: \"o líder\", \"a líder\". Plural \"os líderes\", verb \"liderar\"."},
  "o/a poeta": {"ipa":"poo-EH-tah","ex":"O poeta vai ler os seus versos hoje.","exE":"The poet is going to read his verses today.","note":"A forma tradicional feminina é «a poetisa», mas «a poeta» é hoje comum e preferida por muitas autoras.","noteE":"The traditional feminine is 'a poetisa', but 'a poeta' is now common and preferred by many women writers."},
  "o/a presidente": {"ipa":"pruh-zee-DEH (nasal)-tuh","ex":"A presidente da câmara falou na televisão.","exE":"The mayor spoke on television.","note":"A forma não muda: só o artigo marca o género, \"o presidente\" / \"a presidente\". \"Presidente da câmara\" é o mayor de uma cidade portuguesa.","noteE":"The word itself doesn't change: only the article marks gender, \"o presidente\" / \"a presidente\". \"Presidente da câmara\" is a Portuguese town's mayor."},
  "obrigada": {"ipa":"oo-bree-GAH-dah","ex":"Obrigada, é muito simpático.","exE":"Thank you, that's very kind.","note":"Forma feminina — dita por mulheres, seja com quem for.","noteE":"The feminine form — said by women, whoever they're speaking to."},
  "obrigado": {"ipa":"oo-bree-GAH-doo","ex":"Obrigado pela ajuda.","exE":"Thank you for the help.","note":"Concorda com quem fala: um homem diz 'obrigado', uma mulher 'obrigada'.","noteE":"Agrees with the speaker: a man says 'obrigado', a woman 'obrigada'."},
  "obrigar": {"ipa":"oo-bree-GAR","ex":"Ninguém te obriga a ir.","exE":"Nobody is forcing you to go.","note":"Pede «a» antes do infinitivo: obrigar alguém a fazer algo. «Ser obrigado a» é a forma passiva mais usada.","noteE":"It takes a before an infinitive: obrigar alguém a fazer algo. Ser obrigado a is the usual passive form."},
  "observar": {"ipa":"ohb-suhr-VAR","ex":"Fiquei a observar as pessoas na praça.","exE":"I stood watching the people in the square.","note":"É mais atento e formal do que «ver». Também significa fazer um comentário: «observou que estava tarde».","noteE":"More attentive and formal than ver. It can also mean to remark: observou que estava tarde."},
  "obter": {"ipa":"ob-TEHR","ex":"É difícil obter um visto de trabalho.","exE":"It's hard to get a work visa.","note":"Conjuga-se como «ter»: obtenho, obténs, obtém, obtive. É mais formal do que «conseguir», que se usa no dia a dia.","noteE":"It conjugates like ter (obtenho, obtém, obtive) and is fairly formal; in everyday speech people say conseguir instead."},
  "ocorrer": {"ipa":"oo-koo-RREHR","ex":"O acidente ocorreu perto da ponte.","exE":"The accident happened near the bridge.","note":"Mais formal do que acontecer e frequente em notícias. Com pronome significa vir à ideia: ocorreu-me uma solução.","noteE":"More formal than acontecer and common in news reports. With a pronoun it means to come to mind: ocorreu-me uma solução."},
  "ocupado": {"ipa":"oh-koo-PAH-doo","ex":"Hoje estou muito ocupada no trabalho.","exE":"Today I am very busy at work.","note":"Usa-se com \"estar\" para pessoas e para lugares ou linhas telefónicas. Concorda: ocupada, ocupados, ocupadas.","noteE":"Use it with \"estar\" for people and also for seats or phone lines. It agrees: ocupada, ocupados, ocupadas."},
  "ocupar": {"ipa":"oo-koo-PAR","ex":"Este sofá ocupa muito espaço.","exE":"This sofa takes up a lot of space.","note":"«Ocupar-se de» é tratar de algo. O adjetivo «ocupado» serve para pessoas atarefadas e para lugares já tomados.","noteE":"Ocupar-se de means to deal with something. The adjective ocupado covers both busy people and taken seats."},
  "oferecer": {"ipa":"oo-fuh-ruh-SEHR","ex":"Ofereci-lhe um livro pelos anos.","exE":"I gave her a book for her birthday.","note":"Em Portugal significa sobretudo dar uma prenda, não só propor algo. O «c» passa a «ç»: ofereço, ofereça.","noteE":"In Portugal it mainly means to give a present, not just to propose something. The c becomes ç: ofereço, ofereça."},
  "olhar": {"ipa":"oo-LYAR","ex":"Olha para aquele quadro.","exE":"Look at that painting.","note":"Pede sempre para antes do que se observa, ao contrário de ver, que é direto. Olha! sozinho funciona como um marcador de conversa, tipo escuta.","noteE":"It always takes para before what you look at, unlike ver, which is direct. Olha! on its own works as a conversational marker, like listen."},
  "olá": {"ipa":"o-LAH","ex":"Olá! Está tudo bem?","exE":"Hi! Is everything okay?","note":"A saudação mais neutra — serve para qualquer hora do dia.","noteE":"The most neutral greeting — it works at any time of day."},
  "onde?": {"ipa":"ON (nasal)-duh","ex":"Onde é que fica a casa de banho?","exE":"Where is the bathroom?","note":"\"Onde\" indica lugar sem movimento; com verbos de movimento usa-se \"aonde\" (Aonde vais?) e para origem \"de onde/donde\".","noteE":"Onde is for static location; with verbs of motion use aonde, and for origin de onde or donde."},
  "ontem": {"ipa":"ON (nasal)-teh (nasal)","ex":"Ontem à noite fiquei em casa.","exE":"Last night I stayed at home.","note":"Pede o pretérito perfeito simples (fui, comi). \"Anteontem\" é o dia antes de ontem.","noteE":"It calls for the simple past tense, and anteontem covers the day before yesterday."},
  "orgulhoso": {"ipa":"or-goo-LYOH-zoo","ex":"Estou muito orgulhoso de ti.","exE":"I am very proud of you.","note":"Pede a preposição \"de\" e vai com \"estar\" para o sentido positivo. Com \"ser\" pode significar arrogante, e concorda: orgulhosa, orgulhosos.","noteE":"It takes the preposition \"de\" and goes with \"estar\" for the positive sense. With \"ser\" it can mean arrogant, and it agrees: orgulhosa, orgulhosos."},
  "os": {"ipa":"oosh","ex":"Os miúdos estão a brincar na rua.","exE":"The kids are playing in the street.","note":"O plural masculino cobre grupos mistos: \"os pais\" pode ser \"os progenitores\" e não só vários homens.","noteE":"The masculine plural covers mixed groups, so os pais usually means 'the parents' (mother and father), not 'the fathers'."},
  "os calções": {"ipa":"kahl-SOYNSH (nasal)","ex":"No verão ando sempre de calções.","exE":"In summer I always wear shorts.","note":"Também só se usa no plural. «Calções de banho» são os calções de praia; no Brasil diria-se «shorts», forma pouco usada em Portugal.","noteE":"Plural only as well. \"Calções de banho\" are swimming trunks; Brazil says \"shorts\", which is rarer in Portugal."},
  "os sapatos": {"ipa":"sah-PAH-toosh","ex":"Estes sapatos são muito confortáveis.","exE":"These shoes are very comfortable.","note":"Refere sobretudo o sapato fechado, de vestir; os desportivos são «os ténis» e as sandálias «as sandálias». O verbo é «calçar», não «vestir».","noteE":"It suggests proper closed shoes; trainers are \"os ténis\" and sandals \"as sandálias\". The verb is \"calçar\", not \"vestir\"."},
  "ou": {"ipa":"oh","ex":"Queres chá ou café?","exE":"Do you want tea or coffee?","note":"Liga alternativas e leva indicativo. Repetido (\"ou... ou...\") torna a escolha exclusiva, e \"ou seja\" serve para reformular.","noteE":"It links alternatives and takes the indicative. Doubled as ou... ou... it makes the choice exclusive, and ou seja means that is."},
  "ouvir": {"ipa":"oh-VEER","ex":"Ouves música?","exE":"Do you listen to music?","note":"Ouvir = to hear/listen; irregular: 'ouço, ouves'.","noteE":"Ouvir = to hear/listen; irregular: 'ouço, ouves'."},
  "ou… ou…": {"ipa":"oh ... oh","ex":"Ou vamos agora ou não vamos de todo.","exE":"Either we go now or we don't go at all.","note":"Marca alternativas exclusivas, uma ou outra, e leva indicativo nas duas orações. Com sujeitos diferentes, o verbo concorda com o mais próximo.","noteE":"It marks exclusive alternatives and takes the indicative in both clauses. With different subjects the verb agrees with the nearest one."},
  "pagar": {"ipa":"pah-GAR","ex":"Posso pagar com multibanco?","exE":"Can I pay by debit card?","note":"Paga-se algo a alguém: paguei a conta ao empregado. O g leva u antes de e: paguei, pague.","noteE":"You pagar something a someone: paguei a conta ao empregado. The g takes a u before e: paguei, pague."},
  "para": {"ipa":"PAH-rah","ex":"Este presente é para a tua mãe.","exE":"This present is for your mother.","note":"Na fala corrente diz-se \"pra\" e \"prò\", embora se escreva \"para\". Seguido de infinitivo exprime finalidade: estudo para aprender.","noteE":"In everyday speech it is squashed to pra (and para o becomes prò), though you still write para. Before an infinitive it means 'in order to'."},
  "parar": {"ipa":"pah-RAR","ex":"O autocarro para aqui em frente.","exE":"The bus stops right here in front.","note":"Antes de outro verbo leva «de»: parar de fumar, parar de chover. «Sem parar» significa continuamente.","noteE":"Before another verb it takes de: parar de fumar. Sem parar means non-stop."},
  "parecer": {"ipa":"pah-ruh-SEHR","ex":"Parece que vai chover hoje.","exE":"It looks like it's going to rain today.","note":"Parecer-se com significa ser fisicamente semelhante: pareces-te com o teu pai. Na negativa, não parece que pede conjuntivo.","noteE":"Parecer-se com means to physically resemble: pareces-te com o teu pai. In the negative, não parece que takes the subjunctive."},
  "participar": {"ipa":"par-tee-see-PAR","ex":"Ela participou no concurso de fotografia.","exE":"She took part in the photography competition.","note":"Em português europeu pede «em»: participar numa reunião, num projeto. Nunca se diz «participar de».","noteE":"In European Portuguese it takes em: participar numa reunião. Participar de is Brazilian."},
  "partir": {"ipa":"par-TEER","ex":"Partimos de manhã cedo.","exE":"We're leaving early in the morning.","note":"Tem dois sentidos: ir embora e quebrar (parti um copo). A expressão a partir de significa a contar de determinada data.","noteE":"It has two senses: to depart and to break (parti um copo, I broke a glass). The set phrase a partir de means from a given date onwards."},
  "passar": {"ipa":"pah-SAR","ex":"Passámos o fim de semana na praia.","exE":"We spent the weekend at the beach.","note":"Pede por para lugares (passar pela ponte) e por a para mudanças (passar a ser). Passar-se significa acontecer: o que se passa?","noteE":"It takes por for places (passar pela ponte, to go over the bridge) and a for changes (passar a ser, to become). Reflexive passar-se means to happen: o que se passa?"},
  "pedir": {"ipa":"puh-DEER","ex":"Pedi um café ao empregado.","exE":"I ordered a coffee from the waiter.","note":"Pede-se algo a alguém, com a onde o inglês usa from. Irregular na primeira pessoa: eu peço. Não confundir com perguntar, que é fazer uma pergunta.","noteE":"You pedir something a someone, using a where English says from. Irregular in the first person: eu peço. Don't confuse it with perguntar, which is to ask a question."},
  "pegar": {"ipa":"puh-GAR","ex":"Pega no saco, por favor.","exE":"Pick up the bag, please.","note":"Em Portugal pede «em»: pegar num livro. Para transportes ou constipações usa-se «apanhar», não «pegar» como no Brasil.","noteE":"In Portugal it takes em: pegar num livro. For transport or catching a cold you use apanhar, unlike Brazilian usage."},
  "pensar": {"ipa":"peh (nasal)-SAR","ex":"Estou a pensar em mudar de casa.","exE":"I'm thinking of moving house.","note":"Pensar em é ter algo na cabeça; pensar de é ter uma opinião (o que pensas dele?). Seguido de infinitivo sem preposição significa tencionar.","noteE":"Pensar em is to have something on your mind; pensar de is to hold an opinion (o que pensas dele?). Followed by a bare infinitive it means to intend."},
  "pequeno": {"ipa":"puh-KEH-noo","ex":"Um café pequeno.","exE":"A small coffee.","note":"Feminino 'pequena'; 'pequeno-almoço' = breakfast (em Portugal).","noteE":"Feminine 'pequena'; 'pequeno-almoço' = breakfast (in Portugal)."},
  "perceber": {"ipa":"puhr-suh-BEHR","ex":"Desculpa, não percebi o que disseste.","exE":"Sorry, I didn't catch what you said.","note":"Falso amigo: em Portugal significa compreender, e não notar. É muito mais frequente do que entender, que domina no Brasil. Perceber de significa saber muito de um assunto.","noteE":"A false friend: in Portugal it means to understand, not to perceive. It is far more common than entender, which dominates in Brazil. Perceber de means to know a lot about a subject."},
  "perder": {"ipa":"puhr-DEHR","ex":"Perdi o autocarro das oito.","exE":"I missed the eight o'clock bus.","note":"Irregular só na primeira pessoa do presente: eu perco. Usa-se também para falhar transportes e horários, onde o inglês diz miss.","noteE":"Irregular only in the first person present: eu perco. It is also the verb for missing transport and appointments, where English says miss."},
  "perguntar": {"ipa":"puhr-goo (nasal)-TAR","ex":"Perguntei-lhe as horas.","exE":"I asked him the time.","note":"Pergunta-se a alguém por algo ou sobre algo. Distingue-se de pedir, que é solicitar uma coisa e não uma informação.","noteE":"You perguntar a someone por or sobre something. It differs from pedir, which is to request a thing rather than information."},
  "permanecer": {"ipa":"puhr-mah-nuh-SEHR","ex":"O tempo permaneceu igual toda a semana.","exE":"The weather stayed the same all week.","note":"Mais formal do que «ficar». O «c» passa a «ç» antes de «a» e «o»: permaneço, permaneça.","noteE":"More formal than ficar. The c becomes ç before a and o: permaneço, permaneça."},
  "permitir": {"ipa":"puhr-mee-TEER","ex":"Não permitem cães no restaurante.","exE":"They don't allow dogs in the restaurant.","note":"Permite-se algo a alguém, ou permitir que mais conjuntivo: permitiram que ficássemos. Deixar é a alternativa corrente na fala.","noteE":"You permitir something a someone, or use permitir que plus the subjunctive: permitiram que ficássemos. Deixar is the everyday spoken alternative."},
  "pertencer": {"ipa":"puhr-teh (nasal)-SEHR","ex":"Este livro pertence à minha irmã.","exE":"This book belongs to my sister.","note":"Pede sempre a preposição a, com contração (pertence ao João, pertence à empresa); nunca se usa com de. Leva cedilha antes de a/o: eu pertenço.","noteE":"Always takes a, contracted with the article (pertence ao João, pertence à empresa) — never de. Cedilla before a/o: eu pertenço."},
  "perto": {"ipa":"PEHR-too","ex":"A padaria fica perto de minha casa.","exE":"The bakery is near my house.","note":"É invariável e pede sempre \"de\" antes do lugar: perto do metro. Para a forma adjetiva use \"próximo\", que concorda: a estação mais próxima.","noteE":"It is invariable and always takes \"de\" before the place: perto do metro. For a true adjective use \"próximo\", which agrees: a estação mais próxima."},
  "pesado": {"ipa":"puh-ZAH-doo","ex":"Este saco é demasiado pesado para mim.","exE":"This bag is too heavy for me.","note":"Vem depois do nome e concorda: pesada, pesados, pesadas. Também descreve refeições difíceis de digerir: um almoço pesado.","noteE":"It follows the noun and agrees: pesada, pesados, pesadas. It also describes meals that are hard to digest: um almoço pesado."},
  "pesar": {"ipa":"puh-ZAR","ex":"Este saco pesa demasiado.","exE":"This bag weighs too much.","note":"Intransitivo (pesa dois quilos) e transitivo (pesar a fruta). Como nome, o pesar significa tristeza — daí a locução apesar de.","noteE":"Intransitive (pesa dois quilos) and transitive (pesar a fruta). As a noun, o pesar means sorrow — which is where the phrase apesar de comes from."},
  "pior": {"ipa":"pee-AWR","ex":"Hoje está pior do que ontem.","exE":"Today it's worse than yesterday.","note":"Comparativo irregular de mau e de mal: nunca se diz «mais mau». Não varia em género (só no plural, piores) e vem antes do nome no superlativo (o pior dia); com estar exprime um estado passageiro, com ser uma característica.","noteE":"Irregular comparative of mau and mal — never 'mais mau'. It has one form for both genders (only the plural piores changes) and goes before the noun in the superlative (o pior dia); with estar it is a passing state, with ser a lasting trait."},
  "pobre": {"ipa":"PAW-bruh","ex":"Ele vem de uma família pobre.","exE":"He comes from a poor family.","note":"Forma única nos dois géneros, plural \"pobres\". Depois do nome significa sem dinheiro; antes do nome exprime pena: o pobre homem.","noteE":"One form for both genders, plural \"pobres\". After the noun it means without money; before the noun it expresses pity: o pobre homem."},
  "poder": {"ipa":"poo-DER","ex":"Posso entrar?","exE":"May I come in?","note":"'Posso?' = may I? — pedido educado do dia a dia.","noteE":"'Posso?' = may I? — an everyday polite request."},
  "pois": {"ipa":"poysh","ex":"Vamos de táxi, pois já é tarde.","exE":"Let's take a taxi, since it's already late.","note":"Como conjunção causal é formal e nunca abre a frase, vindo sempre depois da oração principal, com indicativo. Na fala portuguesa \"pois\" e \"pois é\" exprimem concordância.","noteE":"As a causal conjunction it is formal and never opens the sentence, always following the main clause with the indicative. In speech pois and pois é signal agreement."},
  "por": {"ipa":"poor","ex":"Passei por tua casa ontem à noite.","exE":"I went past your house last night.","note":"\"Por\" indica causa, meio ou trajeto (obrigado por tudo, por comboio); \"para\" indica destino ou finalidade. Contrai com o artigo: pelo, pela, pelos, pelas.","noteE":"The classic trap is por vs para: por is cause, means or route (por comboio, obrigado por isso), para is destination or purpose. Note it contracts into pelo/pela."},
  "porque": {"ipa":"poor-KUH","ex":"Fiquei em casa porque estava a chover.","exE":"I stayed home because it was raining.","note":"Escreve-se numa palavra e sem acento, introduz a causa e leva indicativo. A oração vem depois da principal; para perguntar usa-se \"porquê?\" ou \"porque é que...?\".","noteE":"Written as one unaccented word, it introduces a cause with the indicative. Its clause follows the main one; questions use porquê or porque é que."},
  "porquê?": {"ipa":"poor-KAY","ex":"Não vieste ontem, porquê?","exE":"You didn't come yesterday, why?","note":"Com acento usa-se sozinho ou no fim da frase. No início da pergunta diz-se \"Porque é que...?\" e a resposta começa por \"porque\", sem acento.","noteE":"The accented form stands alone or ends a question. To open a question use \"Porque é que...?\", and answer with unaccented \"porque\"."},
  "portanto / por isso": {"ipa":"poor-TAN (nasal)-too / poor EE-soo","ex":"Perdi o comboio, portanto cheguei tarde.","exE":"I missed the train, so I arrived late.","note":"Introduzem a consequência, no início da segunda oração e com indicativo. \"Por isso\" é o mais corrente na fala; \"portanto\" é ligeiramente mais formal.","noteE":"Both introduce a consequence, opening the second clause with the indicative. Por isso is the everyday spoken choice; portanto is slightly more formal."},
  "possuir": {"ipa":"poo-soo-EER","ex":"A família possui uma quinta no Alentejo.","exE":"The family owns a farm in the Alentejo.","note":"Registo formal, próprio de documentos; na fala normal diz-se ter. Conjuga-se como incluir: possuo, possuis, possui.","noteE":"Formal register, typical of documents; ordinary speech uses ter. It conjugates like incluir: possuo, possuis, possui."},
  "pouco": {"ipa":"POH-koo","ex":"Ele fala pouco nas reuniões.","exE":"He speaks little in meetings.","note":"Advérbio invariável depois do verbo; como determinante concorda (poucas pessoas). \"Um pouco de\" significa uma pequena quantidade e \"há pouco\" quer dizer há bocado.","noteE":"As an adverb after the verb it is invariable, but as a determiner it agrees. Um pouco de means a bit of, and há pouco means a moment ago."},
  "precisar": {"ipa":"pruh-see-ZAR","ex":"Preciso de ir à farmácia.","exE":"I need to go to the chemist.","note":"Em Portugal leva de tanto antes de nome como de infinitivo: preciso de ajuda, preciso de sair. Omitir o de é traço brasileiro.","noteE":"In Portugal it takes de before both nouns and infinitives: preciso de ajuda, preciso de sair. Dropping the de is a Brazilian trait."},
  "preferir": {"ipa":"pruh-fuh-REER","ex":"Prefiro chá a café.","exE":"I prefer tea to coffee.","note":"Alternância vocálica no presente: eu prefiro, tu preferes, eles preferem. Prefere-se uma coisa A outra — «do que» é evitado na norma.","noteE":"Vowel change in the present: eu prefiro, tu preferes, eles preferem. You prefer one thing A another — 'do que' is avoided in careful Portuguese."},
  "preparar": {"ipa":"pruh-pah-RAR","ex":"Estou a preparar o jantar.","exE":"I'm making dinner.","note":"«Preparar-se para» é aprontar-se para algo. Note o «para» e não «a» depois da forma reflexa.","noteE":"Preparar-se para means to get ready for something; note that it takes para, not a."},
  "pretender": {"ipa":"pruh-teh (nasal)-DEHR","ex":"Pretendo mudar de emprego este ano.","exE":"I intend to change jobs this year.","note":"Falso amigo: não significa fingir, que se diz «fingir». Liga-se diretamente ao infinitivo, sem preposição.","noteE":"A false friend: it does not mean to pretend (that is fingir). It links straight to an infinitive with no preposition."},
  "preto / negro": {"ipa":"PRAY-too / NEH-groo","ex":"Comprei um casaco preto para o inverno.","exE":"I bought a black coat for the winter.","note":"Para objetos e roupa diz-se \"preto\"; \"negro\" é mais literário e usa-se para pessoas. Ambos concordam: preta, pretos, negras.","noteE":"For objects and clothes say \"preto\"; \"negro\" is more literary and is the word used for people. Both agree: preta, pretos, negras."},
  "prever": {"ipa":"pruh-VEHR","ex":"Preveem chuva para o fim de semana.","exE":"They're forecasting rain for the weekend.","note":"Conjuga-se como «ver» no presente: prevejo, prevês, prevê. No pretérito, porém, faz previ, previu, com «i».","noteE":"Present tense follows ver: prevejo, prevês, prevê. The past, however, is previ, previu with an i."},
  "primeiro": {"ipa":"pree-MAY-roo","ex":"Apanhámos o primeiro comboio da manhã.","exE":"We took the first train of the morning.","note":"Como os outros ordinais, vem antes do nome e concorda: primeira, primeiros, primeiras. Também serve de advérbio: primeiro comemos, depois saímos.","noteE":"Like the other ordinals it comes before the noun and agrees: primeira, primeiros, primeiras. It also works as an adverb: primeiro comemos, depois saímos."},
  "principalmente": {"ipa":"pree (nasal)-see-pahl-MEH (nasal)-tuh","ex":"Vou à praia, principalmente no verão.","exE":"I go to the beach, mainly in summer.","note":"Os adjetivos terminados em consoante, como \"principal\", juntam -mente sem mudar de forma. É praticamente sinónimo de \"sobretudo\".","noteE":"Adjectives ending in a consonant, like principal, simply add -mente. It is virtually interchangeable with sobretudo."},
  "procurar": {"ipa":"proo-koo-RAR","ex":"Procuro a casa de banho.","exE":"I'm looking for the toilet.","note":"Liga-se diretamente ao objeto, sem por: procuro as chaves. Seguido de infinitivo significa esforçar-se por: procura chegar a horas.","noteE":"It links straight to its object, with no por: procuro as chaves. Followed by an infinitive it means to strive to: procura chegar a horas."},
  "produzir": {"ipa":"proo-doo-ZEER","ex":"Esta região produz um vinho excelente.","exE":"This region produces excellent wine.","note":"Como os verbos em -uzir, perde o e final na terceira pessoa: ele produz, não produze. O mesmo se passa com conduzir e traduzir.","noteE":"Like other -uzir verbs, it drops the final e in the third person: ele produz, not produze. The same happens with conduzir and traduzir."},
  "prometer": {"ipa":"proo-muh-TEHR","ex":"Prometeste-me que vinhas.","exE":"You promised me you'd come.","note":"Prometer algo a alguém, com o pronome indireto enclítico (prometeste-me, prometo-lhe). Regular em -er, com e fechado no radical.","noteE":"Prometer something a someone, with the indirect pronoun attached (prometeste-me, prometo-lhe). A regular -er verb with a closed e in the stem."},
  "promover": {"ipa":"proo-moo-VEHR","ex":"A câmara promoveu um concerto gratuito.","exE":"The council put on a free concert.","note":"Promover alguém a um cargo (foi promovido a chefe) e promover um evento, no sentido de organizar ou divulgar. Regular em -er.","noteE":"Promover someone a a post (foi promovido a chefe), and promover an event, meaning to organise or publicise it. Regular -er verb."},
  "propor": {"ipa":"proo-POHR","ex":"Proponho que jantemos fora.","exE":"I suggest we eat out.","note":"Composto de pôr: eu proponho, ele propõe, pretérito propus. Propor que exige conjuntivo (que jantemos); propor-se a + infinitivo é comprometer-se.","noteE":"A compound of pôr: eu proponho, ele propõe, past propus. Propor que requires the subjunctive (que jantemos); propor-se a + infinitive means to set out to do something."},
  "próprio": {"ipa":"PRAW-pree-oo","ex":"Ela tem o seu próprio carro.","exE":"She has her own car.","note":"Vem antes do nome com um possessivo: a minha própria casa. Depois do nome ou do pronome reforça: o próprio presidente veio.","noteE":"It goes before the noun together with a possessive: a minha própria casa. After a noun or pronoun it emphasises: o próprio presidente veio."},
  "publicar": {"ipa":"poo-blee-KAR","ex":"Ela publicou o primeiro livro aos trinta.","exE":"She published her first book at thirty.","note":"Antes de «e» escreve-se «qu»: publiquei, publique. Também se usa para redes sociais: publicar uma foto.","noteE":"Spelling changes to qu before e: publiquei, publique. It is also used for social media: publicar uma foto."},
  "péssimo": {"ipa":"PEH-see-moo","ex":"O tempo esteve péssimo o fim de semana todo.","exE":"The weather was awful all weekend.","note":"É o superlativo de \"mau\" e o oposto de \"ótimo\"; dispensa \"muito\". Normalmente vem depois do nome ou com ser/estar.","noteE":"It is the superlative of \"mau\" and the opposite of \"ótimo\"; no \"muito\" needed. It usually follows the noun or comes after ser/estar."},
  "pôr": {"ipa":"por","ex":"Põe a mesa, por favor.","exE":"Set the table, please.","note":"Leva acento circunflexo para o distinguir de 'por' (by/for). Irregular.","noteE":"Written with a circumflex (pôr) to tell it apart from 'por' (by/for). Irregular."},
  "qualquer": {"ipa":"kwal-KEHR","ex":"Qualquer autocarro serve.","exE":"Any bus will do.","note":"Não muda com o género, mas tem um plural irregular no meio da palavra: quaisquer. Depois do substantivo pode significar insignificante: um homem qualquer.","noteE":"It does not change for gender, but has an irregular plural formed inside the word: quaisquer. After the noun it can mean unremarkable: um homem qualquer, some man or other."},
  "quando": {"ipa":"KWAN (nasal)-doo","ex":"Quando chegares, manda uma mensagem.","exE":"When you arrive, send a message.","note":"Se se refere ao futuro, pede o futuro do conjuntivo (quando puderes, quando fores). Para factos passados ou habituais usa-se o indicativo.","noteE":"Referring to the future it requires the future subjunctive, as in quando puderes. For past or habitual facts the indicative is used."},
  "quando?": {"ipa":"KWAN (nasal)-doo","ex":"Quando é que chega o comboio?","exE":"When does the train arrive?","note":"Na pergunta aparece normalmente com \"é que\". Não confundir com a conjunção \"quando\", que liga duas orações.","noteE":"As a question word it usually appears with \"é que\". Do not confuse it with the conjunction quando, which joins two clauses."},
  "quanto": {"ipa":"KWAN (nasal)-too","ex":"Quanto custa este bilhete?","exE":"How much does this ticket cost?","note":"Como determinante concorda com o nome: quantos livros, quantas horas. \"Quanto a\" significa no que diz respeito a.","noteE":"As a determiner it agrees with the noun, giving quantos livros and quantas horas. Quanto a means as for."},
  "quanto mais… mais/menos…": {"ipa":"KWAN (nasal)-too mysh ... mysh / MAY-noosh","ex":"Quanto mais estudo, mais aprendo.","exE":"The more I study, the more I learn.","note":"Estrutura correlativa com vírgula a separar as duas partes; se for facto, ambas vão no indicativo. Se apontar para o futuro, a primeira leva futuro do conjuntivo: quanto mais treinares, melhor jogas.","noteE":"It is a correlative structure with a comma between the halves, both indicative when stating a fact. Pointing to the future, the first clause takes the future subjunctive."},
  "quase": {"ipa":"KWAH-zuh","ex":"Estou quase pronto para sair.","exE":"I'm almost ready to go out.","note":"É invariável e vem imediatamente antes do que modifica. Em \"quase nunca\" e \"quase nada\" não se acrescenta \"não\" antes do verbo.","noteE":"It is invariable and sits right before what it modifies. In quase nunca and quase nada no extra não is needed before the verb."},
  "que": {"ipa":"kuh","ex":"Acho que ele já saiu.","exE":"I think he has already left.","note":"Introduz a oração subordinada e nunca se omite, ao contrário do \"that\" inglês. Depois de verbos de dúvida, desejo ou emoção pede o conjuntivo: espero que venhas.","noteE":"It introduces the subordinate clause and can never be dropped, unlike English that. After verbs of doubt, wish or emotion it triggers the subjunctive."},
  "quente": {"ipa":"KEH (nasal)-tuh","ex":"O café ainda está quente.","exE":"The coffee is still hot.","note":"Tem forma única para os dois géneros, plural \"quentes\". Para a sensação da pessoa usa-se \"ter calor\", nunca \"estar quente\", que soa estranho.","noteE":"It has a single form for both genders, plural \"quentes\". For how a person feels use \"ter calor\", never \"estar quente\", which sounds odd."},
  "querer": {"ipa":"kuh-RER","ex":"Quero um café, por favor.","exE":"I want a coffee, please.","note":"'Queria…' (imperfeito) soa mais educado: 'queria um café'.","noteE":"'Queria…' (imperfect) sounds more polite: 'I'd like a coffee'."},
  "rapidamente": {"ipa":"rrah-pee-dah-MEH (nasal)-tuh","ex":"Ele resolveu o problema rapidamente.","exE":"He solved the problem quickly.","note":"Formado por rápida + -mente, com a sílaba tónica em -MEN-. Na conversa é muito mais comum \"depressa\".","noteE":"It is built from the feminine rápida plus -mente, with the stress on -MEN-. In conversation depressa is much more common."},
  "realizar": {"ipa":"rree-ah-lee-ZAR","ex":"Ela realizou o seu primeiro filme.","exE":"She directed her first film.","note":"Falso amigo: não significa aperceber-se de algo, que se diz perceber ou dar-se conta. Em Portugal, o realizador é quem dirige um filme.","noteE":"A false friend: it does not mean to realise something, which is perceber or dar-se conta. In Portugal o realizador is the film director."},
  "realmente": {"ipa":"rree-ahl-MEH (nasal)-tuh","ex":"Isto é realmente muito caro.","exE":"This is really very expensive.","note":"Reforça a verdade da afirmação e pode vir antes do adjetivo ou no fim da frase. Sinónimos próximos: \"na verdade\" e \"mesmo\".","noteE":"It strengthens the truth of a statement and can sit before the adjective or at the end. Close alternatives are na verdade and mesmo."},
  "receber": {"ipa":"rruh-suh-BEHR","ex":"Recebi uma carta do banco.","exE":"I received a letter from the bank.","note":"Regular, mas com o e da raiz aberto nas formas tónicas: recebo, recebes. Também significa acolher visitas em casa.","noteE":"Regular, but the stem e is open in the stressed forms: recebo, recebes. It also means to have guests over."},
  "reconhecer": {"ipa":"rruh-koo-nyuh-SEHR","ex":"Não te reconheci com esse casaco.","exE":"I didn't recognise you in that coat.","note":"O «c» passa a «ç» antes de «a» e «o»: reconheço, reconheça. Também significa admitir: «reconheço que errei».","noteE":"The c becomes ç before a and o: reconheço, reconheça. It also means to admit: reconheço que errei."},
  "reduzir": {"ipa":"rruh-doo-ZEER","ex":"Temos de reduzir os gastos este mês.","exE":"We have to cut our spending this month.","note":"Verbo em -uzir: cai o -e na 3.ª pessoa (ele reduz, como conduz, traduz). Reduzir a indica o resultado (reduzir a pó), reduzir em a quantidade.","noteE":"An -uzir verb: the third person drops the ending (ele reduz, like conduz, traduz). Reduzir a gives the end state (reduzir a pó), reduzir em the amount."},
  "referir": {"ipa":"rruh-fuh-REER","ex":"Não me referi a ti.","exE":"I wasn't referring to you.","note":"Quase sempre reflexo com «a»: referir-se a alguma coisa. O «e» do radical muda para «i» na primeira pessoa: refiro.","noteE":"Usually reflexive with a: referir-se a algo. The stem e changes to i in the first person: refiro."},
  "regressar": {"ipa":"rruh-gruh-SAR","ex":"Regressámos de férias no domingo.","exE":"We got back from holiday on Sunday.","note":"Regressar a um lugar, de um lugar. É de registo neutro ou cuidado; voltar é o equivalente mais coloquial. Pretérito nós regressámos, com acento agudo.","noteE":"Regressar a a place, de a place. Neutral to slightly formal register; voltar is the more colloquial equivalent. Past nós regressámos, with an acute accent."},
  "repetir": {"ipa":"rruh-puh-TEER","ex":"Podes repetir, se faz favor?","exE":"Could you say that again, please?","note":"O «e» do radical muda para «i» na primeira pessoa: repito, repetes, repete. À mesa, «repetir» é servir-se outra vez.","noteE":"The stem e changes to i in the first person: repito, repetes, repete. At the table it means to have a second helping."},
  "representar": {"ipa":"rruh-pruh-zeh (nasal)-TAR","ex":"Esta bandeira representa a cidade.","exE":"This flag represents the city.","note":"Além de simbolizar e falar em nome de alguém, é o verbo do teatro: representar uma peça. Para cinema diz-se antes fazer um papel.","noteE":"Besides symbolising and speaking on someone's behalf, it is the theatre verb: representar uma peça, to act in a play. For film, fazer um papel is more usual."},
  "resolver": {"ipa":"rruh-zol-VEHR","ex":"Já resolvemos o problema do aquecimento.","exE":"We've already sorted out the heating problem.","note":"Além de solucionar, significa decidir: «resolvi ir a pé». O particípio é irregular: resolvido, mas «resolto» não existe.","noteE":"Besides solving, it means to decide: resolvi ir a pé (I decided to walk)."},
  "responder": {"ipa":"rresh-po (nasal)-DEHR","ex":"Ele ainda não respondeu à minha mensagem.","exE":"He still hasn't answered my message.","note":"Pede a preposição «a»: responder a uma pergunta, responder ao professor. Responder a alguém torto significa ser malcriado.","noteE":"It takes the preposition a: responder a uma pergunta. Note that responder torto to someone means to answer back rudely."},
  "resultar": {"ipa":"rruh-zool-TAR","ex":"A ideia não resultou muito bem.","exE":"The idea didn't really work out.","note":"«Resultar em» indica a consequência e «resultar de» a causa. Na fala, «não resultou» quer dizer que não funcionou.","noteE":"Resultar em gives the consequence, resultar de the cause. Colloquially não resultou means it didn't work."},
  "retirar": {"ipa":"rruh-tee-RAR","ex":"Retirei o dinheiro no multibanco.","exE":"I took the money out at the cash machine.","note":"Retirar algo de algum lado; é mais formal do que o corrente tirar. O reflexo retirar-se significa ir-se embora ou reformar-se.","noteE":"Retirar algo de somewhere; it is more formal than everyday tirar. Reflexive retirar-se means to withdraw, leave, or retire."},
  "reunir": {"ipa":"rree-oo-NEER","ex":"A família reúne-se sempre no Natal.","exE":"The family always gets together at Christmas.","note":"Com pessoas usa-se a forma reflexa «reunir-se com». O «u» leva acento quando é tónico: reúno, reúnes, reúne.","noteE":"With people you use reflexive reunir-se com. The u takes an accent when stressed: reúno, reúnes, reúne."},
  "revelar": {"ipa":"rruh-vuh-LAR","ex":"O estudo revelou dados surpreendentes.","exE":"The study revealed surprising figures.","note":"«Revelar-se» significa mostrar ser: a viagem revelou-se cansativa. Também se revelam fotografias analógicas.","noteE":"Revelar-se means to turn out to be: a viagem revelou-se cansativa. It is also the verb for developing photos."},
  "rico": {"ipa":"RREE-koo","ex":"Aquela família é muito rica.","exE":"That family is very rich.","note":"Com \"em\" significa abundante em algo: rico em vitaminas. Concorda: rica, ricos, ricas.","noteE":"With \"em\" it means abundant in something: rico em vitaminas. It agrees: rica, ricos, ricas."},
  "rir-se": {"ipa":"rreer-suh","ex":"Rimo-nos a noite toda.","exE":"We laughed all night.","note":"Pede «de» com aquilo de que se ri, e rir-se de alguém é gozar. Presente irregular: rio, ris, ri, rimos, riem.","noteE":"It takes de for what you laugh at, and rir-se de alguém means to laugh at someone. Irregular present: rio, ris, ri, rimos, riem."},
  "roxo": {"ipa":"RROH-shoo","ex":"As flores do jardim são roxas.","exE":"The flowers in the garden are purple.","note":"Concorda com o nome: roxo, roxa, roxos, roxas, e vem depois do nome. Compostos como roxo-escuro ficam invariáveis.","noteE":"It agrees with the noun (roxo/roxa/roxos/roxas) and follows it. Compound shades such as roxo-escuro or verde-escuro stay invariable."},
  "rápido": {"ipa":"RRAH-pee-doo","ex":"Foi uma viagem rápida de comboio.","exE":"It was a quick train journey.","note":"Como adjetivo concorda: rápida, rápidos, rápidas. Na fala também serve de advérbio invariável, embora o correto seja \"rapidamente\": anda rápido.","noteE":"As an adjective it agrees: rápida, rápidos, rápidas. In speech it also serves as an invariable adverb, though the correct form is \"rapidamente\": anda rápido."},
  "saber": {"ipa":"sah-BER","ex":"Sabes onde fica?","exE":"Do you know where it is?","note":"Saber = saber factos; 'conhecer' = conhecer pessoas/lugares.","noteE":"Saber = to know facts; 'conhecer' = to know people/places."},
  "sair": {"ipa":"sah-EER","ex":"Vou sair esta noite.","exE":"I'm going out tonight.","note":"Sair = to go out/leave; o oposto de 'entrar'.","noteE":"Sair = to go out/leave; the opposite of 'entrar'."},
  "saudável": {"ipa":"sow-DAH-vel","ex":"O pequeno-almoço dele é muito saudável.","exE":"His breakfast is very healthy.","note":"Forma única nos dois géneros, plural \"saudáveis\". Descreve hábitos e alimentos; para a pessoa que não está doente diz-se \"estar bem de saúde\".","noteE":"One form for both genders, plural \"saudáveis\". It describes habits and food; for a person who is not ill say \"estar bem de saúde\"."},
  "se": {"ipa":"suh","ex":"Ela chama-se Marta.","exE":"Her name is Marta.","note":"Além de reflexo, «se» forma construções impessoais: «vende-se», «fala-se inglês». Não confundir com a conjunção «se» (= if).","noteE":"Besides being reflexive, 'se' forms impersonal constructions: 'vende-se', 'fala-se inglês'. Don't confuse it with the conjunction 'se' (if)."},
  "seco": {"ipa":"SAY-koo","ex":"A roupa já está seca.","exE":"The clothes are already dry.","note":"Com \"estar\" descreve o estado; com \"ser\" uma característica, como um vinho seco. Concorda: seca, secos, secas.","noteE":"With \"estar\" it describes a state; with \"ser\" a characteristic, as in um vinho seco. It agrees: seca, secos, secas."},
  "seguir": {"ipa":"suh-GEER","ex":"Segue sempre em frente.","exE":"Keep going straight ahead.","note":"O u desaparece na primeira pessoa: eu sigo. A seguir significa a seguir no tempo, ou seja, depois: a seguir vamos almoçar.","noteE":"The u drops in the first person: eu sigo. The phrase a seguir means next or afterwards: a seguir vamos almoçar."},
  "seguro": {"ipa":"suh-GOO-roo","ex":"Este bairro é muito seguro à noite.","exE":"This neighbourhood is very safe at night.","note":"Com \"ser\" fala de segurança do lugar; com \"estar\" fala de certeza da pessoa: estou seguro disso. Concorda: segura, seguros, seguras.","noteE":"With \"ser\" it refers to a place being safe; with \"estar\" to a person being sure: estou seguro disso. It agrees: segura, seguros, seguras."},
  "sem": {"ipa":"seh (nasal)","ex":"Bebo o café sem açúcar.","exE":"I drink my coffee without sugar.","note":"Seguido de infinitivo traduz o inglês \"without -ing\": saiu sem dizer nada. Não confundir com \"cem\" (100), que se pronuncia quase igual.","noteE":"Before an infinitive it renders English 'without -ing': saiu sem dizer nada. Beware the near-homophone cem ('a hundred') — context does the work."},
  "sempre": {"ipa":"SEH (nasal)-pruh","ex":"Ele chega sempre atrasado.","exE":"He is always late.","note":"Fica normalmente depois do verbo simples e entre o auxiliar e o particípio (tenho sempre feito). No português europeu coloquial pode significar \"afinal\": afinal sempre vou.","noteE":"It normally sits after a simple verb and between auxiliary and participle. In colloquial European Portuguese it can also mean after all, as in sempre vou."},
  "sentar": {"ipa":"seh (nasal)-TAR","ex":"Senta-te aqui ao meu lado.","exE":"Sit here next to me.","note":"Quase sempre reflexo: sentar-se. Para o estado usa-se «estar sentado», não o verbo sozinho.","noteE":"Almost always reflexive: sentar-se. For the state you say estar sentado, not the plain verb."},
  "sentir": {"ipa":"se (nasal)-TEER","ex":"Sinto-me bem.","exE":"I feel well.","note":"'Sentir-se' + adjetivo = to feel …; irregular: 'sinto'.","noteE":"'Sentir-se' + adjective = to feel …; irregular: 'sinto'."},
  "senão": {"ipa":"suh-NOW (nasal)","ex":"Despacha-te, senão perdes o autocarro.","exE":"Hurry up, otherwise you'll miss the bus.","note":"Numa palavra significa \"caso contrário\" ou \"exceto\" e leva indicativo. Separado, \"se não\" é a conjunção se + negação.","noteE":"Written as one word it means otherwise or except and takes the indicative. Split into se não it is simply if plus not."},
  "ser": {"ipa":"sehr","ex":"Eu sou português.","exE":"I am Portuguese.","note":"Ser é permanente: identidade, origem, profissão. Compara com 'estar'.","noteE":"Ser is for permanent things — identity, origin, profession. Contrast with 'estar'."},
  "servir": {"ipa":"suhr-VEER","ex":"Este casaco já não me serve.","exE":"This coat doesn't fit me any more.","note":"Primeira pessoa irregular: eu sirvo. Servir para significa ter uma utilidade, e com pronome significa ficar bem de tamanho.","noteE":"Irregular first person: eu sirvo. Servir para means to be used for something, and with a pronoun it means to fit sizewise."},
  "seu / sua": {"ipa":"sayoo / SOO-ah","ex":"O seu bilhete, por favor.","exE":"Your ticket, please.","note":"Em Portugal, seu/sua é sobretudo o possessivo formal (de você, do senhor). Para dizer dele ou dela, os portugueses preferem o carro dele a o seu carro, para evitar ambiguidade.","noteE":"In Portugal seu/sua is mainly the formal possessive (matching você, o senhor). To say his or her, Portuguese speakers prefer o carro dele over o seu carro, to avoid ambiguity."},
  "si": {"ipa":"see","ex":"Isto é para si, senhora Ana.","exE":"This is for you, Mrs Ana.","note":"Em Portugal «si» é a forma delicada de tratamento depois de preposição, além do reflexo «em si»; com «com» dá «consigo».","noteE":"In Portugal 'si' is the polite 'you' after a preposition, as well as the reflexive 'oneself'; with 'com' it gives 'consigo'."},
  "significar": {"ipa":"seeg-nee-fee-KAR","ex":"O que significa esta palavra?","exE":"What does this word mean?","note":"Antes de «e» escreve-se «qu»: significou, mas signifique. Para perguntar o sentido de algo é mais comum «o que quer dizer».","noteE":"Spelling changes to qu before e: signifique. To ask what something means, o que quer dizer is even more common."},
  "sim": {"ipa":"see (nasal)","ex":"Sim, quero um café, por favor.","exE":"Yes, I'd like a coffee, please.","note":"Em português responde-se muitas vezes repetindo o verbo (\"Queres?\" — \"Quero.\"); \"sim\" sozinho pode soar seco. \"Isso sim\" serve para enfatizar.","noteE":"Portuguese usually answers by repeating the verb, and a bare sim can sound curt. Isso sim adds emphasis."},
  "sob": {"ipa":"sawb","ex":"O gato dormia sob a mesa.","exE":"The cat was sleeping under the table.","note":"É formal e quase só escrito; na fala diz-se \"debaixo de\". Não confundir com \"sobre\", que é quase o contrário e difere numa só letra.","noteE":"Formal and mostly written — in speech people say debaixo de. Do not mix it up with sobre ('about, over'), which is one letter away and nearly the opposite."},
  "sobre": {"ipa":"SOH-bruh","ex":"Falámos sobre o trabalho novo.","exE":"We talked about the new job.","note":"Não confundir com \"sob\" (por baixo), que difere numa só letra. Para assunto pode dizer-se também \"acerca de\"; para posição física, \"em cima de\" é mais natural.","noteE":"For 'about a topic' this is the standard word (or acerca de). For physical 'on top of', em cima de sounds far more natural in speech than sobre."},
  "sobretudo": {"ipa":"soo-bruh-TOO-doo","ex":"Gosto de fruta, sobretudo de laranjas.","exE":"I like fruit, above all oranges.","note":"Escreve-se numa só palavra e destaca o elemento mais importante da lista. Não confundir com o nome \"sobretudo\", que é uma peça de roupa.","noteE":"It is written as one word and singles out the most important item in a list. Do not confuse it with the noun sobretudo, meaning an overcoat."},
  "sofrer": {"ipa":"soo-FREHR","ex":"O meu avô sofre de dores nas costas.","exE":"My grandfather suffers from back pain.","note":"Pede «de» para doenças (sofrer de asma) e «com» para situações (sofrer com o calor).","noteE":"Use de for illnesses (sofrer de asma) and com for situations (sofrer com o calor)."},
  "sonhar": {"ipa":"soo-NYAR","ex":"Sonhei contigo esta noite.","exE":"I dreamt about you last night.","note":"Sonhar COM alguém ou algo (com + tu dá contigo); sonhar em + infinitivo exprime uma aspiração. Nunca se diz «sonhar de».","noteE":"Sonhar COM someone or something (com + tu gives contigo); sonhar em + infinitive expresses an aspiration. Never 'sonhar de'."},
  "sorrir": {"ipa":"soo-RREER","ex":"Ela sorriu-me quando entrei.","exE":"She smiled at me when I came in.","note":"Conjuga-se como rir: eu sorrio, tu sorris, ele sorri, eles sorriem. Sorri-se a ou para alguém, com pronome enclítico (sorriu-me).","noteE":"Conjugated like rir: eu sorrio, tu sorris, ele sorri, eles sorriem. You smile a or para someone, with the pronoun attached (sorriu-me)."},
  "suave": {"ipa":"SWAH-vuh","ex":"Esta manteiga tem um sabor suave.","exE":"This butter has a mild flavour.","note":"Forma única nos dois géneros, plural \"suaves\". Serve para texturas, sabores, sons e luz, sempre com ideia de delicadeza.","noteE":"One form for both genders, plural \"suaves\". It works for textures, tastes, sounds and light, always with a sense of gentleness."},
  "subir": {"ipa":"soo-BEER","ex":"Subimos as escadas a correr.","exE":"We ran up the stairs.","note":"No presente o «u» abre para «o»: subo, sobes, sobe, subimos, sobem. O contrário é «descer».","noteE":"In the present the u opens to o: subo, sobes, sobe, subimos, sobem. The opposite is descer."},
  "substituir": {"ipa":"soobsh-tee-TWEER","ex":"Vou substituir o colega amanhã.","exE":"I'm standing in for my colleague tomorrow.","note":"Substituir algo POR outra coisa (substituí o velho pelo novo). Verbo em -uir: eu substituo, ele substitui, com acento em substituí.","noteE":"Substituir something POR something else (substituí o velho pelo novo). An -uir verb: eu substituo, ele substitui, with an accent in substituí."},
  "suficiente": {"ipa":"soo-fee-see-EH (nasal)-tuh","ex":"Não tenho dinheiro suficiente.","exE":"I don't have enough money.","note":"Vem depois do nome (tempo suficiente) e faz plural \"suficientes\". O advérbio é \"suficientemente\" e \"o suficiente\" funciona como nome.","noteE":"It follows the noun and pluralises to suficientes. The adverb is suficientemente, and o suficiente works as a noun."},
  "sujo": {"ipa":"SOO-zhoo","ex":"Tens as mãos sujas, vai lavá-las.","exE":"Your hands are dirty, go and wash them.","note":"Vem depois do nome e concorda: suja, sujos, sujas. Combina quase sempre com \"estar\", porque é uma condição temporária.","noteE":"It follows the noun and agrees: suja, sujos, sujas. It almost always pairs with \"estar\", as it is a temporary condition."},
  "surgir": {"ipa":"soor-ZHEER","ex":"Surgiu um problema com o comboio.","exE":"A problem came up with the train.","note":"O g passa a j antes de a e o: eu surjo. É mais formal do que aparecer e usa-se sobretudo com coisas, não com pessoas.","noteE":"The g becomes j before a and o: eu surjo. It is more formal than aparecer and is used mainly with things rather than people."},
  "só / apenas": {"ipa":"saw / ah-PAY-nush","ex":"Só tenho cinco minutos, apenas isso.","exE":"I only have five minutes, just that.","note":"Coloca-se logo antes do elemento que limita, porque muda o sentido da frase. \"Apenas\" é mais formal ou escrito; \"só\" também significa sozinho e aí concorda (sós).","noteE":"Place it immediately before the element it limits, since position changes the meaning. Apenas is more formal, and só can also mean alone, agreeing as sós."},
  "talvez": {"ipa":"tahl-VAYSH","ex":"Talvez venha jantar connosco.","exE":"Maybe he'll come to dinner with us.","note":"Antes do verbo obriga ao conjuntivo (talvez seja, talvez venha); depois do verbo usa-se o indicativo (ele vem, talvez).","noteE":"Before the verb it forces the subjunctive, as in talvez seja. Placed after the verb, the indicative is used instead."},
  "também": {"ipa":"tah (nasal)-BEH (nasal)","ex":"Eu também quero ir convosco.","exE":"I also want to go with you.","note":"Vem depois do sujeito ou no fim da frase. Na negativa usa-se \"também não\" (Eu também não vou), nunca \"também\" sozinho.","noteE":"It follows the subject or closes the sentence. The negative counterpart is também não, as in eu também não vou."},
  "tanto": {"ipa":"TAN (nasal)-too","ex":"Nunca comi tanto na minha vida.","exE":"I have never eaten so much in my life.","note":"Usa-se com verbos e nomes; com adjetivos e advérbios usa-se \"tão\". Como determinante concorda (tantas pessoas) e \"tanto... como\" exprime igualdade.","noteE":"It goes with verbs and nouns, while tão goes with adjectives and adverbs. As a determiner it agrees, and tanto... como expresses equality."},
  "tanto… como…": {"ipa":"TAN (nasal)-too ... KOH-moo","ex":"Tanto eu como o meu irmão fomos à festa.","exE":"Both my brother and I went to the party.","note":"Liga dois elementos com igual peso e o verbo vai normalmente ao plural. Também exprime comparação de igualdade: tanto trabalho como tu.","noteE":"It links two elements of equal weight and the verb usually goes plural. It also expresses comparison of equality, as in tanto trabalho como tu."},
  "tarde": {"ipa":"TAR-duh","ex":"Cheguei tarde ao trabalho.","exE":"I arrived late to work.","note":"Como advérbio fica depois do verbo; como nome feminino significa o período da tarde (boa tarde). Para uma pessoa atrasada diz-se \"atrasado\".","noteE":"As an adverb it follows the verb; as a feminine noun it means the afternoon. A person who is late is atrasado, not tarde."},
  "te": {"ipa":"tuh","ex":"Telefono-te amanhã de manhã.","exE":"I'll call you tomorrow morning.","note":"«Te» só combina com «tu». Se tratar a pessoa por «o senhor» ou «você», use «lhe» ou «o/a».","noteE":"'Te' only goes with 'tu'. If you address someone as 'o senhor' or 'você', use 'lhe' or 'o/a' instead."},
  "tentar": {"ipa":"teh (nasal)-TAR","ex":"Vou tentar outra vez amanhã.","exE":"I'll try again tomorrow.","note":"Liga-se ao infinitivo sem preposição: tentei abrir a porta. A alternativa formal é procurar; experimentar é testar algo para ver como é.","noteE":"It links to the infinitive with no preposition: tentei abrir a porta. The formal alternative is procurar; experimentar means to try something out to see what it is like."},
  "ter": {"ipa":"tehr","ex":"Tenho dois irmãos.","exE":"I have two brothers.","note":"Também exprime idade e sensações: 'ter fome', 'ter 30 anos'.","noteE":"Also used for age and feelings: 'ter fome' (be hungry), 'ter 30 anos' (be 30)."},
  "terminar": {"ipa":"tuhr-mee-NAR","ex":"O filme termina daqui a dez minutos.","exE":"The film ends in ten minutes.","note":"«Acabar» é mais usado na fala. «Terminar com alguém» significa acabar uma relação amorosa.","noteE":"Acabar is commoner in speech. Terminar com alguém means to break up with someone."},
  "terrível": {"ipa":"tuh-RREE-vel","ex":"Tive uma dor de cabeça terrível.","exE":"I had a terrible headache.","note":"Forma única nos dois géneros, plural \"terríveis\". Antes do nome soa mais dramático e literário: um terrível acidente.","noteE":"One form for both genders, plural \"terríveis\". Before the noun it sounds more dramatic and literary: um terrível acidente."},
  "teu / tua": {"ipa":"tayoo / TOO-ah","ex":"O teu telemóvel está em cima da mesa.","exE":"Your phone is on the table.","note":"Usa-se só com o tratamento por tu e concorda com a coisa possuída, não com o dono. Em Portugal leva quase sempre artigo: o teu carro, a tua casa.","noteE":"Only used with the informal tu, and it agrees with the thing owned, not the owner. In Portugal it almost always takes the article: o teu carro, a tua casa."},
  "ti": {"ipa":"tee","ex":"Trouxe um presente para ti.","exE":"I brought a present for you.","note":"Forma de «tu» depois de preposição; com «com» dá «contigo».","noteE":"The form of 'tu' after prepositions; with 'com' it becomes 'contigo'."},
  "tirar": {"ipa":"tee-RAR","ex":"Podes tirar os sapatos à entrada.","exE":"You can take your shoes off at the entrance.","note":"Usa-se em muitas expressões: tirar fotografias, tirar dúvidas, tirar um curso e tirar dinheiro do multibanco.","noteE":"It appears in many set phrases: tirar fotografias (take photos), tirar dúvidas (clear up doubts), tirar um curso (do a degree), tirar dinheiro (withdraw money)."},
  "tocar": {"ipa":"too-KAR","ex":"Ela toca piano desde pequena.","exE":"She has played the piano since she was little.","note":"Com instrumentos usa-se sem preposição, mas «tocar em» é encostar a mão. É também o verbo do telemóvel e da campainha a tocar.","noteE":"With instruments there is no preposition, but tocar em means to touch physically. It is also the verb for a phone or doorbell ringing."},
  "todo / toda": {"ipa":"TOH-doo / TOH-dah","ex":"Estudei toda a tarde.","exE":"I studied all afternoon.","note":"No singular com artigo significa inteiro (todo o dia, o dia inteiro); no plural significa cada um (todos os dias, cada dia). Todo o mundo em Portugal é o planeta, não as pessoas.","noteE":"In the singular with an article it means whole (todo o dia, the whole day); in the plural it means every (todos os dias, every day). In Portugal todo o mundo means the whole planet, not everybody."},
  "tomar": {"ipa":"too-MAR","ex":"Tomo café ao pequeno-almoço.","exE":"I have coffee with breakfast.","note":"É o verbo normal para bebidas e medicamentos (tomar um chá, tomar um comprimido) e para tomar banho. Tomar conta de significa cuidar de alguém.","noteE":"It is the normal verb for drinks and medicine (tomar um chá, tomar um comprimido) and for taking a bath or shower. Tomar conta de means to look after someone."},
  "tornar-se": {"ipa":"toor-NAR-suh","ex":"Ele tornou-se médico aos trinta anos.","exE":"He became a doctor at thirty.","note":"É pronominal e liga-se diretamente ao nome ou adjetivo, sem preposição. Alternativas na fala corrente são ficar e passar a ser.","noteE":"It is pronominal and links straight to a noun or adjective, with no preposition. Everyday alternatives are ficar and passar a ser."},
  "trabalhar": {"ipa":"trah-bah-LYAR","ex":"Ela trabalha num café no Porto.","exE":"She works in a café in Porto.","note":"Pede em para o local ou a área, para para o empregador e com para os colegas: trabalho numa escola, trabalho para uma empresa.","noteE":"It takes em for the place or field, para for the employer and com for colleagues: trabalho numa escola, trabalho para uma empresa."},
  "transformar": {"ipa":"trah (nasal)sh-foor-MAR","ex":"Transformaram a garagem num escritório.","exE":"They turned the garage into an office.","note":"Pede «em» com o resultado da mudança. Na forma reflexa, «transformar-se em» é tornar-se outra coisa.","noteE":"It takes em for the result of the change. Reflexive transformar-se em means to turn into something else."},
  "tratar": {"ipa":"trah-TAR","ex":"Esta reunião trata do orçamento.","exE":"This meeting deals with the budget.","note":"Tratar de significa ocupar-se de um assunto; sem preposição significa dar tratamento médico. Tratar por tu é passar ao registo informal com alguém.","noteE":"Tratar de means to deal with a matter; with no preposition it means to treat medically. Tratar por tu is to switch to informal address with someone."},
  "trazer": {"ipa":"trah-ZEHR","ex":"Trouxe-te um bolo da pastelaria.","exE":"I brought you a cake from the bakery.","note":"Muito irregular: trago no presente e trouxe no pretérito, com x lido como s. Opõe-se a levar, que é afastar do falante.","noteE":"Highly irregular: trago in the present and trouxe in the past, where the x sounds like s. It contrasts with levar, which moves things away from the speaker."},
  "triste": {"ipa":"TREESH-tuh","ex":"Ela ficou triste com a notícia.","exE":"She got sad at the news.","note":"Não muda no feminino; só acrescenta \"-s\" no plural: tristes. Diz-se \"estar triste\" para o momento e \"ser triste\" para algo que causa tristeza: é um filme triste.","noteE":"It does not change in the feminine, only adding \"-s\" in the plural: tristes. Use \"estar triste\" for the moment and \"ser triste\" for something that causes sadness: é um filme triste."},
  "tu": {"ipa":"too","ex":"Tu queres um café?","exE":"Do you want a coffee?","note":"Em Portugal «tu» é a forma informal normal com amigos e família, ao contrário do Brasil. O verbo leva sempre -s: tu queres, tu tens.","noteE":"In Portugal 'tu' is the standard informal you with friends and family, unlike Brazil. Its verb form always ends in -s: tu queres."},
  "tudo": {"ipa":"TOO-doo","ex":"Está tudo bem contigo?","exE":"Is everything all right with you?","note":"Neutro e invariável, para coisas em bloco; para pessoas ou coisas contáveis usa-se todos: tudo está pronto, mas todos chegaram.","noteE":"Neuter and invariable, for things taken as a whole; for people or countable things use todos: tudo está pronto, but todos chegaram."},
  "tudo bem?": {"ipa":"TOO-doo beh (nasal)","ex":"— Tudo bem? — Tudo, e tu?","exE":"— How's it going? — Good, and you?","note":"Serve de pergunta e de resposta: 'Tudo bem?' — 'Tudo bem.'","noteE":"Works as both the question and the answer: 'All good?' — 'All good.'"},
  "tão": {"ipa":"tow (nasal)","ex":"Ela é tão simpática!","exE":"She is so nice!","note":"Só antes de adjetivos e advérbios, nunca antes de nomes (aí é \"tanto\"). \"Tão... como\" compara em igualdade e \"tão... que\" exprime consequência.","noteE":"It only precedes adjectives and adverbs, never nouns, where tanto is used. Tão... como compares equals and tão... que expresses result."},
  "um": {"ipa":"oo (nasal)","ex":"Quero um café, se faz favor.","exE":"I'd like a coffee, please.","note":"\"Um\" é também o número um, por isso o contexto decide. Omite-se depois de \"ser\" com profissões: \"Ele é médico\", não \"é um médico\".","noteE":"Same word as the number 'one'. Drop it after ser with jobs: Ele é médico ('He is a doctor') — adding um sounds wrong unless you add a description."},
  "uma": {"ipa":"OO-mah","ex":"Vive numa casa muito antiga.","exE":"She lives in a very old house.","note":"Com \"em\" e \"de\" contrai obrigatoriamente: numa, duma. A forma \"em uma\" é brasileira e soa estranha em Portugal.","noteE":"Contracts with em and de: numa, duma. The uncontracted em uma is Brazilian and sounds odd in Portugal."},
  "umas": {"ipa":"OO-mash","ex":"Faltam umas semanas para as férias.","exE":"There are a few weeks left until the holidays.","note":"É o plural de \"uma\" e concorda em género com o substantivo: umas horas, uns dias. Não confundir com \"algumas\", que é mais preciso e menos vago.","noteE":"The feminine plural of um. It is vaguer than algumas ('some, a certain number'), so umas horas is 'a few hours' rather than a counted amount."},
  "uns": {"ipa":"oosh (nasal)","ex":"Comprei uns livros na feira.","exE":"I bought some books at the market.","note":"Antes de números significa \"aproximadamente\": \"uns vinte euros\" quer dizer cerca de vinte euros.","noteE":"Before a number it means 'roughly': uns vinte euros = about twenty euros. That approximating use is very common in speech."},
  "usar": {"ipa":"oo-ZAR","ex":"Uso óculos para ler.","exE":"I wear glasses for reading.","note":"Além de utilizar, é o verbo normal para vestuário e acessórios: usar casaco, usar anel. Usar de é raro e formal.","noteE":"Besides using, it is the normal verb for clothes and accessories: usar casaco, usar anel. Usar de is rare and formal."},
  "utilizar": {"ipa":"oo-tee-lee-ZAR","ex":"Utilizo o telemóvel para tudo.","exE":"I use my mobile for everything.","note":"É mais formal do que «usar», comum em textos escritos e instruções. Antes de «e» escreve-se «c»: utilizei, mas utilize.","noteE":"More formal than usar and common in writing and instructions. Spelling: utilize (z becomes c before e in the subjunctive)."},
  "valer": {"ipa":"vah-LEHR","ex":"Vale a pena visitar o castelo.","exE":"It's worth visiting the castle.","note":"Irregular na primeira pessoa: «valho». A expressão «valer a pena» é muito frequente e concorda com o sujeito: valem a pena.","noteE":"Irregular first person: valho. The phrase valer a pena (to be worth it) is very common and agrees with the subject."},
  "velho": {"ipa":"VEH-lyoo","ex":"O meu telemóvel já está muito velho.","exE":"My mobile phone is already very old.","note":"Depois do nome descreve a idade (um carro velho); antes do nome sugere afeto ou antiguidade da relação (um velho amigo). Concorda: velha, velhos, velhas.","noteE":"After the noun it describes age (um carro velho); before the noun it suggests affection or a long-standing relationship (um velho amigo). It agrees: velha, velhos, velhas."},
  "vencer": {"ipa":"veh (nasal)-SEHR","ex":"A nossa equipa venceu por dois a zero.","exE":"Our team won two-nil.","note":"O «c» passa a «ç» antes de «a» e «o»: venço, vença. Também significa expirar: o prazo venceu ontem.","noteE":"The c becomes ç before a and o: venço, vença. It also means to expire: o prazo venceu ontem."},
  "vender": {"ipa":"veh (nasal)-DEHR","ex":"Vendemos o carro por dois mil euros.","exE":"We sold the car for two thousand euros.","note":"O preço vai com «por»: vender por cem euros. «Vende-se» nos anúncios é a forma passiva impessoal.","noteE":"The price takes por: vender por cem euros. Vende-se on signs is the impersonal passive (for sale)."},
  "ver": {"ipa":"vehr","ex":"Vejo-te amanhã.","exE":"I'll see you tomorrow.","note":"Ver = see/watch; 'olhar' = to look at.","noteE":"Ver = to see/watch; 'olhar' = to look at."},
  "verde": {"ipa":"VAYR-duh","ex":"O semáforo já está verde.","exE":"The traffic light is green now.","note":"Forma única nos dois géneros, plural \"verdes\". Aplicado a fruta significa que ainda não está madura.","noteE":"One form for both genders, plural \"verdes\". Applied to fruit it means not yet ripe."},
  "verificar": {"ipa":"vuh-ree-fee-KAR","ex":"Vou verificar o horário do comboio.","exE":"I'm going to check the train timetable.","note":"Verificar é conferir dados ou factos; para «ver se está tudo bem» diz-se antes ver ou confirmar. Verificar-se significa acontecer ou confirmar-se.","noteE":"Verificar is to check data or facts; for a casual 'have a look' Portuguese prefers ver or confirmar. Verificar-se means to occur or turn out to be true."},
  "vermelho": {"ipa":"vuhr-MAY-lyoo","ex":"Prefiro vinho vermelho ao branco.","exE":"I prefer red wine to white.","note":"Concorda: vermelha, vermelhos, vermelhas. Para o vinho, os portugueses dizem antes \"vinho tinto\".","noteE":"It agrees: vermelha, vermelhos, vermelhas. For wine, the Portuguese say \"vinho tinto\" instead."},
  "vir": {"ipa":"veer","ex":"Vem cá!","exE":"Come here!","note":"Irregular; não confundir com 'ver' (to see).","noteE":"Irregular; don't confuse with 'ver' (to see)."},
  "virar": {"ipa":"vee-RAR","ex":"Vira à direita depois do semáforo.","exE":"Turn right after the traffic lights.","note":"Nas direções usa-se «virar à direita/à esquerda», com crase. «Virar-se» é voltar-se para outro lado.","noteE":"For directions you say virar à direita/à esquerda. Virar-se means to turn yourself around."},
  "viver": {"ipa":"vee-VER","ex":"Vivo em Lisboa.","exE":"I live in Lisbon.","note":"'Viver' = to live; 'morar' = to reside (mais específico).","noteE":"'Viver' = to live; 'morar' = to reside (more specific)."},
  "você": {"ipa":"vaw-SAY","ex":"Você já almoçou?","exE":"Have you had lunch?","note":"Cuidado: em Portugal «você» pode soar distante ou até malcriado com desconhecidos ou pessoas mais velhas; prefira «o senhor / a senhora» ou o verbo na 3.ª pessoa.","noteE":"Careful: in Portugal 'você' can sound distant or even rude with strangers or older people. Use 'o senhor / a senhora', or just the third-person verb."},
  "vocês": {"ipa":"vaw-SAYSH","ex":"Vocês querem sobremesa?","exE":"Do you (all) want dessert?","note":"É o plural normal de «tu» e de «você» em Portugal; «vós» só sobrevive em textos antigos, na liturgia e nalguns dialetos do Norte.","noteE":"This is the normal plural of both 'tu' and 'você' in Portugal; 'vós' survives only in old texts, liturgy and some northern dialects."},
  "voltar": {"ipa":"vol-TAR","ex":"Volto já.","exE":"I'll be right back.","note":"'Voltar' = to come/go back; 'volto já' = back in a moment.","noteE":"'Voltar' = to come/go back; 'volto já' = back in a moment."},
  "vos": {"ipa":"voosh","ex":"Escrevo-vos amanhã.","exE":"I'll write to you all tomorrow.","note":"Embora «vós» já não se use como sujeito, «vos» sobrevive como objeto de «vocês»; em alternativa diz-se «a vocês».","noteE":"Although 'vós' is no longer used as a subject, 'vos' survives as the object form for 'vocês'; the alternative is 'a vocês'."},
  "vosso / vossa": {"ipa":"VAW-soo / VAW-sah","ex":"O vosso quarto é no primeiro andar.","exE":"Your room is on the first floor.","note":"Em Portugal usa-se normalmente vosso com vocês, embora o verbo vá na terceira pessoa do plural: vocês trouxeram o vosso carro? No Brasil isto soa arcaico.","noteE":"In Portugal vosso is the normal possessive for vocês, even though the verb stays in the third person plural: vocês trouxeram o vosso carro? In Brazil this sounds archaic."},
  "à frente": {"ipa":"ah FREH (nasal)-tuh","ex":"O carro está à frente da casa.","exE":"The car is in front of the house.","note":"Liga-se com \"de\": à frente de mim, à frente do prédio. Não confundir com \"em frente\", que significa em linha reta ou do lado oposto.","noteE":"It links with de, as in à frente de mim. Keep it apart from em frente, which means straight ahead or opposite."},
  "às vezes": {"ipa":"ahsh VAY-zush","ex":"Às vezes janto fora com amigos.","exE":"Sometimes I have dinner out with friends.","note":"Escreve-se sempre com crase no \"às\". Da mesma família: muitas vezes, poucas vezes e \"de vez em quando\".","noteE":"The à always carries its grave accent. Related frequency phrases are muitas vezes, poucas vezes and de vez em quando."},
  "áspero": {"ipa":"AHSH-puh-roo","ex":"Esta toalha é áspera demais.","exE":"This towel is too rough.","note":"Aplica-se sobretudo a texturas e à pele; para uma superfície irregular diz-se \"irregular\". Concorda: áspera, ásperos, ásperas.","noteE":"It applies mainly to textures and skin; for an uneven surface say \"irregular\". It agrees: áspera, ásperos, ásperas."},
  "ótimo": {"ipa":"AW-tee-moo","ex":"O jantar estava ótimo, obrigado.","exE":"The dinner was great, thank you.","note":"É o superlativo de \"bom\", por isso não se diz \"muito ótimo\". Concorda em género e número: ótima, ótimos, ótimas.","noteE":"It is the superlative of \"bom\", so you never say \"muito ótimo\". It agrees in gender and number: ótima, ótimos, ótimas."},
  "último": {"ipa":"OOL-tee-moo","ex":"Este é o último autocarro para Lisboa.","exE":"This is the last bus to Lisbon.","note":"Vai antes do nome e leva quase sempre artigo definido: o último dia. Concorda em género e número: última, últimos, últimas.","noteE":"It goes before the noun and almost always takes a definite article: o último dia. It agrees in gender and number: última, últimos, últimas."},
};
